/**
 * The RoveHQ agreement's second language for businesses outside Thailand (generated from translation drafts; edit
 * here). lib/contract-templates/default-en.html is written in English and Thai; each entry below is one Thai text of
 * that file (a clause or a label) with the same text in the other languages RoveHQ supports. lib/agreement-language.ts
 * swaps them in when the agreement is rendered (lib/agreement-localize.ts). Keys must match the template's Thai exactly (a key that no longer
 * matches leaves that text English only): scripts/check-agreement-languages.cjs reports any that don't.
 *
 * Drafted from the English and Thai wording, not reviewed by a lawyer in each country.
 */

import type { SecondLanguage } from "@/lib/agreement-language";

export type SecondLanguageEntry = { th: string } & Record<SecondLanguage, string>;

/** The bilingual clauses (the <div class="lang-th"> blocks), in template order. */
export const AGREEMENT_CLAUSES: SecondLanguageEntry[] = [
  {"th":"สัญญานี้ทำขึ้นเมื่อวันที่ {{contract_date}} ระหว่างผู้ให้เช่าและผู้เช่าที่ระบุไว้ข้างต้น ผู้เช่ายอมรับความรับผิดชอบต่อยานพาหนะและภาระผูกพันทั้งหมดตามสัญญานี้","id":"Perjanjian ini dibuat pada tanggal {{contract_date}} antara Pemilik dan Penyewa yang disebut di atas. Penyewa menerima tanggung jawab atas kendaraan dan seluruh kewajiban dalam perjanjian ini.","vi":"Hợp đồng này được lập ngày {{contract_date}} giữa Bên cho thuê và Bên thuê nêu trên. Bên thuê chịu trách nhiệm đối với xe và mọi nghĩa vụ trong hợp đồng này.","ms":"Perjanjian ini dibuat pada {{contract_date}} antara Pemilik dan Penyewa yang dinamakan di atas. Penyewa menerima tanggungjawab ke atas kenderaan dan semua kewajipan dalam perjanjian ini.","fil":"Ang kasunduang ito ay ginawa noong {{contract_date}} sa pagitan ng May-ari at ng Umuupa na nakapangalan sa itaas. Tinatanggap ng Umuupa ang pananagutan sa sasakyan at sa lahat ng obligasyon sa kasunduang ito.","lo":"ສັນຍານີ້ເຮັດຂຶ້ນໃນວັນທີ {{contract_date}} ລະຫວ່າງຜູ້ໃຫ້ເຊົ່າ ແລະ ຜູ້ເຊົ່າທີ່ລະບຸໄວ້ຂ້າງເທິງ. ຜູ້ເຊົ່າຍອມຮັບຜິດຊອບຕໍ່ຍານພາຫະນະ ແລະ ພັນທະທັງໝົດຕາມສັນຍານີ້.","km":"កិច្ចសន្យានេះធ្វើឡើងនៅថ្ងៃទី {{contract_date}} រវាងអ្នកឲ្យជួល និងអ្នកជួលដែលមានឈ្មោះខាងលើ។ អ្នកជួលទទួលខុសត្រូវចំពោះយានយន្ត និងកាតព្វកិច្ចទាំងអស់ក្នុងកិច្ចសន្យានេះ។","el":"Η παρούσα σύμβαση συνάπτεται στις {{contract_date}} μεταξύ του Εκμισθωτή και του Μισθωτή που αναφέρονται παραπάνω. Ο Μισθωτής αναλαμβάνει την ευθύνη για το όχημα και όλες τις υποχρεώσεις της παρούσας σύμβασης.","es":"El presente contrato se celebra el {{contract_date}} entre el Propietario y el Arrendatario arriba identificados. El Arrendatario asume la responsabilidad sobre el vehículo y todas las obligaciones de este contrato.","pt":"O presente contrato é celebrado em {{contract_date}} entre o Locador e o Locatário acima identificados. O Locatário assume a responsabilidade pelo veículo e por todas as obrigações deste contrato.","it":"Il presente contratto è stipulato il {{contract_date}} tra il Locatore e il Conduttore sopra indicati. Il Conduttore assume la responsabilità del veicolo e di tutti gli obblighi del presente contratto.","hr":"Ovaj ugovor sklapa se dana {{contract_date}} između gore navedenog Najmodavca i Najmoprimca. Najmoprimac preuzima odgovornost za vozilo i sve obveze iz ovog ugovora.","fr":"Le présent contrat est conclu le {{contract_date}} entre le Loueur et le Locataire désignés ci-dessus. Le Locataire assume la responsabilité du véhicule et de toutes les obligations du présent contrat.","de":"Dieser Vertrag wird am {{contract_date}} zwischen dem oben genannten Vermieter und dem Mieter geschlossen. Der Mieter übernimmt die Verantwortung für das Fahrzeug und alle Pflichten aus diesem Vertrag.","tr":"İşbu sözleşme {{contract_date}} tarihinde, yukarıda bilgileri yer alan Kiraya Veren ile Kiracı arasında akdedilmiştir. Kiracı, araçla ilgili sorumluluğu ve işbu sözleşmeden doğan tüm yükümlülükleri üstlenir."},
  {"th":"ผู้ให้เช่าให้เช่ายานพาหนะตามรายละเอียดข้างต้นแก่ผู้เช่า ตามระยะเวลาเช่าและเงื่อนไขที่ระบุในสัญญานี้","id":"Pemilik menyewakan kendaraan yang dijelaskan di atas kepada Penyewa untuk masa sewa dan dengan ketentuan yang tercantum dalam perjanjian ini.","vi":"Bên cho thuê cho Bên thuê thuê chiếc xe nêu trên trong thời hạn thuê và theo các điều khoản ghi trong hợp đồng này.","ms":"Pemilik menyewakan kenderaan yang diterangkan di atas kepada Penyewa bagi tempoh sewa dan mengikut terma yang dinyatakan dalam perjanjian ini.","fil":"Pinauupahan ng May-ari ang sasakyang inilarawan sa itaas sa Umuupa para sa panahon ng upa at ayon sa mga tuntuning nakasaad sa kasunduang ito.","lo":"ຜູ້ໃຫ້ເຊົ່າໃຫ້ຜູ້ເຊົ່າເຊົ່າຍານພາຫະນະຕາມລາຍລະອຽດຂ້າງເທິງ ຕາມໄລຍະເວລາເຊົ່າ ແລະ ເງື່ອນໄຂທີ່ລະບຸໄວ້ໃນສັນຍານີ້.","km":"អ្នកឲ្យជួលជួលយានយន្តដែលបានរៀបរាប់ខាងលើឲ្យអ្នកជួល សម្រាប់រយៈពេលជួល និងតាមលក្ខខណ្ឌដែលមានចែងក្នុងកិច្ចសន្យានេះ។","el":"Ο Εκμισθωτής εκμισθώνει στον Μισθωτή το όχημα που περιγράφεται παραπάνω για τη διάρκεια της μίσθωσης και με τους όρους της παρούσας σύμβασης.","es":"El Propietario alquila al Arrendatario el vehículo descrito arriba durante el periodo de alquiler y en las condiciones establecidas en este contrato.","pt":"O Locador aluga ao Locatário o veículo acima descrito pelo período de aluguer e nas condições previstas neste contrato.","it":"Il Locatore concede in noleggio al Conduttore il veicolo sopra descritto per il periodo di noleggio e alle condizioni del presente contratto.","hr":"Najmodavac daje Najmoprimcu u najam gore opisano vozilo za razdoblje najma i pod uvjetima iz ovog ugovora.","fr":"Le Loueur loue au Locataire le véhicule décrit ci-dessus pour la durée de location et aux conditions prévues au présent contrat.","de":"Der Vermieter vermietet dem Mieter das oben beschriebene Fahrzeug für die Mietdauer und zu den Bedingungen dieses Vertrags.","tr":"Kiraya Veren, yukarıda tanımlanan aracı işbu sözleşmede belirtilen kiralama süresi boyunca ve belirtilen şartlarla Kiracıya kiralar."},
  {"th":"ผู้เช่ายืนยันว่าได้รับยานพาหนะในสภาพใช้งานได้ดี เว้นแต่ความเสียหาย รอยตำหนิ รายการขาดหาย ระดับน้ำมัน หรือเลขไมล์ที่บันทึกไว้ในรายงานตรวจรับรถหรือภาคผนวก ก.","id":"Penyewa menyatakan bahwa kendaraan diterima dalam kondisi baik dan berfungsi, kecuali kerusakan, goresan, barang yang hilang, tingkat bahan bakar atau jarak tempuh yang dicatat dalam laporan pemeriksaan serah terima.","vi":"Bên thuê xác nhận đã nhận xe trong tình trạng hoạt động tốt, trừ các hư hỏng, vết trầy, vật dụng bị thiếu, mức nhiên liệu hoặc số km đã được ghi trong biên bản kiểm tra khi giao xe.","ms":"Penyewa mengesahkan bahawa kenderaan diterima dalam keadaan baik dan berfungsi kecuali sebarang kerosakan, calar, barang yang hilang, paras bahan api atau perbatuan yang direkodkan dalam laporan pemeriksaan serahan.","fil":"Kinukumpirma ng Umuupa na natanggap niya ang sasakyan na nasa maayos na kondisyon maliban sa anumang sira, gasgas, nawawalang gamit, antas ng panggatong o mileage na nakatala sa ulat ng inspeksyon sa paghahatid.","lo":"ຜູ້ເຊົ່າຢືນຢັນວ່າໄດ້ຮັບຍານພາຫະນະໃນສະພາບໃຊ້ງານໄດ້ດີ ຍົກເວັ້ນຄວາມເສຍຫາຍ, ຮອຍຂີດຂ່ວນ, ສິ່ງຂອງທີ່ຂາດ, ລະດັບນ້ຳມັນ ຫຼື ເລກໄມທີ່ບັນທຶກໄວ້ໃນບົດລາຍງານກວດຮັບລົດ.","km":"អ្នកជួលបញ្ជាក់ថាបានទទួលយានយន្តក្នុងស្ថានភាពល្អ លើកលែងតែការខូចខាត ស្នាមឆ្កូត របស់ដែលបាត់ កម្រិតឥន្ធនៈ ឬចម្ងាយដែលបានកត់ត្រាក្នុងរបាយការណ៍ត្រួតពិនិត្យពេលប្រគល់។","el":"Ο Μισθωτής βεβαιώνει ότι παραλαμβάνει το όχημα σε καλή κατάσταση λειτουργίας, εκτός από τις ζημιές, τα σημάδια, τα ελλείποντα αντικείμενα, τη στάθμη καυσίμου ή τα χιλιόμετρα που καταγράφονται στην έκθεση ελέγχου παράδοσης.","es":"El Arrendatario confirma que recibe el vehículo en buen estado de funcionamiento, salvo los daños, marcas, elementos que falten, nivel de combustible o kilometraje anotados en el informe de inspección de entrega.","pt":"O Locatário confirma que recebe o veículo em bom estado de funcionamento, salvo os danos, marcas, objetos em falta, nível de combustível ou quilometragem registados no relatório de inspeção de entrega.","it":"Il Conduttore conferma di ricevere il veicolo in buono stato di funzionamento, salvo i danni, i segni, gli oggetti mancanti, il livello di carburante o il chilometraggio annotati nel verbale di consegna.","hr":"Najmoprimac potvrđuje da je vozilo primio u dobrom i ispravnom stanju, osim oštećenja, tragova, nedostajućih dijelova, razine goriva ili kilometraže zabilježenih u zapisniku o primopredaji.","fr":"Le Locataire confirme recevoir le véhicule en bon état de marche, sous réserve des dommages, marques, éléments manquants, niveau de carburant ou kilométrage notés dans l'état des lieux de départ.","de":"Der Mieter bestätigt, das Fahrzeug in gutem, betriebsbereitem Zustand erhalten zu haben, abgesehen von den im Übergabeprotokoll festgehaltenen Schäden, Gebrauchsspuren, fehlenden Teilen, dem Tankstand und dem Kilometerstand.","tr":"Kiracı, teslim kontrol raporunda kaydedilen hasar, iz, eksik parça, yakıt seviyesi ve kilometre dışında aracı çalışır ve iyi durumda teslim aldığını beyan eder."},
  {"th":"ผู้เช่ายืนยันว่ามีใบอนุญาตขับขี่ที่ถูกต้องสำหรับยานพาหนะประเภทนี้ และจะไม่อนุญาตให้บุคคลที่ไม่ได้รับอนุญาตขับหรือควบคุมยานพาหนะ","id":"Penyewa menyatakan memiliki surat izin mengemudi yang sah untuk golongan kendaraan ini dan tidak akan mengizinkan orang yang tidak berwenang mengemudikan atau menguasai kendaraan.","vi":"Bên thuê xác nhận có giấy phép lái xe hợp lệ cho loại xe này và sẽ không cho phép người không được ủy quyền lái hoặc điều khiển xe.","ms":"Penyewa mengesahkan bahawa mereka memegang lesen memandu yang sah untuk kelas kenderaan ini dan tidak akan membenarkan mana-mana orang yang tidak dibenarkan memandu atau mengawal kenderaan.","fil":"Kinukumpirma ng Umuupa na mayroon siyang balidong lisensya sa pagmamaneho para sa uri ng sasakyang ito at hindi niya papayagang magmaneho o humawak ng sasakyan ang sinumang walang pahintulot.","lo":"ຜູ້ເຊົ່າຢືນຢັນວ່າມີໃບຂັບຂີ່ທີ່ຖືກຕ້ອງສຳລັບຍານພາຫະນະປະເພດນີ້ ແລະ ຈະບໍ່ອະນຸຍາດໃຫ້ບຸກຄົນທີ່ບໍ່ໄດ້ຮັບອະນຸຍາດຂັບ ຫຼື ຄວບຄຸມຍານພາຫະນະ.","km":"អ្នកជួលបញ្ជាក់ថាមានប័ណ្ណបើកបរត្រឹមត្រូវសម្រាប់ប្រភេទយានយន្តនេះ ហើយនឹងមិនអនុញ្ញាតឲ្យអ្នកដែលគ្មានការអនុញ្ញាតបើកបរ ឬគ្រប់គ្រងយានយន្តឡើយ។","el":"Ο Μισθωτής βεβαιώνει ότι διαθέτει έγκυρη άδεια οδήγησης για την κατηγορία αυτού του οχήματος και ότι δεν θα επιτρέψει σε μη εξουσιοδοτημένο πρόσωπο να οδηγήσει ή να χρησιμοποιήσει το όχημα.","es":"El Arrendatario confirma que posee un permiso de conducción válido para esta clase de vehículo y que no permitirá que ninguna persona no autorizada lo conduzca o lo maneje.","pt":"O Locatário confirma que é titular de uma carta de condução válida para esta categoria de veículo e que não permitirá que nenhuma pessoa não autorizada conduza ou utilize o veículo.","it":"Il Conduttore conferma di essere titolare di una patente di guida valida per questa categoria di veicolo e di non consentire la guida o l'uso del veicolo a persone non autorizzate.","hr":"Najmoprimac potvrđuje da ima valjanu vozačku dozvolu za ovu kategoriju vozila te da neće dopustiti neovlaštenoj osobi da upravlja vozilom ili ga koristi.","fr":"Le Locataire confirme être titulaire d'un permis de conduire valable pour cette catégorie de véhicule et s'engage à ne laisser aucune personne non autorisée conduire ou utiliser le véhicule.","de":"Der Mieter bestätigt, eine gültige Fahrerlaubnis für diese Fahrzeugklasse zu besitzen, und wird keiner unberechtigten Person erlauben, das Fahrzeug zu führen oder zu benutzen.","tr":"Kiracı, bu araç sınıfı için geçerli bir sürücü belgesine sahip olduğunu ve yetkisiz hiç kimsenin aracı kullanmasına izin vermeyeceğini beyan eder."},
  {"th":"ผู้เช่าต้องคืนยานพาหนะภายในวันที่และเวลาที่ตกลงกัน เว้นแต่ผู้ให้เช่าจะยืนยันการขยายเวลาเป็นลายลักษณ์อักษร","id":"Kendaraan wajib dikembalikan paling lambat pada tanggal dan jam berakhirnya sewa yang disepakati, kecuali Pemilik mengonfirmasi perpanjangan secara tertulis.","vi":"Xe phải được trả đúng hoặc trước ngày giờ kết thúc đã thỏa thuận, trừ khi Bên cho thuê xác nhận gia hạn bằng văn bản.","ms":"Kenderaan mesti dipulangkan pada atau sebelum tarikh dan masa tamat yang dipersetujui melainkan Pemilik mengesahkan lanjutan secara bertulis.","fil":"Dapat ibalik ang sasakyan sa o bago ang napagkasunduang petsa at oras ng pagtatapos maliban kung kumpirmahin ng May-ari ang extension nang nakasulat.","lo":"ຜູ້ເຊົ່າຕ້ອງສົ່ງຄືນຍານພາຫະນະພາຍໃນວັນທີ ແລະ ເວລາທີ່ຕົກລົງກັນ ເວັ້ນເສຍແຕ່ຜູ້ໃຫ້ເຊົ່າຢືນຢັນການຕໍ່ເວລາເປັນລາຍລັກອັກສອນ.","km":"យានយន្តត្រូវប្រគល់វិញនៅ ឬមុនថ្ងៃ និងម៉ោងបញ្ចប់ដែលបានព្រមព្រៀង លើកលែងតែអ្នកឲ្យជួលបញ្ជាក់ការពន្យារពេលជាលាយលក្ខណ៍អក្សរ។","el":"Το όχημα πρέπει να επιστραφεί το αργότερο κατά τη συμφωνημένη ημερομηνία και ώρα λήξης, εκτός αν ο Εκμισθωτής επιβεβαιώσει γραπτώς παράταση.","es":"El vehículo debe devolverse como muy tarde en la fecha y hora de finalización acordadas, salvo que el Propietario confirme una prórroga por escrito.","pt":"O veículo deve ser devolvido até à data e hora de fim acordadas, salvo se o Locador confirmar uma prorrogação por escrito.","it":"Il veicolo deve essere restituito entro la data e l'ora di fine concordate, salvo proroga confermata per iscritto dal Locatore.","hr":"Vozilo se mora vratiti najkasnije do ugovorenog datuma i vremena završetka, osim ako Najmodavac pisano potvrdi produljenje.","fr":"Le véhicule doit être restitué au plus tard à la date et à l'heure de fin convenues, sauf prolongation confirmée par écrit par le Loueur.","de":"Das Fahrzeug ist spätestens zum vereinbarten Enddatum und zur vereinbarten Uhrzeit zurückzugeben, sofern der Vermieter keine Verlängerung schriftlich bestätigt.","tr":"Kiraya Veren süre uzatımını yazılı olarak teyit etmedikçe, araç en geç kararlaştırılan bitiş tarihi ve saatinde iade edilmelidir."},
  {"th":"การเช่านี้เป็นแบบไม่กำหนดวันสิ้นสุดหรือรายเดือนต่อเนื่อง ผู้เช่ายังคงรับผิดชอบค่าเช่าในแต่ละรอบบิลจนกว่าจะคืนยานพาหนะและผู้ให้เช่ายืนยันว่าการเช่าสิ้นสุดแล้ว","id":"Sewa ini tanpa tanggal berakhir atau diperpanjang setiap bulan. Penyewa tetap bertanggung jawab atas setiap periode tagihan sampai kendaraan dikembalikan dan Pemilik mengonfirmasi bahwa sewa telah selesai.","vi":"Hợp đồng thuê này không có ngày kết thúc hoặc gia hạn theo từng tháng. Bên thuê vẫn chịu trách nhiệm cho từng kỳ thanh toán cho đến khi trả xe và Bên cho thuê xác nhận kết thúc việc thuê.","ms":"Sewaan ini tiada tarikh tamat atau diperbaharui setiap bulan. Penyewa kekal bertanggungjawab bagi setiap tempoh bil sehingga kenderaan dipulangkan dan Pemilik mengesahkan sewaan telah selesai.","fil":"Ang upang ito ay walang takdang pagtatapos o paulit-ulit buwan-buwan. Mananatiling may pananagutan ang Umuupa sa bawat panahon ng singil hanggang maibalik ang sasakyan at kumpirmahin ng May-ari na tapos na ang upa.","lo":"ການເຊົ່ານີ້ບໍ່ມີກຳນົດວັນສິ້ນສຸດ ຫຼື ຕໍ່ເປັນລາຍເດືອນ. ຜູ້ເຊົ່າຍັງຄົງຮັບຜິດຊອບຄ່າເຊົ່າໃນແຕ່ລະຮອບບິນ ຈົນກວ່າຈະສົ່ງຄືນຍານພາຫະນະ ແລະ ຜູ້ໃຫ້ເຊົ່າຢືນຢັນວ່າການເຊົ່າສິ້ນສຸດແລ້ວ.","km":"ការជួលនេះគ្មានថ្ងៃបញ្ចប់ ឬបន្តជារៀងរាល់ខែ។ អ្នកជួលនៅតែទទួលខុសត្រូវសម្រាប់វដ្តវិក្កយបត្រនីមួយៗ រហូតដល់ប្រគល់យានយន្តវិញ ហើយអ្នកឲ្យជួលបញ្ជាក់ថាការជួលបានបញ្ចប់។","el":"Η μίσθωση αυτή είναι αορίστου χρόνου ή ανανεώνεται κάθε μήνα. Ο Μισθωτής οφείλει το μίσθωμα κάθε περιόδου χρέωσης μέχρι να επιστρέψει το όχημα και να επιβεβαιώσει ο Εκμισθωτής τη λήξη της μίσθωσης.","es":"Este alquiler es indefinido o se renueva mensualmente. El Arrendatario sigue siendo responsable de cada periodo de facturación hasta que devuelva el vehículo y el Propietario confirme la finalización.","pt":"Este aluguer não tem termo ou renova-se mensalmente. O Locatário continua responsável por cada período de faturação até devolver o veículo e o Locador confirmar o fim do aluguer.","it":"Il presente noleggio è a tempo indeterminato o si rinnova di mese in mese. Il Conduttore resta tenuto al pagamento di ogni periodo di fatturazione fino alla restituzione del veicolo e alla conferma della chiusura da parte del Locatore.","hr":"Ovaj najam sklopljen je na neodređeno vrijeme ili se produljuje iz mjeseca u mjesec. Najmoprimac odgovara za svako obračunsko razdoblje dok ne vrati vozilo i dok Najmodavac ne potvrdi završetak najma.","fr":"Cette location est à durée indéterminée ou reconduite de mois en mois. Le Locataire reste redevable de chaque période de facturation jusqu'à la restitution du véhicule et la confirmation de fin de location par le Loueur.","de":"Diese Miete ist unbefristet oder verlängert sich monatlich. Der Mieter schuldet die Miete für jeden Abrechnungszeitraum, bis das Fahrzeug zurückgegeben ist und der Vermieter das Mietende bestätigt.","tr":"Bu kiralama belirsiz sürelidir veya aylık olarak yenilenir. Kiracı, aracı iade edip Kiraya Veren kiralamanın sona erdiğini teyit edene kadar her fatura döneminin bedelinden sorumludur."},
  {"th":"ค่าเช่าคิดในอัตรา ฿{{rental_rate}} ต่อ{{billing_period_label_th}} และครบกำหนดชำระ{{payment_due_label_th}} ระดับน้ำมันจะถูกบันทึกในขณะส่งมอบยานพาหนะ {{#if fuel_charge_enabled}}หากคืนน้ำมันต่ำกว่าเดิมอาจมีค่าธรรมเนียม ฿{{fuel_charge_per_increment}} ต่อหนึ่งในแปดขีดบนมาตรวัด {{/if}}การชำระล่าช้า การยกเลิกก่อนกำหนด ความเสียหาย ค่าทำความสะอาด และค่าใช้จ่ายอื่น ๆ อาจถูกหักจากเงินประกันหรือเรียกเก็บเพิ่มเติม","id":"Sewa dikenakan sebesar {{currency_symbol}}{{rental_rate}} per {{billing_period_label_2}} dan jatuh tempo {{payment_due_label_2}}. Tingkat bahan bakar dicatat saat serah terima kendaraan. {{#if fuel_charge_enabled}}Kekurangan bahan bakar dapat dikenakan biaya {{currency_symbol}}{{fuel_charge_per_increment}} per seperdelapan skala indikator. {{/if}}Keterlambatan pembayaran, pengakhiran lebih awal, kerusakan, biaya kebersihan dan biaya lainnya dapat dipotong dari uang jaminan atau ditagih terpisah.","vi":"Tiền thuê là {{currency_symbol}}{{rental_rate}} mỗi {{billing_period_label_2}} và đến hạn {{payment_due_label_2}}. Mức nhiên liệu được ghi nhận khi giao xe. {{#if fuel_charge_enabled}}Nếu thiếu nhiên liệu có thể bị tính {{currency_symbol}}{{fuel_charge_per_increment}} cho mỗi một phần tám vạch đồng hồ. {{/if}}Phí trả chậm, chấm dứt sớm, hư hỏng, vệ sinh và các khoản phí khác có thể được trừ vào tiền đặt cọc hoặc lập hóa đơn riêng.","ms":"Sewa dikenakan pada kadar {{currency_symbol}}{{rental_rate}} setiap {{billing_period_label_2}} dan perlu dibayar {{payment_due_label_2}}. Paras bahan api direkodkan semasa serahan kenderaan. {{#if fuel_charge_enabled}}Kekurangan bahan api boleh dikenakan caj {{currency_symbol}}{{fuel_charge_per_increment}} bagi setiap satu perlapan tolok. {{/if}}Bayaran lewat, penamatan awal, kerosakan, pembersihan dan caj lain boleh ditolak daripada wang cagaran atau diinvois secara berasingan.","fil":"Ang upa ay {{currency_symbol}}{{rental_rate}} bawat {{billing_period_label_2}} at dapat bayaran {{payment_due_label_2}}. Itinatala ang antas ng panggatong sa oras ng paghahatid ng sasakyan. {{#if fuel_charge_enabled}}Ang kakulangan sa panggatong ay maaaring singilin ng {{currency_symbol}}{{fuel_charge_per_increment}} bawat ikawalong bahagi ng gauge. {{/if}}Ang huling bayad, maagang pagwawakas, sira, paglilinis at iba pang singil ay maaaring ibawas sa deposito o singilin nang hiwalay.","lo":"ຄ່າເຊົ່າຄິດໃນອັດຕາ {{currency_symbol}}{{rental_rate}} ຕໍ່{{billing_period_label_2}} ແລະ ຄົບກຳນົດຊຳລະ{{payment_due_label_2}}. ລະດັບນ້ຳມັນຈະຖືກບັນທຶກໃນເວລາສົ່ງມອບຍານພາຫະນະ. {{#if fuel_charge_enabled}}ຖ້າສົ່ງຄືນນ້ຳມັນຕ່ຳກວ່າເດີມ ອາດມີຄ່າທຳນຽມ {{currency_symbol}}{{fuel_charge_per_increment}} ຕໍ່ໜຶ່ງສ່ວນແປດຂອງໜ້າປັດ. {{/if}}ການຊຳລະຊັກຊ້າ, ການຍົກເລີກກ່ອນກຳນົດ, ຄວາມເສຍຫາຍ, ຄ່າທຳຄວາມສະອາດ ແລະ ຄ່າໃຊ້ຈ່າຍອື່ນໆ ອາດຖືກຫັກຈາກເງິນມັດຈຳ ຫຼື ຮຽກເກັບຕ່າງຫາກ.","km":"ថ្លៃជួលគឺ {{currency_symbol}}{{rental_rate}} ក្នុងមួយ{{billing_period_label_2}} ហើយត្រូវបង់{{payment_due_label_2}}។ កម្រិតឥន្ធនៈត្រូវកត់ត្រានៅពេលប្រគល់យានយន្ត។ {{#if fuel_charge_enabled}}ការខ្វះឥន្ធនៈអាចគិតថ្លៃ {{currency_symbol}}{{fuel_charge_per_increment}} ក្នុងមួយភាគប្រាំបីនៃនាឡិកាឥន្ធនៈ។ {{/if}}ការបង់យឺត ការបញ្ចប់មុនកំណត់ ការខូចខាត ការសម្អាត និងថ្លៃផ្សេងៗ អាចកាត់ពីប្រាក់កក់ ឬចេញវិក្កយបត្រដាច់ដោយឡែក។","el":"Το μίσθωμα ανέρχεται σε {{currency_symbol}}{{rental_rate}} ανά {{billing_period_label_2}} και καταβάλλεται {{payment_due_label_2}}. Η στάθμη καυσίμου καταγράφεται κατά την παράδοση του οχήματος. {{#if fuel_charge_enabled}}Το καύσιμο που λείπει μπορεί να χρεωθεί {{currency_symbol}}{{fuel_charge_per_increment}} ανά όγδοο της ένδειξης. {{/if}}Η καθυστέρηση πληρωμής, η πρόωρη λήξη, οι ζημιές, ο καθαρισμός και άλλες χρεώσεις μπορούν να παρακρατηθούν από την εγγύηση ή να τιμολογηθούν χωριστά.","es":"El alquiler se cobra a {{currency_symbol}}{{rental_rate}} por {{billing_period_label_2}} y se paga {{payment_due_label_2}}. El nivel de combustible se anota en el momento de la entrega del vehículo. {{#if fuel_charge_enabled}}La falta de combustible puede cobrarse a {{currency_symbol}}{{fuel_charge_per_increment}} por cada octavo del indicador. {{/if}}Los retrasos en el pago, la finalización anticipada, los daños, la limpieza y otros cargos pueden descontarse de la fianza o facturarse por separado.","pt":"O aluguer é cobrado a {{currency_symbol}}{{rental_rate}} por {{billing_period_label_2}} e é pago {{payment_due_label_2}}. O nível de combustível é registado no momento da entrega do veículo. {{#if fuel_charge_enabled}}A falta de combustível pode ser cobrada a {{currency_symbol}}{{fuel_charge_per_increment}} por cada oitavo do indicador. {{/if}}Os atrasos de pagamento, a cessação antecipada, os danos, a limpeza e outros encargos podem ser deduzidos da caução ou faturados separadamente.","it":"Il canone è di {{currency_symbol}}{{rental_rate}} per {{billing_period_label_2}} ed è dovuto {{payment_due_label_2}}. Il livello di carburante viene annotato alla consegna del veicolo. {{#if fuel_charge_enabled}}L'eventuale carburante mancante può essere addebitato a {{currency_symbol}}{{fuel_charge_per_increment}} per ogni ottavo dell'indicatore. {{/if}}Ritardi di pagamento, recesso anticipato, danni, pulizia e altri addebiti possono essere trattenuti dal deposito cauzionale o fatturati separatamente.","hr":"Najamnina iznosi {{currency_symbol}}{{rental_rate}} po {{billing_period_label_2}} i plaća se {{payment_due_label_2}}. Razina goriva bilježi se pri predaji vozila. {{#if fuel_charge_enabled}}Gorivo koje nedostaje može se naplatiti {{currency_symbol}}{{fuel_charge_per_increment}} za svaku osminu pokazivača. {{/if}}Zakašnjelo plaćanje, prijevremeni raskid, oštećenja, čišćenje i ostali troškovi mogu se odbiti od jamčevine ili posebno fakturirati.","fr":"Le loyer est de {{currency_symbol}}{{rental_rate}} par {{billing_period_label_2}} et est payable {{payment_due_label_2}}. Le niveau de carburant est relevé lors de la remise du véhicule. {{#if fuel_charge_enabled}}Le carburant manquant peut être facturé {{currency_symbol}}{{fuel_charge_per_increment}} par huitième de jauge. {{/if}}Les retards de paiement, la résiliation anticipée, les dommages, le nettoyage et les autres frais peuvent être déduits du dépôt de garantie ou facturés séparément.","de":"Die Miete beträgt {{currency_symbol}}{{rental_rate}} pro {{billing_period_label_2}} und ist {{payment_due_label_2}} fällig. Der Tankstand wird bei der Übergabe des Fahrzeugs festgehalten. {{#if fuel_charge_enabled}}Fehlender Kraftstoff kann mit {{currency_symbol}}{{fuel_charge_per_increment}} je Achtel der Tankanzeige berechnet werden. {{/if}}Verspätete Zahlung, vorzeitige Beendigung, Schäden, Reinigung und sonstige Kosten können von der Kaution einbehalten oder gesondert in Rechnung gestellt werden.","tr":"Kira bedeli {{currency_symbol}}{{rental_rate}} / {{billing_period_label_2}} olup {{payment_due_label_2}} ödenir. Yakıt seviyesi aracın teslimi sırasında kaydedilir. {{#if fuel_charge_enabled}}Eksik yakıt için gösterge sekizde biri başına {{currency_symbol}}{{fuel_charge_per_increment}} ücret alınabilir. {{/if}}Gecikmeli ödemeler, erken sona erdirme, hasar, temizlik ve diğer masraflar depozitodan mahsup edilebilir veya ayrıca faturalandırılabilir."},
  {"th":"เงินประกันถูกเก็บไว้เพื่อเป็นหลักประกันสำหรับค่าเช่าค้างชำระ ความเสียหาย ค่าปรับ รายการสูญหาย ค่าทำความสะอาด ค่าน้ำมัน การคืนรถล่าช้า และความรับผิดอื่นใดจากการเช่านี้","id":"Uang jaminan disimpan sebagai jaminan atas sewa yang belum dibayar, kerusakan, denda, barang yang hilang, kebersihan, bahan bakar, keterlambatan pengembalian dan kewajiban lain yang timbul dari sewa ini.","vi":"Tiền đặt cọc được giữ để bảo đảm cho tiền thuê chưa trả, hư hỏng, tiền phạt, vật dụng bị mất, vệ sinh, nhiên liệu, trả xe trễ và mọi trách nhiệm khác phát sinh từ việc thuê này.","ms":"Wang cagaran dipegang sebagai jaminan bagi sewa yang belum dibayar, kerosakan, saman, barang yang hilang, pembersihan, bahan api, pemulangan lewat dan apa-apa liabiliti lain yang timbul daripada sewaan ini.","fil":"Ang deposito ay hawak bilang garantiya para sa hindi nabayarang upa, sira, multa, nawawalang gamit, paglilinis, panggatong, huling pagbabalik at anumang iba pang pananagutang magmumula sa upang ito.","lo":"ເງິນມັດຈຳຖືກເກັບໄວ້ເປັນຫຼັກປະກັນສຳລັບຄ່າເຊົ່າຄ້າງຊຳລະ, ຄວາມເສຍຫາຍ, ຄ່າປັບ, ສິ່ງຂອງເສຍ, ຄ່າທຳຄວາມສະອາດ, ຄ່ານ້ຳມັນ, ການສົ່ງລົດຄືນຊັກຊ້າ ແລະ ຄວາມຮັບຜິດຊອບອື່ນໃດທີ່ເກີດຈາກການເຊົ່ານີ້.","km":"ប្រាក់កក់ត្រូវរក្សាទុកជាការធានាសម្រាប់ថ្លៃជួលមិនទាន់បង់ ការខូចខាត ការពិន័យ របស់បាត់ ការសម្អាត ឥន្ធនៈ ការប្រគល់យឺត និងការទទួលខុសត្រូវផ្សេងទៀតដែលកើតចេញពីការជួលនេះ។","el":"Η εγγύηση καλύπτει απλήρωτα μισθώματα, ζημιές, πρόστιμα, απολεσθέντα αντικείμενα, καθαρισμό, καύσιμα, καθυστερημένη επιστροφή και κάθε άλλη υποχρέωση από τη μίσθωση αυτή.","es":"La fianza garantiza el alquiler impagado, los daños, las multas, los elementos perdidos, la limpieza, el combustible, la devolución tardía y cualquier otra responsabilidad derivada de este alquiler.","pt":"A caução garante o aluguer em dívida, os danos, as coimas, os objetos perdidos, a limpeza, o combustível, a devolução tardia e qualquer outra responsabilidade resultante deste aluguer.","it":"Il deposito cauzionale garantisce i canoni non pagati, i danni, le multe, gli oggetti smarriti, la pulizia, il carburante, la riconsegna tardiva e ogni altra obbligazione derivante dal noleggio.","hr":"Jamčevina služi kao osiguranje za neplaćenu najamninu, oštećenja, kazne, izgubljene predmete, čišćenje, gorivo, kasni povrat i svaku drugu obvezu iz ovog najma.","fr":"Le dépôt de garantie couvre les loyers impayés, les dommages, les amendes, les éléments perdus, le nettoyage, le carburant, la restitution tardive et toute autre somme due au titre de cette location.","de":"Die Kaution dient als Sicherheit für offene Miete, Schäden, Bußgelder, verlorene Gegenstände, Reinigung, Kraftstoff, verspätete Rückgabe und alle sonstigen Ansprüche aus diesem Mietverhältnis.","tr":"Depozito; ödenmemiş kira bedelini, hasarları, cezaları, kaybolan eşyaları, temizlik ve yakıt giderlerini, geç iadeyi ve işbu kiralamadan doğan diğer borçları teminat altına alır."},
  {"th":"เฉพาะรายการที่ระบุข้างต้นเท่านั้นที่รวมอยู่ รายการอื่นที่ไม่ได้ระบุถือว่าไม่รวม เว้นแต่ผู้ให้เช่าจะยืนยันเป็นลายลักษณ์อักษร","id":"Hanya barang yang tercantum di atas yang termasuk. Barang yang tidak tercantum tidak termasuk, kecuali dikonfirmasi oleh Pemilik secara tertulis.","vi":"Chỉ những hạng mục liệt kê ở trên được bao gồm. Mọi hạng mục không được liệt kê đều không bao gồm, trừ khi Bên cho thuê xác nhận bằng văn bản.","ms":"Hanya item yang disenaraikan di atas disertakan. Item yang tidak disenaraikan tidak termasuk melainkan disahkan oleh Pemilik secara bertulis.","fil":"Ang mga gamit lamang na nakalista sa itaas ang kasama. Ang anumang hindi nakalista ay hindi kasama maliban kung kumpirmahin ng May-ari nang nakasulat.","lo":"ສະເພາະລາຍການທີ່ລະບຸໄວ້ຂ້າງເທິງເທົ່ານັ້ນທີ່ລວມຢູ່. ລາຍການອື່ນທີ່ບໍ່ໄດ້ລະບຸຖືວ່າບໍ່ລວມ ເວັ້ນເສຍແຕ່ຜູ້ໃຫ້ເຊົ່າຢືນຢັນເປັນລາຍລັກອັກສອນ.","km":"មានតែរបស់ដែលបានរាយខាងលើប៉ុណ្ណោះដែលរួមបញ្ចូល។ របស់ដែលមិនបានរាយមិនរួមបញ្ចូលទេ លើកលែងតែអ្នកឲ្យជួលបញ្ជាក់ជាលាយលក្ខណ៍អក្សរ។","el":"Περιλαμβάνονται μόνο όσα αναφέρονται παραπάνω. Ό,τι δεν αναφέρεται δεν περιλαμβάνεται, εκτός αν ο Εκμισθωτής το επιβεβαιώσει γραπτώς.","es":"Solo se incluyen los elementos indicados arriba. Cualquier elemento no indicado queda excluido, salvo que el Propietario lo confirme por escrito.","pt":"Apenas estão incluídos os elementos acima indicados. Qualquer elemento não indicado fica excluído, salvo confirmação escrita do Locador.","it":"Sono compresi solo gli elementi sopra elencati. Ogni elemento non elencato è escluso, salvo conferma scritta del Locatore.","hr":"Uključeni su samo gore navedeni predmeti. Sve što nije navedeno nije uključeno, osim ako to Najmodavac pisano potvrdi.","fr":"Seuls les éléments énumérés ci-dessus sont inclus. Tout élément non énuméré est exclu, sauf confirmation écrite du Loueur.","de":"Enthalten sind nur die oben aufgeführten Gegenstände. Nicht aufgeführte Gegenstände sind nicht enthalten, sofern der Vermieter sie nicht schriftlich bestätigt.","tr":"Yalnızca yukarıda belirtilen kalemler dâhildir. Belirtilmeyen her kalem, Kiraya Veren yazılı olarak teyit etmedikçe hariç sayılır."},
  {"th":"ผู้เช่าต้องดูแลยานพาหนะอย่างเหมาะสม ตรวจไฟเตือน สภาพยาง น้ำมันเครื่องและของเหลวตามความเหมาะสม และแจ้งผู้ให้เช่าทันทีเมื่อมีความผิดปกติ อุบัติเหตุ รถเสีย หรือเสียงผิดปกติ","id":"Penyewa wajib merawat kendaraan dengan wajar, memeriksa lampu peringatan, kondisi ban, oli dan cairan bila perlu, dan segera memberi tahu Pemilik jika terjadi kerusakan, kecelakaan, mogok atau bunyi yang tidak biasa.","vi":"Bên thuê phải sử dụng xe cẩn thận, kiểm tra đèn cảnh báo, tình trạng lốp, dầu và các loại dung dịch khi cần, và báo ngay cho Bên cho thuê khi có bất kỳ hỏng hóc, tai nạn, xe chết máy hoặc tiếng động bất thường nào.","ms":"Penyewa mesti menjaga kenderaan dengan munasabah, memeriksa lampu amaran, keadaan tayar, minyak dan cecair jika perlu, dan segera memaklumkan Pemilik tentang sebarang kerosakan, kemalangan, kerosakan enjin atau bunyi luar biasa.","fil":"Dapat maging maingat ang Umuupa, suriin ang mga warning light, kondisyon ng gulong, langis at mga likido kung naaangkop, at agad na ipaalam sa May-ari ang anumang sira, aksidente, pagtirik o kakaibang ingay.","lo":"ຜູ້ເຊົ່າຕ້ອງດູແລຍານພາຫະນະຢ່າງເໝາະສົມ, ກວດໄຟເຕືອນ, ສະພາບຢາງ, ນ້ຳມັນເຄື່ອງ ແລະ ຂອງແຫຼວຕາມຄວາມເໝາະສົມ ແລະ ແຈ້ງຜູ້ໃຫ້ເຊົ່າທັນທີເມື່ອມີຄວາມຜິດປົກກະຕິ, ອຸບັດຕິເຫດ, ລົດເປ່ເພ ຫຼື ສຽງຜິດປົກກະຕິ.","km":"អ្នកជួលត្រូវប្រើប្រាស់ដោយប្រុងប្រយ័ត្នសមរម្យ ពិនិត្យភ្លើងព្រមាន ស្ថានភាពកង់ ប្រេងម៉ាស៊ីន និងវត្ថុរាវតាមការចាំបាច់ ហើយជូនដំណឹងអ្នកឲ្យជួលភ្លាមៗពីការខូចខាត គ្រោះថ្នាក់ ការខូចម៉ាស៊ីន ឬសំឡេងមិនធម្មតា។","el":"Ο Μισθωτής οφείλει να χρησιμοποιεί το όχημα με επιμέλεια, να ελέγχει τις προειδοποιητικές λυχνίες, την κατάσταση των ελαστικών, τα λάδια και τα υγρά όπου χρειάζεται και να ενημερώνει αμέσως τον Εκμισθωτή για κάθε βλάβη, ατύχημα, ακινητοποίηση ή ασυνήθιστο θόρυβο.","es":"El Arrendatario debe actuar con la diligencia debida, revisar los testigos de aviso, el estado de los neumáticos, el aceite y los líquidos cuando proceda, y avisar de inmediato al Propietario de cualquier fallo, accidente, avería o ruido anormal.","pt":"O Locatário deve utilizar o veículo com o cuidado devido, verificar as luzes de aviso, o estado dos pneus, o óleo e os líquidos quando adequado, e informar de imediato o Locador de qualquer avaria, acidente, imobilização ou ruído anormal.","it":"Il Conduttore deve usare il veicolo con la dovuta diligenza, controllare le spie, lo stato degli pneumatici, l'olio e i liquidi quando opportuno e avvisare subito il Locatore di qualsiasi guasto, incidente, fermo o rumore anomalo.","hr":"Najmoprimac mora postupati s dužnom pažnjom, provjeravati kontrolna svjetla, stanje guma, ulje i tekućine kada je to primjereno te odmah obavijestiti Najmodavca o svakom kvaru, nezgodi, zastoju ili neobičnom zvuku.","fr":"Le Locataire doit utiliser le véhicule avec soin, surveiller les voyants, l'état des pneus, l'huile et les liquides le cas échéant, et informer immédiatement le Loueur de toute anomalie, accident, panne ou bruit inhabituel.","de":"Der Mieter hat das Fahrzeug sorgfältig zu behandeln, Warnleuchten, Reifenzustand, Öl und Flüssigkeiten soweit angemessen zu prüfen und den Vermieter unverzüglich über jeden Defekt, Unfall, jede Panne oder ungewöhnliche Geräusche zu informieren.","tr":"Kiracı aracı gereken özeni göstererek kullanmalı, uyarı ışıklarını, lastiklerin durumunu, yağ ve sıvıları gerektiğinde kontrol etmeli ve her türlü arıza, kaza, bozulma veya olağan dışı sesi derhâl Kiraya Verene bildirmelidir."},
  {"th":"ผู้เช่าไม่มีสิทธิอนุมัติการซ่อม เว้นแต่เป็นเหตุฉุกเฉินและไม่เกิน ฿{{emergency_repair_limit}} โดยไม่ได้รับอนุมัติเป็นลายลักษณ์อักษรล่วงหน้า","id":"Penyewa tidak boleh menyetujui perbaikan kecuali dalam keadaan darurat dan hanya sampai {{currency_symbol}}{{emergency_repair_limit}} tanpa persetujuan tertulis terlebih dahulu.","vi":"Bên thuê không được tự quyết định sửa chữa, trừ trường hợp khẩn cấp và chỉ tối đa {{currency_symbol}}{{emergency_repair_limit}} khi chưa có sự chấp thuận trước bằng văn bản.","ms":"Penyewa tidak boleh membenarkan pembaikan kecuali dalam kecemasan dan hanya sehingga {{currency_symbol}}{{emergency_repair_limit}} tanpa kelulusan bertulis terlebih dahulu.","fil":"Hindi maaaring magpaayos ang Umuupa maliban sa emergency at hanggang {{currency_symbol}}{{emergency_repair_limit}} lamang nang walang paunang nakasulat na pahintulot.","lo":"ຜູ້ເຊົ່າບໍ່ມີສິດອະນຸມັດການສ້ອມແປງ ເວັ້ນເສຍແຕ່ເປັນເຫດສຸກເສີນ ແລະ ບໍ່ເກີນ {{currency_symbol}}{{emergency_repair_limit}} ໂດຍບໍ່ໄດ້ຮັບອະນຸມັດເປັນລາຍລັກອັກສອນລ່ວງໜ້າ.","km":"អ្នកជួលមិនអាចសម្រេចជួសជុលបានទេ លើកលែងតែក្នុងករណីបន្ទាន់ ហើយមិនលើសពី {{currency_symbol}}{{emergency_repair_limit}} ដោយគ្មានការយល់ព្រមជាលាយលក្ខណ៍អក្សរជាមុន។","el":"Ο Μισθωτής δεν μπορεί να αναθέσει επισκευές χωρίς προηγούμενη γραπτή έγκριση, εκτός από επείγουσα περίπτωση και μόνο έως {{currency_symbol}}{{emergency_repair_limit}}.","es":"El Arrendatario no puede encargar reparaciones salvo en caso de urgencia y solo hasta {{currency_symbol}}{{emergency_repair_limit}} sin autorización previa por escrito.","pt":"O Locatário não pode mandar fazer reparações, salvo em caso de urgência e apenas até {{currency_symbol}}{{emergency_repair_limit}}, sem autorização prévia por escrito.","it":"Il Conduttore non può far eseguire riparazioni, salvo in caso di emergenza e solo fino a {{currency_symbol}}{{emergency_repair_limit}}, senza previa autorizzazione scritta.","hr":"Najmoprimac ne smije naručiti popravke bez prethodnog pisanog odobrenja, osim u hitnom slučaju i najviše do {{currency_symbol}}{{emergency_repair_limit}}.","fr":"Le Locataire ne peut faire effectuer aucune réparation, sauf en cas d'urgence et dans la limite de {{currency_symbol}}{{emergency_repair_limit}}, sans accord écrit préalable.","de":"Der Mieter darf ohne vorherige schriftliche Zustimmung keine Reparaturen in Auftrag geben, außer im Notfall und nur bis {{currency_symbol}}{{emergency_repair_limit}}.","tr":"Kiracı, acil durumlar dışında ve önceden yazılı onay alınmaksızın yalnızca {{currency_symbol}}{{emergency_repair_limit}} tutarına kadar onarım yaptırabilir; bunun dışında onarım yaptıramaz."},
  {"th":"ผู้เช่าไม่มีสิทธิอนุมัติการซ่อมใด ๆ โดยไม่ได้รับอนุมัติจากผู้ให้เช่าล่วงหน้า เว้นแต่สิ่งที่จำเป็นเพื่อความปลอดภัยของบุคคล","id":"Penyewa tidak boleh menyetujui perbaikan apa pun tanpa persetujuan Pemilik terlebih dahulu, kecuali yang diperlukan untuk keselamatan orang.","vi":"Bên thuê không được tự quyết định bất kỳ việc sửa chữa nào khi chưa có sự chấp thuận trước của Bên cho thuê, trừ những việc cần thiết để bảo đảm an toàn cho con người.","ms":"Penyewa tidak boleh membenarkan sebarang pembaikan tanpa kelulusan Pemilik terlebih dahulu, kecuali yang perlu untuk keselamatan orang.","fil":"Hindi maaaring magpaayos ang Umuupa nang walang paunang pahintulot ng May-ari, maliban sa kinakailangan para sa kaligtasan ng mga tao.","lo":"ຜູ້ເຊົ່າບໍ່ມີສິດອະນຸມັດການສ້ອມແປງໃດໆ ໂດຍບໍ່ໄດ້ຮັບອະນຸມັດຈາກຜູ້ໃຫ້ເຊົ່າລ່ວງໜ້າ ເວັ້ນເສຍແຕ່ສິ່ງທີ່ຈຳເປັນເພື່ອຄວາມປອດໄພຂອງບຸກຄົນ.","km":"អ្នកជួលមិនអាចសម្រេចជួសជុលអ្វីបានទេ ដោយគ្មានការយល់ព្រមជាមុនពីអ្នកឲ្យជួល លើកលែងតែអ្វីដែលចាំបាច់ដើម្បីសុវត្ថិភាពមនុស្ស។","el":"Ο Μισθωτής δεν μπορεί να αναθέσει καμία επισκευή χωρίς την προηγούμενη έγκριση του Εκμισθωτή, εκτός από ό,τι είναι αναγκαίο για την ασφάλεια των προσώπων.","es":"El Arrendatario no puede encargar ninguna reparación sin la autorización previa del Propietario, salvo lo necesario para la seguridad de las personas.","pt":"O Locatário não pode mandar fazer qualquer reparação sem autorização prévia do Locador, salvo o necessário para a segurança das pessoas.","it":"Il Conduttore non può far eseguire alcuna riparazione senza la previa autorizzazione del Locatore, salvo quanto necessario per la sicurezza delle persone.","hr":"Najmoprimac ne smije naručiti nikakav popravak bez prethodnog odobrenja Najmodavca, osim onoga što je nužno za sigurnost ljudi.","fr":"Le Locataire ne peut faire effectuer aucune réparation sans l'accord préalable du Loueur, sauf ce qui est nécessaire à la sécurité des personnes.","de":"Der Mieter darf ohne vorherige Zustimmung des Vermieters keine Reparaturen in Auftrag geben, außer was zur Sicherheit von Personen erforderlich ist.","tr":"Kiracı, kişilerin güvenliği için zorunlu olanlar dışında, Kiraya Verenin önceden onayı olmaksızın hiçbir onarım yaptıramaz."},
  {"th":"ห้ามใช้ยานพาหนะเพื่อกิจกรรมผิดกฎหมาย แข่งขัน ลากจูง ขับออฟโรดเว้นแต่ตกลงไว้ ให้เช่าต่อเชิงพาณิชย์ ขับขี่ขณะมึนเมา ขนส่งสิ่งผิดกฎหมาย หรือใช้งานนอกพื้นที่ที่ตกลงกัน","id":"Kendaraan tidak boleh digunakan untuk kegiatan ilegal, balapan, menarik kendaraan lain, berkendara di luar jalan kecuali disepakati, disewakan kembali secara komersial, berkendara di bawah pengaruh alkohol atau narkoba, mengangkut barang terlarang, atau penggunaan di luar wilayah yang disepakati.","vi":"Không được sử dụng xe cho hoạt động bất hợp pháp, đua xe, kéo xe, đi đường địa hình trừ khi đã thỏa thuận, cho thuê lại để kinh doanh, lái xe khi say rượu hoặc dùng chất kích thích, chở hàng cấm, hoặc sử dụng ngoài khu vực đã thỏa thuận.","ms":"Kenderaan tidak boleh digunakan untuk aktiviti haram, perlumbaan, menunda, pemanduan luar jalan melainkan dipersetujui, sewaan semula secara komersial, memandu di bawah pengaruh alkohol atau dadah, membawa barang yang menyalahi undang-undang, atau penggunaan di luar kawasan yang dipersetujui.","fil":"Hindi dapat gamitin ang sasakyan sa ilegal na gawain, karera, paghila, pagmamaneho sa labas ng kalsada maliban kung napagkasunduan, komersyal na pagpapaupa, pagmamaneho nang lasing o nasa impluwensya ng droga, pagdadala ng ilegal na kalakal, o anumang paggamit sa labas ng napagkasunduang lugar.","lo":"ຫ້າມໃຊ້ຍານພາຫະນະເພື່ອກິດຈະກຳທີ່ຜິດກົດໝາຍ, ການແຂ່ງຂັນ, ການລາກຈູງ, ການຂັບນອກເສັ້ນທາງເວັ້ນເສຍແຕ່ຕົກລົງໄວ້, ການໃຫ້ເຊົ່າຕໍ່ເພື່ອການຄ້າ, ການຂັບຂີ່ຂະນະມຶນເມົາ, ການຂົນສົ່ງສິ່ງຜິດກົດໝາຍ ຫຼື ການນຳໃຊ້ນອກພື້ນທີ່ທີ່ຕົກລົງກັນ.","km":"ហាមប្រើយានយន្តសម្រាប់សកម្មភាពខុសច្បាប់ ការប្រណាំង ការអូស ការបើកបរក្រៅផ្លូវ លើកលែងតែបានព្រមព្រៀង ការជួលបន្តដើម្បីពាណិជ្ជកម្ម ការបើកបរក្រោមឥទ្ធិពលស្រា ឬគ្រឿងញៀន ការដឹកទំនិញខុសច្បាប់ ឬការប្រើប្រាស់ក្រៅតំបន់ដែលបានព្រមព្រៀង។","el":"Απαγορεύεται η χρήση του οχήματος για παράνομες δραστηριότητες, αγώνες, ρυμούλκηση, οδήγηση εκτός δρόμου χωρίς συμφωνία, εμπορική υπεκμίσθωση, οδήγηση υπό την επήρεια αλκοόλ ή ουσιών, μεταφορά παράνομων αγαθών ή χρήση εκτός της συμφωνημένης περιοχής.","es":"El vehículo no puede utilizarse para actividades ilícitas, carreras, remolcar, circular fuera de carretera salvo acuerdo, alquiler comercial a terceros, conducir bajo los efectos del alcohol o las drogas, transportar mercancías ilícitas ni fuera de la zona acordada.","pt":"O veículo não pode ser utilizado para atividades ilícitas, corridas, reboque, condução fora de estrada salvo acordo, aluguer comercial a terceiros, condução sob a influência de álcool ou drogas, transporte de mercadorias ilícitas ou fora da zona acordada.","it":"Il veicolo non può essere usato per attività illecite, gare, traino, guida fuoristrada salvo accordo, noleggio commerciale a terzi, guida sotto l'effetto di alcol o droghe, trasporto di merci illecite o al di fuori della zona concordata.","hr":"Vozilo se ne smije koristiti za nezakonite aktivnosti, utrke, vuču, vožnju izvan cesta osim ako je dogovoreno, komercijalni najam trećima, vožnju pod utjecajem alkohola ili droga, prijevoz nedopuštene robe niti izvan dogovorenog područja.","fr":"Le véhicule ne peut pas être utilisé pour des activités illicites, des courses, du remorquage, la conduite hors route sauf accord, la sous-location commerciale, la conduite sous l'emprise de l'alcool ou de stupéfiants, le transport de marchandises illicites ou en dehors de la zone convenue.","de":"Das Fahrzeug darf nicht für rechtswidrige Zwecke, Rennen, zum Abschleppen, im Gelände (sofern nicht vereinbart), zur gewerblichen Weitervermietung, unter dem Einfluss von Alkohol oder Drogen, zum Transport verbotener Waren oder außerhalb des vereinbarten Gebiets genutzt werden.","tr":"Araç; yasa dışı faaliyetlerde, yarışlarda, çekme işinde, kararlaştırılmadıkça arazi sürüşünde, üçüncü kişilere ticari kiralamada, alkol veya uyuşturucu etkisi altında, yasa dışı yük taşımada veya kararlaştırılan bölge dışında kullanılamaz."},
  {"th":"พื้นที่เดินทางปกติที่อนุญาตคือ {{home_territory}} การเดินทางออกนอกพื้นที่นี้ต้องแจ้งล่วงหน้าหรือได้รับอนุมัติเป็นลายลักษณ์อักษรตามนโยบายของผู้ให้เช่า","id":"Wilayah perjalanan normal yang diizinkan adalah {{home_territory}}. Perjalanan ke luar wilayah ini memerlukan pemberitahuan sebelumnya atau persetujuan tertulis sesuai kebijakan Pemilik.","vi":"Khu vực được phép đi lại thông thường là {{home_territory}}. Việc đi ra ngoài khu vực này cần thông báo trước hoặc được chấp thuận bằng văn bản theo chính sách của Bên cho thuê.","ms":"Kawasan perjalanan biasa yang dibenarkan ialah {{home_territory}}. Perjalanan ke luar kawasan ini memerlukan notis terlebih dahulu atau kelulusan bertulis mengikut polisi Pemilik.","fil":"Ang karaniwang pinahihintulutang lugar ng paglalakbay ay {{home_territory}}. Ang paglalakbay sa labas ng lugar na ito ay nangangailangan ng paunang abiso o nakasulat na pahintulot ayon sa patakaran ng May-ari.","lo":"ພື້ນທີ່ເດີນທາງປົກກະຕິທີ່ອະນຸຍາດແມ່ນ {{home_territory}}. ການເດີນທາງອອກນອກພື້ນທີ່ນີ້ຕ້ອງແຈ້ງລ່ວງໜ້າ ຫຼື ໄດ້ຮັບອະນຸມັດເປັນລາຍລັກອັກສອນຕາມນະໂຍບາຍຂອງຜູ້ໃຫ້ເຊົ່າ.","km":"តំបន់ធ្វើដំណើរធម្មតាដែលអនុញ្ញាតគឺ {{home_territory}}។ ការធ្វើដំណើរក្រៅតំបន់នេះត្រូវជូនដំណឹងជាមុន ឬទទួលបានការយល់ព្រមជាលាយលក្ខណ៍អក្សរតាមគោលការណ៍របស់អ្នកឲ្យជួល។","el":"Η επιτρεπόμενη περιοχή κυκλοφορίας είναι {{home_territory}}. Για μετακίνηση εκτός αυτής απαιτείται προηγούμενη ειδοποίηση ή γραπτή έγκριση σύμφωνα με την πολιτική του Εκμισθωτή.","es":"La zona de circulación permitida es {{home_territory}}. Circular fuera de esta zona requiere aviso previo o autorización por escrito según la política del Propietario.","pt":"A zona de circulação permitida é {{home_territory}}. Circular fora desta zona exige aviso prévio ou autorização escrita, de acordo com a política do Locador.","it":"La zona di circolazione consentita è {{home_territory}}. Per circolare al di fuori di questa zona occorre un preavviso o un'autorizzazione scritta secondo le regole del Locatore.","hr":"Dopušteno područje vožnje je {{home_territory}}. Za vožnju izvan tog područja potrebna je prethodna obavijest ili pisano odobrenje prema pravilima Najmodavca.","fr":"La zone de circulation autorisée est {{home_territory}}. Tout déplacement hors de cette zone nécessite un préavis ou un accord écrit selon les règles du Loueur.","de":"Das zulässige Fahrgebiet ist {{home_territory}}. Fahrten außerhalb dieses Gebiets erfordern eine vorherige Mitteilung oder schriftliche Zustimmung nach den Regeln des Vermieters.","tr":"İzin verilen kullanım bölgesi {{home_territory}} şeklindedir. Bu bölgenin dışına çıkılması, Kiraya Verenin politikasına göre önceden bildirim veya yazılı izin gerektirir."},
  {"th":"การเดินทางข้ามเกาะหรือโดยเรือเฟอร์รี่ต้องแจ้งก่อนเดินทาง ผู้เช่ารับผิดชอบต่อความล่าช้าของเรือ ความเสียหายจากการขนส่งทางเรือ การคืนรถล่าช้า และค่าใช้จ่ายในการกู้คืนเพิ่มเติม","id":"Perjalanan antarpulau atau dengan kapal feri wajib diberitahukan sebelum berangkat. Penyewa tetap bertanggung jawab atas keterlambatan feri, kerusakan selama penyeberangan, keterlambatan pengembalian dan biaya pemulihan tambahan.","vi":"Việc đi ra đảo hoặc đi phà phải được thông báo trước. Bên thuê chịu trách nhiệm về việc phà bị trễ, hư hỏng khi đi phà, trả xe trễ và mọi chi phí thu hồi phát sinh.","ms":"Perjalanan ke pulau atau dengan feri mesti dimaklumkan sebelum perjalanan. Penyewa kekal bertanggungjawab atas kelewatan feri, kerosakan semasa di atas feri, pemulangan lewat dan sebarang kos pemulihan tambahan.","fil":"Dapat ipaalam bago bumiyahe ang paglalakbay sa ibang isla o sakay ng ferry. Mananagot ang Umuupa sa pagkaantala ng ferry, sira habang nasa ferry, huling pagbabalik at anumang karagdagang gastos sa pagbawi.","lo":"ການເດີນທາງຂ້າມເກາະ ຫຼື ໂດຍເຮືອຂ້າມຟາກຕ້ອງແຈ້ງກ່ອນເດີນທາງ. ຜູ້ເຊົ່າຮັບຜິດຊອບຕໍ່ຄວາມຊັກຊ້າຂອງເຮືອ, ຄວາມເສຍຫາຍໃນເວລາຂົນສົ່ງທາງເຮືອ, ການສົ່ງລົດຄືນຊັກຊ້າ ແລະ ຄ່າໃຊ້ຈ່າຍໃນການກູ້ຄືນເພີ່ມເຕີມ.","km":"ការធ្វើដំណើរទៅកោះ ឬតាមសាឡាងត្រូវជូនដំណឹងមុនពេលធ្វើដំណើរ។ អ្នកជួលទទួលខុសត្រូវចំពោះការយឺតយ៉ាវរបស់សាឡាង ការខូចខាតពេលនៅលើសាឡាង ការប្រគល់យឺត និងថ្លៃដកយកមកវិញបន្ថែម។","el":"Η μετάβαση σε άλλο νησί ή με πλοίο πρέπει να δηλώνεται πριν από το ταξίδι. Ο Μισθωτής ευθύνεται για καθυστερήσεις του πλοίου, ζημιές κατά τη μεταφορά, καθυστερημένη επιστροφή και κάθε πρόσθετο κόστος επαναφοράς του οχήματος.","es":"Los desplazamientos a otras islas o en ferry deben comunicarse antes de realizarlos. El Arrendatario responde de los retrasos del ferry, los daños durante la travesía, los retrasos en la devolución y cualquier coste adicional de recuperación.","pt":"As deslocações a outras ilhas ou de ferry devem ser comunicadas antes de serem feitas. O Locatário responde pelos atrasos do ferry, pelos danos durante a travessia, pelos atrasos na devolução e por quaisquer custos adicionais de recuperação.","it":"Gli spostamenti verso altre isole o in traghetto devono essere comunicati prima della partenza. Il Conduttore risponde dei ritardi del traghetto, dei danni durante la traversata, dei ritardi nella riconsegna e degli eventuali costi di recupero aggiuntivi.","hr":"Putovanje na druge otoke ili trajektom mora se prijaviti prije polaska. Najmoprimac odgovara za kašnjenja trajekta, oštećenja tijekom prijevoza, kasni povrat i sve dodatne troškove povrata vozila.","fr":"Tout déplacement vers une autre île ou en ferry doit être signalé avant le départ. Le Locataire répond des retards de ferry, des dommages pendant la traversée, des retards de restitution et de tout frais de récupération supplémentaire.","de":"Fahrten auf andere Inseln oder mit der Fähre sind vor Antritt mitzuteilen. Der Mieter haftet für Verspätungen der Fähre, Schäden während der Überfahrt, verspätete Rückgabe und zusätzliche Rückführungskosten.","tr":"Başka adalara veya feribotla yapılacak yolculuklar önceden bildirilmelidir. Feribot gecikmelerinden, deniz yolculuğu sırasındaki hasarlardan, iadedeki gecikmelerden ve ek geri alma masraflarından Kiracı sorumludur."},
  {"th":"อาจต้องชำระเงินประกันการเดินทางเพิ่มเติมจำนวน ฿{{secondary_deposit_amount}} ก่อนการเดินทางข้ามเกาะหรือไปแผ่นดินใหญ่ที่ได้รับอนุมัติ","id":"Uang jaminan perjalanan tambahan sebesar {{currency_symbol}}{{secondary_deposit_amount}} dapat diminta sebelum perjalanan antarpulau atau ke daratan utama yang disetujui.","vi":"Có thể yêu cầu một khoản đặt cọc đi lại bổ sung {{currency_symbol}}{{secondary_deposit_amount}} trước khi đi ra đảo khác hoặc vào đất liền đã được chấp thuận.","ms":"Cagaran perjalanan tambahan sebanyak {{currency_symbol}}{{secondary_deposit_amount}} mungkin diperlukan sebelum perjalanan antara pulau atau ke tanah besar yang diluluskan.","fil":"Maaaring hingin ang karagdagang deposito sa paglalakbay na {{currency_symbol}}{{secondary_deposit_amount}} bago ang aprubadong paglalakbay sa ibang isla o sa mainland.","lo":"ອາດຕ້ອງຊຳລະເງິນມັດຈຳການເດີນທາງເພີ່ມເຕີມຈຳນວນ {{currency_symbol}}{{secondary_deposit_amount}} ກ່ອນການເດີນທາງຂ້າມເກາະ ຫຼື ໄປແຜ່ນດິນໃຫຍ່ທີ່ໄດ້ຮັບອະນຸມັດ.","km":"ប្រាក់កក់សម្រាប់ការធ្វើដំណើរបន្ថែមចំនួន {{currency_symbol}}{{secondary_deposit_amount}} អាចត្រូវបានទាមទារមុនការធ្វើដំណើរទៅកោះផ្សេង ឬដីគោកដែលបានអនុម័ត។","el":"Πριν από εγκεκριμένη μετάβαση σε άλλο νησί ή στην ηπειρωτική χώρα μπορεί να ζητηθεί πρόσθετη εγγύηση ταξιδιού {{currency_symbol}}{{secondary_deposit_amount}}.","es":"Puede exigirse una fianza adicional de viaje de {{currency_symbol}}{{secondary_deposit_amount}} antes de un desplazamiento autorizado a otra isla o a la península.","pt":"Pode ser exigida uma caução de viagem adicional de {{currency_symbol}}{{secondary_deposit_amount}} antes de uma deslocação autorizada a outra ilha ou ao continente.","it":"Prima di uno spostamento autorizzato verso un'altra isola o la terraferma può essere richiesto un deposito di viaggio aggiuntivo di {{currency_symbol}}{{secondary_deposit_amount}}.","hr":"Prije odobrenog putovanja na drugi otok ili na kopno može se zatražiti dodatna putna jamčevina od {{currency_symbol}}{{secondary_deposit_amount}}.","fr":"Un dépôt de garantie de déplacement supplémentaire de {{currency_symbol}}{{secondary_deposit_amount}} peut être exigé avant un déplacement autorisé vers une autre île ou le continent.","de":"Vor einer genehmigten Fahrt auf eine andere Insel oder auf das Festland kann eine zusätzliche Reisekaution von {{currency_symbol}}{{secondary_deposit_amount}} verlangt werden.","tr":"İzin verilen bir ada veya anakara yolculuğundan önce {{currency_symbol}}{{secondary_deposit_amount}} tutarında ek seyahat depozitosu istenebilir."},
  {"th":"ยานพาหนะอาจถูกติดตามด้วยระบบ GPS หรือ geofence เพื่อความปลอดภัย การปฏิบัติตามเงื่อนไข และการกู้คืนยานพาหนะ","id":"Kendaraan dapat dipantau dengan GPS atau sistem geofence untuk keselamatan, kepatuhan dan pemulihan kendaraan.","vi":"Xe có thể được theo dõi bằng GPS hoặc hệ thống hàng rào địa lý (geofence) vì mục đích an toàn, tuân thủ và thu hồi xe.","ms":"Kenderaan mungkin dipantau melalui GPS atau sistem geofence bagi tujuan keselamatan, pematuhan dan pemulihan.","fil":"Maaaring subaybayan ang sasakyan gamit ang GPS o geofence para sa kaligtasan, pagsunod at pagbawi.","lo":"ຍານພາຫະນະອາດຖືກຕິດຕາມດ້ວຍລະບົບ GPS ຫຼື geofence ເພື່ອຄວາມປອດໄພ, ການປະຕິບັດຕາມເງື່ອນໄຂ ແລະ ການກູ້ຄືນຍານພາຫະນະ.","km":"យានយន្តអាចត្រូវបានតាមដានដោយប្រព័ន្ធ GPS ឬ geofence ដើម្បីសុវត្ថិភាព ការអនុវត្តតាមលក្ខខណ្ឌ និងការដកយកមកវិញ។","el":"Το όχημα μπορεί να εντοπίζεται μέσω GPS ή συστήματος γεωπεριφράξης για λόγους ασφάλειας, τήρησης της σύμβασης και ανάκτησης.","es":"El vehículo puede estar localizado mediante GPS o geocercas con fines de seguridad, cumplimiento del contrato y recuperación.","pt":"O veículo pode ser localizado por GPS ou sistemas de geovedação para fins de segurança, cumprimento do contrato e recuperação.","it":"Il veicolo può essere localizzato tramite GPS o sistemi di geofencing per finalità di sicurezza, rispetto del contratto e recupero.","hr":"Vozilo se može pratiti GPS-om ili sustavom geofencinga radi sigurnosti, poštivanja ugovora i povrata vozila.","fr":"Le véhicule peut être localisé par GPS ou géorepérage à des fins de sécurité, de respect du contrat et de récupération.","de":"Das Fahrzeug kann zu Sicherheits-, Vertragskontroll- und Rückführungszwecken per GPS oder Geofencing geortet werden.","tr":"Araç; güvenlik, sözleşmeye uyum ve aracın geri alınması amacıyla GPS veya coğrafi sınır (geofence) sistemleriyle izlenebilir."},
  {"th":"ยานพาหนะได้รับความคุ้มครองด้วยประกันภัยภาคสมัครใจประเภท 1 ที่มีผลบังคับใช้ทั่วราชอาณาจักรไทย ผู้เช่าจะถูกเพิ่มเป็นผู้ขับขี่ที่ระบุชื่อในกรมธรรม์ ในกรณีที่มีการเรียกร้องประกันภัย ค่าใช้จ่ายที่เกิดขึ้นจะถูกหักจากเงินประกัน ซึ่งต้องชำระทดแทน","id":"Kendaraan diasuransikan sebagaimana dinyatakan oleh Pemilik, termasuk asuransi tanggung jawab pihak ketiga apa pun yang diwajibkan oleh hukum di Indonesia. Penyewa ditanggung sebagai pengemudi yang disebut dalam perjanjian ini. Jika ada klaim asuransi, biaya yang timbul akan diambil dari uang jaminan, yang kemudian wajib diisi kembali.","vi":"Xe được bảo hiểm theo nội dung Bên cho thuê đã nêu, bao gồm bảo hiểm trách nhiệm dân sự đối với bên thứ ba mà pháp luật Việt Nam bắt buộc. Bên thuê được bảo hiểm với tư cách người lái có tên trong hợp đồng này. Khi có yêu cầu bồi thường bảo hiểm, các chi phí liên quan sẽ được trừ vào tiền đặt cọc và Bên thuê phải bổ sung lại khoản đặt cọc.","ms":"Kenderaan diinsuranskan sebagaimana yang dinyatakan oleh Pemilik, termasuk insurans liabiliti pihak ketiga yang diwajibkan oleh undang-undang di Malaysia. Penyewa dilindungi sebagai pemandu yang dinamakan dalam perjanjian ini. Sekiranya terdapat tuntutan insurans, kos yang berkaitan akan diambil daripada wang cagaran, yang kemudiannya mesti ditambah semula.","fil":"Ang sasakyan ay nakaseguro ayon sa nakasaad ng May-ari, kasama ang third-party liability insurance na hinihingi ng batas sa Pilipinas. Saklaw ang Umuupa bilang drayber na nakapangalan sa kasunduang ito. Kapag may claim sa insurance, ang mga gastos ay kukunin mula sa deposito, na kailangang punan muli.","lo":"ຍານພາຫະນະມີປະກັນໄພຕາມທີ່ຜູ້ໃຫ້ເຊົ່າໄດ້ລະບຸໄວ້ ລວມທັງປະກັນໄພຄວາມຮັບຜິດຊອບຕໍ່ບຸກຄົນທີສາມທີ່ກົດໝາຍຂອງ ສປປ ລາວ ກຳນົດ. ຜູ້ເຊົ່າໄດ້ຮັບຄວາມຄຸ້ມຄອງໃນຖານະຜູ້ຂັບຂີ່ທີ່ມີຊື່ໃນສັນຍານີ້. ໃນກໍລະນີມີການຮຽກຮ້ອງປະກັນໄພ ຄ່າໃຊ້ຈ່າຍທີ່ກ່ຽວຂ້ອງຈະຖືກຫັກຈາກເງິນມັດຈຳ ເຊິ່ງຜູ້ເຊົ່າຕ້ອງເຕີມຄືນ.","km":"យានយន្តមានការធានារ៉ាប់រងតាមការបញ្ជាក់របស់អ្នកឲ្យជួល រួមទាំងការធានារ៉ាប់រងទំនួលខុសត្រូវចំពោះភាគីទីបីដែលច្បាប់នៃព្រះរាជាណាចក្រកម្ពុជាតម្រូវ។ អ្នកជួលត្រូវបានធានារ៉ាប់រងក្នុងនាមជាអ្នកបើកបរដែលមានឈ្មោះក្នុងកិច្ចសន្យានេះ។ ក្នុងករណីមានការទាមទារសំណងធានារ៉ាប់រង ថ្លៃចំណាយពាក់ព័ន្ធនឹងត្រូវកាត់ពីប្រាក់កក់ ដែលអ្នកជួលត្រូវបំពេញវិញ។","el":"Το όχημα είναι ασφαλισμένο όπως δηλώνει ο Εκμισθωτής, συμπεριλαμβανομένης της υποχρεωτικής ασφάλισης αστικής ευθύνης έναντι τρίτων που προβλέπει ο νόμος στην {{agreement_country_2}}. Ο Μισθωτής καλύπτεται ως οδηγός που αναφέρεται στην παρούσα σύμβαση. Σε περίπτωση ασφαλιστικής απαίτησης, τα σχετικά ποσά θα παρακρατηθούν από την εγγύηση, η οποία πρέπει στη συνέχεια να συμπληρωθεί.","es":"El vehículo está asegurado en los términos indicados por el Propietario, incluido el seguro obligatorio de responsabilidad civil frente a terceros que exige la ley en España. El Arrendatario está cubierto como conductor designado en este contrato. En caso de siniestro, los costes que correspondan se descontarán de la fianza, que deberá reponerse.","pt":"O veículo está seguro nos termos indicados pelo Locador, incluindo o seguro obrigatório de responsabilidade civil automóvel exigido por lei em Portugal. O Locatário está coberto como condutor identificado neste contrato. Em caso de sinistro, os custos aplicáveis serão deduzidos da caução, que deverá ser reposta.","it":"Il veicolo è assicurato come indicato dal Locatore, compresa l'assicurazione obbligatoria di responsabilità civile verso terzi prevista dalla legge in Italia. Il Conduttore è coperto in quanto conducente indicato nel presente contratto. In caso di sinistro, i costi applicabili saranno trattenuti dal deposito cauzionale, che dovrà essere reintegrato.","hr":"Vozilo je osigurano kako je naveo Najmodavac, uključujući obvezno osiguranje od automobilske odgovornosti propisano zakonom u Hrvatskoj. Najmoprimac je pokriven kao vozač naveden u ovom ugovoru. U slučaju štete, pripadajući troškovi odbit će se od jamčevine, koju je potom potrebno nadoknaditi.","fr":"Le véhicule est assuré dans les conditions indiquées par le Loueur, y compris l'assurance obligatoire de responsabilité civile automobile exigée par la loi en France. Le Locataire est couvert en tant que conducteur désigné au présent contrat. En cas de sinistre, les sommes applicables sont prélevées sur le dépôt de garantie, qui doit alors être reconstitué.","de":"Das Fahrzeug ist wie vom Vermieter angegeben versichert, einschließlich der gesetzlich vorgeschriebenen Kfz-Haftpflichtversicherung in Deutschland. Der Mieter ist als in diesem Vertrag genannter Fahrer versichert. Im Schadensfall werden die anfallenden Kosten von der Kaution einbehalten, die anschließend wieder aufzufüllen ist.","tr":"Araç, Kiraya Verenin belirttiği şekilde ve Türkiye'de kanunen zorunlu olan Zorunlu Mali Sorumluluk (Trafik) Sigortası dâhil olmak üzere sigortalıdır. Kiracı, işbu sözleşmede adı geçen sürücü olarak teminat kapsamındadır. Bir sigorta talebi hâlinde ilgili masraflar depozitodan mahsup edilir ve depozitonun yeniden tamamlanması gerekir."},
  {"th":"ผู้เช่าต้องคืนยานพาหนะในสภาพสะอาด พร้อมระดับน้ำมันที่ตกลงกัน กุญแจ อุปกรณ์ และเอกสาร ผู้ให้เช่าสามารถตรวจสภาพเมื่อคืนรถและบันทึกเลขไมล์ น้ำมัน รูปภาพ และความเสียหายได้","id":"Kendaraan wajib dikembalikan dalam keadaan bersih, dengan tingkat bahan bakar yang disepakati, kunci, perlengkapan dan dokumen. Pemilik dapat memeriksa kendaraan saat pengembalian dan mencatat jarak tempuh, bahan bakar, foto dan kerusakan.","vi":"Xe phải được trả trong tình trạng sạch sẽ, với mức nhiên liệu đã thỏa thuận, chìa khóa, phụ kiện và giấy tờ. Bên cho thuê có thể kiểm tra xe khi nhận lại và ghi nhận số km, nhiên liệu, hình ảnh và hư hỏng.","ms":"Kenderaan mesti dipulangkan dalam keadaan bersih, dengan paras bahan api yang dipersetujui, kunci, aksesori dan dokumen. Pemilik boleh memeriksa kenderaan semasa pemulangan dan merekodkan perbatuan, bahan api, gambar dan kerosakan.","fil":"Dapat ibalik ang sasakyan nang malinis, may napagkasunduang antas ng panggatong, mga susi, aksesorya at dokumento. Maaaring inspeksyunin ng May-ari ang sasakyan sa pagbabalik at itala ang mileage, panggatong, mga larawan at sira.","lo":"ຜູ້ເຊົ່າຕ້ອງສົ່ງຄືນຍານພາຫະນະໃນສະພາບສະອາດ ພ້ອມລະດັບນ້ຳມັນທີ່ຕົກລົງກັນ, ກະແຈ, ອຸປະກອນ ແລະ ເອກະສານ. ຜູ້ໃຫ້ເຊົ່າສາມາດກວດສະພາບເມື່ອຮັບລົດຄືນ ແລະ ບັນທຶກເລກໄມ, ນ້ຳມັນ, ຮູບພາບ ແລະ ຄວາມເສຍຫາຍໄດ້.","km":"យានយន្តត្រូវប្រគល់វិញក្នុងស្ថានភាពស្អាត ជាមួយកម្រិតឥន្ធនៈដែលបានព្រមព្រៀង សោ គ្រឿងបន្លាស់ និងឯកសារ។ អ្នកឲ្យជួលអាចត្រួតពិនិត្យយានយន្តពេលប្រគល់វិញ ហើយកត់ត្រាចម្ងាយ ឥន្ធនៈ រូបថត និងការខូចខាត។","el":"Το όχημα πρέπει να επιστραφεί καθαρό, με τη συμφωνημένη στάθμη καυσίμου, τα κλειδιά, τα εξαρτήματα και τα έγγραφα. Ο Εκμισθωτής μπορεί να ελέγξει το όχημα κατά την επιστροφή και να καταγράψει χιλιόμετρα, καύσιμο, φωτογραφίες και ζημιές.","es":"El vehículo debe devolverse limpio, con el nivel de combustible acordado, las llaves, los accesorios y la documentación. El Propietario puede revisar el vehículo a su devolución y anotar el kilometraje, el combustible, fotografías y daños.","pt":"O veículo deve ser devolvido limpo, com o nível de combustível acordado, as chaves, os acessórios e os documentos. O Locador pode inspecionar o veículo na devolução e registar a quilometragem, o combustível, fotografias e danos.","it":"Il veicolo deve essere restituito pulito, con il livello di carburante concordato, le chiavi, gli accessori e i documenti. Alla riconsegna il Locatore può ispezionare il veicolo e annotare chilometraggio, carburante, fotografie e danni.","hr":"Vozilo se mora vratiti čisto, s dogovorenom razinom goriva, ključevima, opremom i dokumentima. Najmodavac može pri povratu pregledati vozilo i zabilježiti kilometražu, gorivo, fotografije i oštećenja.","fr":"Le véhicule doit être restitué propre, avec le niveau de carburant convenu, les clés, les accessoires et les documents. Le Loueur peut inspecter le véhicule à son retour et relever le kilométrage, le carburant, des photos et les dommages.","de":"Das Fahrzeug ist sauber, mit dem vereinbarten Tankstand, den Schlüsseln, dem Zubehör und den Papieren zurückzugeben. Der Vermieter kann das Fahrzeug bei Rückgabe prüfen und Kilometerstand, Tankstand, Fotos und Schäden festhalten.","tr":"Araç temiz olarak, kararlaştırılan yakıt seviyesinde, anahtarları, donanımı ve belgeleriyle birlikte iade edilmelidir. Kiraya Veren aracı iade sırasında kontrol edebilir ve kilometreyi, yakıtı, fotoğrafları ve hasarları kaydedebilir."},
  {"th":"ผู้เช่าห้ามแก้ไขหรือรบกวนเลขไมล์หรืออุปกรณ์ GPS หากพิสูจน์ได้ว่ามีการแก้ไข ผู้ให้เช่ามีสิทธิเรียกค่าเสียหายที่เกิดจากการแก้ไขนั้น รวมถึงหักจากเงินประกัน","id":"Penyewa tidak boleh mengubah atau mengganggu odometer atau perangkat GPS. Jika manipulasi terbukti, Pemilik berhak menuntut ganti rugi atas kerugian yang ditimbulkannya, termasuk dengan memotong uang jaminan.","vi":"Bên thuê không được can thiệp vào đồng hồ công-tơ-mét hoặc thiết bị GPS. Nếu việc can thiệp được chứng minh, Bên cho thuê có quyền yêu cầu bồi thường thiệt hại do việc đó gây ra, kể cả bằng cách trừ vào tiền đặt cọc.","ms":"Penyewa tidak boleh mengusik odometer atau peranti GPS. Jika usikan dibuktikan, Pemilik berhak menuntut kerugian yang disebabkannya, termasuk dengan menolak daripada wang cagaran.","fil":"Hindi dapat pakialaman ng Umuupa ang odometer o GPS device. Kapag napatunayan ang pakikialam, maaaring singilin ng May-ari ang mga pinsalang idinulot nito, kabilang ang pagbabawas mula sa deposito.","lo":"ຜູ້ເຊົ່າຫ້າມແກ້ໄຂ ຫຼື ລົບກວນໜ້າປັດໄມ ຫຼື ອຸປະກອນ GPS. ຖ້າພິສູດໄດ້ວ່າມີການແກ້ໄຂ ຜູ້ໃຫ້ເຊົ່າມີສິດຮຽກຮ້ອງຄ່າເສຍຫາຍທີ່ເກີດຈາກການແກ້ໄຂນັ້ນ ລວມທັງຫັກຈາກເງິນມັດຈຳ.","km":"អ្នកជួលមិនត្រូវកែប្រែ ឬរំខានកុងទ័រ ឬឧបករណ៍ GPS ឡើយ។ ប្រសិនបើមានភស្តុតាងថាមានការកែប្រែ អ្នកឲ្យជួលអាចទាមទារសំណងលើការខូចខាតដែលបណ្តាលមកពីការកែប្រែនោះ រួមទាំងដោយកាត់ពីប្រាក់កក់។","el":"Ο Μισθωτής δεν πρέπει να παρεμβαίνει στον χιλιομετρητή ή στη συσκευή GPS. Αν αποδειχθεί παρέμβαση, ο Εκμισθωτής μπορεί να ζητήσει την αποκατάσταση της ζημίας που προκλήθηκε, και από την εγγύηση.","es":"El Arrendatario no debe manipular el cuentakilómetros ni el dispositivo GPS. Si se demuestra una manipulación, el Propietario podrá reclamar los perjuicios causados, incluso con cargo a la fianza.","pt":"O Locatário não deve manipular o conta-quilómetros nem o dispositivo GPS. Provada a manipulação, o Locador pode exigir os prejuízos causados, incluindo por dedução da caução.","it":"Il Conduttore non deve manomettere il contachilometri né il dispositivo GPS. In caso di manomissione accertata, il Locatore può chiedere il risarcimento dei danni causati, anche trattenendolo dal deposito cauzionale.","hr":"Najmoprimac ne smije dirati brojač kilometara ni GPS uređaj. Ako se manipulacija dokaže, Najmodavac može naplatiti nastalu štetu, uključujući iz jamčevine.","fr":"Le Locataire ne doit pas manipuler le compteur kilométrique ni le dispositif GPS. Une manipulation avérée permet au Loueur d'obtenir réparation du préjudice causé, y compris sur le dépôt de garantie.","de":"Der Mieter darf den Kilometerzähler und das GPS-Gerät nicht manipulieren. Bei nachgewiesener Manipulation kann der Vermieter den dadurch entstandenen Schaden ersetzt verlangen, auch durch Einbehalt von der Kaution.","tr":"Kiracı kilometre sayacına veya GPS cihazına müdahale edemez. Müdahale ispatlanırsa Kiraya Veren, sebep olunan zararı depozitodan mahsup etmek dâhil olmak üzere talep edebilir."},
  {"th":"ผู้เช่ารับผิดชอบค่าปรับจราจร ค่าจอดรถ ค่าทางด่วน เบี้ยปรับ ค่าลากหรือยึดรถ และค่าดำเนินการที่เกิดขึ้นระหว่างระยะเวลาเช่า","id":"Penyewa bertanggung jawab atas semua denda lalu lintas, biaya parkir, tol, sanksi, biaya penderekan atau penyitaan dan biaya administrasi yang timbul selama masa sewa.","vi":"Bên thuê chịu trách nhiệm về mọi khoản phạt giao thông, phí đỗ xe, phí cầu đường, tiền phạt, phí kéo hoặc tạm giữ xe và phí hành chính phát sinh trong thời gian thuê.","ms":"Penyewa bertanggungjawab atas semua saman lalu lintas, caj letak kereta, tol, penalti, fi tunda atau sitaan dan caj pentadbiran yang timbul dalam tempoh sewa.","fil":"Ang Umuupa ang mananagot sa lahat ng multa sa trapiko, bayad sa paradahan, toll, parusa, bayad sa paghila o impound at mga administratibong singil sa panahon ng upa.","lo":"ຜູ້ເຊົ່າຮັບຜິດຊອບຄ່າປັບຈະລາຈອນ, ຄ່າຈອດລົດ, ຄ່າທາງດ່ວນ, ຄ່າປັບໃໝ, ຄ່າລາກ ຫຼື ຍຶດລົດ ແລະ ຄ່າດຳເນີນການທີ່ເກີດຂຶ້ນລະຫວ່າງໄລຍະເວລາເຊົ່າ.","km":"អ្នកជួលទទួលខុសត្រូវលើការពិន័យចរាចរណ៍ ថ្លៃចំណត ថ្លៃផ្លូវ ការផាកពិន័យ ថ្លៃអូស ឬរឹបអូសយានយន្ត និងថ្លៃរដ្ឋបាលទាំងអស់ដែលកើតឡើងក្នុងរយៈពេលជួល។","el":"Ο Μισθωτής ευθύνεται για όλα τα πρόστιμα τροχαίας, τα τέλη στάθμευσης, τα διόδια, τις κυρώσεις, τα έξοδα ρυμούλκησης και φύλαξης και τα διοικητικά έξοδα που προκύπτουν κατά τη μίσθωση.","es":"El Arrendatario es responsable de todas las multas de tráfico, gastos de aparcamiento, peajes, sanciones, gastos de grúa y depósito y gastos de gestión generados durante el periodo de alquiler.","pt":"O Locatário é responsável por todas as coimas de trânsito, estacionamento, portagens, sanções, custos de reboque e de parque e encargos administrativos gerados durante o período de aluguer.","it":"Il Conduttore è responsabile di tutte le multe stradali, soste a pagamento, pedaggi, sanzioni, spese di rimozione e custodia e spese amministrative maturate durante il periodo di noleggio.","hr":"Najmoprimac odgovara za sve prometne kazne, parkiranje, cestarine, prekršajne naknade, troškove premještanja i čuvanja vozila te administrativne troškove nastale tijekom najma.","fr":"Le Locataire est responsable de toutes les amendes, frais de stationnement, péages, pénalités, frais de fourrière et frais administratifs générés pendant la durée de la location.","de":"Der Mieter trägt alle Bußgelder, Verwarnungsgelder, Parkgebühren, Mautgebühren, Abschlepp- und Verwahrkosten sowie Verwaltungskosten, die während der Mietzeit entstehen.","tr":"Kiralama süresince doğan tüm trafik cezaları, otopark ücretleri, köprü ve otoyol geçiş ücretleri, idari para cezaları, çekici ve otopark (yed-i emin) masrafları ile işlem giderlerinden Kiracı sorumludur."},
  {"th":"ผู้ให้เช่าสามารถยกเลิกสัญญาและนำยานพาหนะคืนได้ทันที หากผู้เช่าฝ่าฝืนสัญญา ไม่ชำระเงิน ให้ข้อมูลเท็จ ทิ้งยานพาหนะ หรือทำให้ยานพาหนะตกอยู่ในความเสี่ยง","id":"Pemilik dapat mengakhiri perjanjian ini dan segera menarik kembali kendaraan jika Penyewa melanggar perjanjian ini, tidak membayar, memberikan informasi palsu, menelantarkan kendaraan, atau membahayakan kendaraan.","vi":"Bên cho thuê có thể chấm dứt hợp đồng này và thu hồi xe ngay lập tức nếu Bên thuê vi phạm hợp đồng, không thanh toán, cung cấp thông tin sai, bỏ xe hoặc đặt xe vào tình trạng nguy hiểm.","ms":"Pemilik boleh menamatkan perjanjian ini dan mengambil semula kenderaan serta-merta jika Penyewa melanggar perjanjian ini, gagal membayar, memberikan maklumat palsu, meninggalkan kenderaan, atau meletakkan kenderaan dalam risiko.","fil":"Maaaring wakasan ng May-ari ang kasunduang ito at agad na bawiin ang sasakyan kung lumabag ang Umuupa sa kasunduang ito, hindi nagbayad, nagbigay ng maling impormasyon, iniwan ang sasakyan, o inilagay ito sa panganib.","lo":"ຜູ້ໃຫ້ເຊົ່າສາມາດຍົກເລີກສັນຍາ ແລະ ຍຶດຍານພາຫະນະຄືນໄດ້ທັນທີ ຖ້າຜູ້ເຊົ່າລະເມີດສັນຍາ, ບໍ່ຊຳລະເງິນ, ໃຫ້ຂໍ້ມູນບໍ່ຖືກຕ້ອງ, ປະຖິ້ມຍານພາຫະນະ ຫຼື ເຮັດໃຫ້ຍານພາຫະນະຕົກຢູ່ໃນຄວາມສ່ຽງ.","km":"អ្នកឲ្យជួលអាចបញ្ចប់កិច្ចសន្យានេះ និងដកយានយន្តវិញភ្លាមៗ ប្រសិនបើអ្នកជួលបំពានកិច្ចសន្យា មិនបង់ប្រាក់ ផ្តល់ព័ត៌មានមិនពិត បោះបង់យានយន្ត ឬធ្វើឲ្យយានយន្តប្រឈមនឹងហានិភ័យ។","el":"Ο Εκμισθωτής μπορεί να καταγγείλει την παρούσα σύμβαση και να πάρει πίσω το όχημα αμέσως, αν ο Μισθωτής παραβεί τη σύμβαση, δεν πληρώσει, δώσει ψευδή στοιχεία, εγκαταλείψει το όχημα ή το θέσει σε κίνδυνο.","es":"El Propietario puede resolver este contrato y recuperar el vehículo de inmediato si el Arrendatario incumple el contrato, no paga, facilita datos falsos, abandona el vehículo o lo pone en peligro.","pt":"O Locador pode resolver este contrato e recuperar o veículo de imediato se o Locatário violar o contrato, não pagar, prestar informações falsas, abandonar o veículo ou o puser em risco.","it":"Il Locatore può risolvere il presente contratto e riprendere immediatamente il veicolo se il Conduttore viola il contratto, non paga, fornisce informazioni false, abbandona il veicolo o lo espone a rischio.","hr":"Najmodavac može raskinuti ovaj ugovor i odmah preuzeti vozilo ako Najmoprimac prekrši ugovor, ne plati, da lažne podatke, napusti vozilo ili ga izloži opasnosti.","fr":"Le Loueur peut résilier le présent contrat et reprendre immédiatement le véhicule si le Locataire manque à ses obligations, ne paie pas, fournit de fausses informations, abandonne le véhicule ou le met en danger.","de":"Der Vermieter kann diesen Vertrag fristlos kündigen und das Fahrzeug sofort zurücknehmen, wenn der Mieter gegen den Vertrag verstößt, nicht zahlt, falsche Angaben macht, das Fahrzeug zurücklässt oder es gefährdet.","tr":"Kiracının sözleşmeyi ihlal etmesi, ödeme yapmaması, yanlış bilgi vermesi, aracı terk etmesi veya tehlikeye sokması hâlinde Kiraya Veren işbu sözleşmeyi derhâl feshedebilir ve aracı geri alabilir."},
  {"th":"สัญญานี้อยู่ภายใต้กฎหมายของ {{jurisdiction}} ข้อพิพาทใด ๆ ควรเจรจาโดยสุจริตก่อนดำเนินการทางกฎหมาย","id":"Perjanjian ini tunduk pada hukum {{jurisdiction}}. Setiap perselisihan wajib terlebih dahulu dibicarakan dengan itikad baik sebelum menempuh jalur hukum.","vi":"Hợp đồng này được điều chỉnh bởi pháp luật của {{jurisdiction}}. Mọi tranh chấp trước hết phải được thương lượng thiện chí trước khi tiến hành thủ tục pháp lý.","ms":"Perjanjian ini ditadbir oleh undang-undang {{jurisdiction}}. Sebarang pertikaian mesti dibincangkan terlebih dahulu dengan suci hati sebelum tindakan undang-undang diambil.","fil":"Ang kasunduang ito ay pinamamahalaan ng mga batas ng {{jurisdiction}}. Ang anumang hindi pagkakasundo ay dapat munang pag-usapan nang may mabuting loob bago magsampa ng pormal na kaso.","lo":"ສັນຍານີ້ຢູ່ພາຍໃຕ້ກົດໝາຍຂອງ {{jurisdiction}}. ຂໍ້ຂັດແຍ່ງໃດໆ ຕ້ອງເຈລະຈາກັນດ້ວຍຄວາມສຸດຈະລິດກ່ອນດຳເນີນການທາງກົດໝາຍ.","km":"កិច្ចសន្យានេះស្ថិតក្រោមច្បាប់របស់ {{jurisdiction}}។ វិវាទណាមួយត្រូវពិភាក្សាដោយសុច្ឆន្ទៈជាមុនសិន មុននឹងចាត់វិធានការផ្លូវច្បាប់។","el":"Η παρούσα σύμβαση διέπεται από {{agreement_law_2}}. Τα μέρη θα επιδιώξουν να επιλύσουν καλόπιστα κάθε διαφορά πριν προσφύγουν στη δικαιοσύνη.","es":"Este contrato se rige por la legislación española. Las partes intentarán resolver de buena fe cualquier controversia antes de acudir a la vía judicial.","pt":"Este contrato rege-se pela lei portuguesa. As partes procurarão resolver de boa-fé qualquer litígio antes de recorrerem aos tribunais.","it":"Il presente contratto è regolato dalla legge italiana. Le parti cercheranno di risolvere in buona fede ogni controversia prima di adire le vie legali.","hr":"Na ovaj ugovor primjenjuje se hrvatsko pravo. Stranke će svaki spor najprije pokušati riješiti u dobroj vjeri prije pokretanja sudskog postupka.","fr":"Le présent contrat est régi par le droit français. Les parties s'efforceront de régler tout litige à l'amiable et de bonne foi avant toute action en justice.","de":"Dieser Vertrag unterliegt deutschem Recht. Die Parteien bemühen sich, Streitigkeiten zunächst in gutem Glauben beizulegen, bevor sie rechtliche Schritte einleiten.","tr":"İşbu sözleşmeye Türkiye Cumhuriyeti hukuku uygulanır. Taraflar, yargı yoluna başvurmadan önce her türlü uyuşmazlığı iyi niyetle çözmeye çalışır."},
  {"th":"<span class=\"clause-num\">18.1 การคืนเงินประกัน.</span> เงินประกันคงเหลือจะคืนโดยปกติภายใน {{deposit_return_days}} วันทำการ หลังจากตรวจคืนรถ กระทบยอดการชำระเงิน และยืนยันว่าไม่มีค่าปรับหรือค่าใช้จ่ายเพิ่มเติม","id":"<span class=\"clause-num\">18.1 Pengembalian uang jaminan.</span> Sisa uang jaminan biasanya dikembalikan dalam {{deposit_return_days}} hari kerja setelah pemeriksaan pengembalian, rekonsiliasi pembayaran dan konfirmasi bahwa tidak ada denda atau biaya lain yang terutang.","vi":"<span class=\"clause-num\">18.1 Hoàn trả tiền đặt cọc.</span> Số tiền đặt cọc còn lại thường được hoàn trả trong vòng {{deposit_return_days}} ngày làm việc sau khi kiểm tra trả xe, đối chiếu thanh toán và xác nhận không còn tiền phạt hay khoản phí nào khác.","ms":"<span class=\"clause-num\">18.1 Pemulangan wang cagaran.</span> Baki wang cagaran biasanya akan dipulangkan dalam tempoh {{deposit_return_days}} hari bekerja selepas pemeriksaan pemulangan, penyelarasan bayaran dan pengesahan bahawa tiada saman atau caj lain yang tertunggak.","fil":"<span class=\"clause-num\">18.1 Pagbabalik ng deposito.</span> Ang natitirang deposito ay karaniwang ibinabalik sa loob ng {{deposit_return_days}} araw ng trabaho pagkatapos ng inspeksyon sa pagbabalik, pagtutugma ng mga bayad at pagkumpirma na wala nang multa o singil na dapat bayaran.","lo":"<span class=\"clause-num\">18.1 ການຄືນເງິນມັດຈຳ.</span> ເງິນມັດຈຳທີ່ເຫຼືອຈະຄືນໃຫ້ຕາມປົກກະຕິພາຍໃນ {{deposit_return_days}} ວັນລັດຖະການ ຫຼັງຈາກກວດຮັບລົດຄືນ, ກວດສອບການຊຳລະເງິນ ແລະ ຢືນຢັນວ່າບໍ່ມີຄ່າປັບ ຫຼື ຄ່າໃຊ້ຈ່າຍເພີ່ມເຕີມ.","km":"<span class=\"clause-num\">18.1 ការសងប្រាក់កក់វិញ។</span> ប្រាក់កក់ដែលនៅសល់ជាធម្មតានឹងសងវិញក្នុងរយៈពេល {{deposit_return_days}} ថ្ងៃធ្វើការ បន្ទាប់ពីត្រួតពិនិត្យពេលប្រគល់ ផ្ទៀងផ្ទាត់ការបង់ប្រាក់ និងបញ្ជាក់ថាគ្មានការពិន័យ ឬថ្លៃផ្សេងទៀត។","el":"<span class=\"clause-num\">18.1 Επιστροφή εγγύησης.</span> Το υπόλοιπο της εγγύησης επιστρέφεται κανονικά εντός {{deposit_return_days}} εργάσιμων ημερών μετά τον έλεγχο επιστροφής, τη συμφωνία των πληρωμών και την επιβεβαίωση ότι δεν οφείλονται πρόστιμα ή χρεώσεις.","es":"<span class=\"clause-num\">18.1 Devolución de la fianza.</span> El saldo de la fianza se devolverá normalmente en un plazo de {{deposit_return_days}} días hábiles tras la inspección de devolución, la conciliación de pagos y la confirmación de que no quedan multas ni cargos pendientes.","pt":"<span class=\"clause-num\">18.1 Devolução da caução.</span> O saldo da caução é normalmente devolvido no prazo de {{deposit_return_days}} dias úteis após a inspeção de devolução, a conciliação dos pagamentos e a confirmação de que não há coimas nem encargos pendentes.","it":"<span class=\"clause-num\">18.1 Restituzione del deposito.</span> Il deposito residuo viene di norma restituito entro {{deposit_return_days}} giorni lavorativi dalla verifica di riconsegna, dalla riconciliazione dei pagamenti e dalla conferma che non restano multe o addebiti.","hr":"<span class=\"clause-num\">18.1 Povrat jamčevine.</span> Preostali iznos jamčevine u pravilu se vraća u roku od {{deposit_return_days}} radnih dana nakon pregleda pri povratu, usklađivanja plaćanja i potvrde da nema neplaćenih kazni ni troškova.","fr":"<span class=\"clause-num\">18.1 Restitution du dépôt.</span> Le solde du dépôt de garantie est normalement restitué dans un délai de {{deposit_return_days}} jours ouvrés après l'état des lieux de retour, le rapprochement des paiements et la confirmation qu'aucune amende ni aucun frais ne restent dus.","de":"<span class=\"clause-num\">18.1 Rückzahlung der Kaution.</span> Die restliche Kaution wird in der Regel innerhalb von {{deposit_return_days}} Werktagen nach der Rückgabeprüfung, dem Zahlungsabgleich und der Bestätigung, dass keine Bußgelder oder Kosten mehr offen sind, zurückgezahlt.","tr":"<span class=\"clause-num\">18.1 Depozitonun iadesi.</span> Depozitonun kalan tutarı, iade kontrolü, ödemelerin mutabakatı ve ödenmemiş ceza veya masraf kalmadığının teyidinden sonra normalde {{deposit_return_days}} iş günü içinde iade edilir."},
  {"th":"<span class=\"clause-num\">18.1 การคืนเงินประกัน.</span> เงินประกันคงเหลือจะคืนหลังจากตรวจคืนรถ กระทบยอดการชำระเงิน และยืนยันว่าไม่มีค่าปรับหรือค่าใช้จ่ายเพิ่มเติม","id":"<span class=\"clause-num\">18.1 Pengembalian uang jaminan.</span> Sisa uang jaminan dikembalikan setelah pemeriksaan pengembalian, rekonsiliasi pembayaran dan konfirmasi bahwa tidak ada denda atau biaya lain yang terutang.","vi":"<span class=\"clause-num\">18.1 Hoàn trả tiền đặt cọc.</span> Số tiền đặt cọc còn lại được hoàn trả sau khi kiểm tra trả xe, đối chiếu thanh toán và xác nhận không còn tiền phạt hay khoản phí nào khác.","ms":"<span class=\"clause-num\">18.1 Pemulangan wang cagaran.</span> Baki wang cagaran akan dipulangkan selepas pemeriksaan pemulangan, penyelarasan bayaran dan pengesahan bahawa tiada saman atau caj lain yang tertunggak.","fil":"<span class=\"clause-num\">18.1 Pagbabalik ng deposito.</span> Ang natitirang deposito ay ibinabalik pagkatapos ng inspeksyon sa pagbabalik, pagtutugma ng mga bayad at pagkumpirma na wala nang multa o singil na dapat bayaran.","lo":"<span class=\"clause-num\">18.1 ການຄືນເງິນມັດຈຳ.</span> ເງິນມັດຈຳທີ່ເຫຼືອຈະຄືນໃຫ້ຫຼັງຈາກກວດຮັບລົດຄືນ, ກວດສອບການຊຳລະເງິນ ແລະ ຢືນຢັນວ່າບໍ່ມີຄ່າປັບ ຫຼື ຄ່າໃຊ້ຈ່າຍເພີ່ມເຕີມ.","km":"<span class=\"clause-num\">18.1 ការសងប្រាក់កក់វិញ។</span> ប្រាក់កក់ដែលនៅសល់នឹងសងវិញ បន្ទាប់ពីត្រួតពិនិត្យពេលប្រគល់ ផ្ទៀងផ្ទាត់ការបង់ប្រាក់ និងបញ្ជាក់ថាគ្មានការពិន័យ ឬថ្លៃផ្សេងទៀត។","el":"<span class=\"clause-num\">18.1 Επιστροφή εγγύησης.</span> Το υπόλοιπο της εγγύησης επιστρέφεται μετά τον έλεγχο επιστροφής, τη συμφωνία των πληρωμών και την επιβεβαίωση ότι δεν οφείλονται πρόστιμα ή χρεώσεις.","es":"<span class=\"clause-num\">18.1 Devolución de la fianza.</span> El saldo de la fianza se devolverá tras la inspección de devolución, la conciliación de pagos y la confirmación de que no quedan multas ni cargos pendientes.","pt":"<span class=\"clause-num\">18.1 Devolução da caução.</span> O saldo da caução é devolvido após a inspeção de devolução, a conciliação dos pagamentos e a confirmação de que não há coimas nem encargos pendentes.","it":"<span class=\"clause-num\">18.1 Restituzione del deposito.</span> Il deposito residuo viene restituito dopo la verifica di riconsegna, la riconciliazione dei pagamenti e la conferma che non restano multe o addebiti.","hr":"<span class=\"clause-num\">18.1 Povrat jamčevine.</span> Preostali iznos jamčevine vraća se nakon pregleda pri povratu, usklađivanja plaćanja i potvrde da nema neplaćenih kazni ni troškova.","fr":"<span class=\"clause-num\">18.1 Restitution du dépôt.</span> Le solde du dépôt de garantie est restitué après l'état des lieux de retour, le rapprochement des paiements et la confirmation qu'aucune amende ni aucun frais ne restent dus.","de":"<span class=\"clause-num\">18.1 Rückzahlung der Kaution.</span> Die restliche Kaution wird nach der Rückgabeprüfung, dem Zahlungsabgleich und der Bestätigung, dass keine Bußgelder oder Kosten mehr offen sind, zurückgezahlt.","tr":"<span class=\"clause-num\">18.1 Depozitonun iadesi.</span> Depozitonun kalan tutarı, iade kontrolü, ödemelerin mutabakatı ve ödenmemiş ceza veya masraf kalmadığının teyidinden sonra iade edilir."},
  {"th":"<span class=\"clause-num\">18.2 การสูบบุหรี่และทำความสะอาด.</span> การสูบบุหรี่ สัตว์เลี้ยง ทรายมากเกินไป คราบ กลิ่น หรือความสกปรกเกินสมควร อาจมีค่าทำความสะอาดสูงสุด ฿{{smoking_fee_maximum}} หรือมากกว่านั้นหากต้องทำความสะอาดโดยผู้เชี่ยวชาญ","id":"<span class=\"clause-num\">18.2 Merokok dan kebersihan.</span> Merokok, hewan peliharaan, pasir berlebihan, noda, bau atau kotoran yang tidak wajar dapat dikenakan biaya kebersihan hingga {{currency_symbol}}{{smoking_fee_maximum}} atau lebih jika diperlukan pembersihan profesional.","vi":"<span class=\"clause-num\">18.2 Hút thuốc và vệ sinh.</span> Hút thuốc, vật nuôi, nhiều cát, vết bẩn, mùi hôi hoặc bụi bẩn quá mức có thể bị tính phí vệ sinh đến {{currency_symbol}}{{smoking_fee_maximum}} hoặc cao hơn nếu cần vệ sinh chuyên nghiệp.","ms":"<span class=\"clause-num\">18.2 Merokok dan pembersihan.</span> Merokok, haiwan peliharaan, pasir berlebihan, kesan kotoran, bau atau kekotoran yang tidak munasabah boleh dikenakan caj pembersihan sehingga {{currency_symbol}}{{smoking_fee_maximum}} atau lebih jika pembersihan profesional diperlukan.","fil":"<span class=\"clause-num\">18.2 Paninigarilyo at paglilinis.</span> Ang paninigarilyo, alagang hayop, labis na buhangin, mantsa, amoy o labis na dumi ay maaaring singilin ng bayad sa paglilinis hanggang {{currency_symbol}}{{smoking_fee_maximum}} o higit pa kung kailangan ng propesyonal na paglilinis.","lo":"<span class=\"clause-num\">18.2 ການສູບຢາ ແລະ ການທຳຄວາມສະອາດ.</span> ການສູບຢາ, ສັດລ້ຽງ, ດິນຊາຍຫຼາຍເກີນໄປ, ຮອຍເປື້ອນ, ກິ່ນ ຫຼື ຄວາມເປື້ອນເປິເກີນສົມຄວນ ອາດມີຄ່າທຳຄວາມສະອາດສູງສຸດ {{currency_symbol}}{{smoking_fee_maximum}} ຫຼື ຫຼາຍກວ່ານັ້ນຖ້າຕ້ອງທຳຄວາມສະອາດໂດຍຜູ້ຊ່ຽວຊານ.","km":"<span class=\"clause-num\">18.2 ការជក់បារី និងការសម្អាត។</span> ការជក់បារី សត្វចិញ្ចឹម ខ្សាច់ច្រើនពេក ស្នាមប្រឡាក់ ក្លិន ឬភាពកខ្វក់ហួសហេតុ អាចត្រូវគិតថ្លៃសម្អាតរហូតដល់ {{currency_symbol}}{{smoking_fee_maximum}} ឬច្រើនជាងនេះ ប្រសិនបើត្រូវការការសម្អាតដោយអ្នកជំនាញ។","el":"<span class=\"clause-num\">18.2 Κάπνισμα και καθαρισμός.</span> Το κάπνισμα, τα ζώα, η υπερβολική άμμος, οι λεκέδες, οι οσμές ή η υπερβολική βρωμιά μπορεί να επιφέρουν χρέωση καθαρισμού έως {{currency_symbol}}{{smoking_fee_maximum}}, ή περισσότερο αν απαιτείται επαγγελματικός καθαρισμός.","es":"<span class=\"clause-num\">18.2 Tabaco y limpieza.</span> Fumar, llevar animales, el exceso de arena, las manchas, los olores o la suciedad excesiva pueden dar lugar a gastos de limpieza de hasta {{currency_symbol}}{{smoking_fee_maximum}}, o más si es necesaria una limpieza profesional.","pt":"<span class=\"clause-num\">18.2 Tabaco e limpeza.</span> Fumar, transportar animais, areia em excesso, nódoas, odores ou sujidade excessiva podem dar origem a custos de limpeza até {{currency_symbol}}{{smoking_fee_maximum}}, ou mais se for necessária limpeza profissional.","it":"<span class=\"clause-num\">18.2 Fumo e pulizia.</span> Fumo, animali, sabbia eccessiva, macchie, odori o sporco eccessivo possono comportare spese di pulizia fino a {{currency_symbol}}{{smoking_fee_maximum}}, o superiori se è necessaria una pulizia professionale.","hr":"<span class=\"clause-num\">18.2 Pušenje i čišćenje.</span> Pušenje, životinje, previše pijeska, mrlje, neugodni mirisi ili pretjerana prljavština mogu se naplatiti troškom čišćenja do {{currency_symbol}}{{smoking_fee_maximum}}, ili više ako je potrebno profesionalno čišćenje.","fr":"<span class=\"clause-num\">18.2 Tabac et nettoyage.</span> Le tabac, les animaux, l'excès de sable, les taches, les odeurs ou une saleté excessive peuvent entraîner des frais de nettoyage jusqu'à {{currency_symbol}}{{smoking_fee_maximum}}, ou davantage si un nettoyage professionnel est nécessaire.","de":"<span class=\"clause-num\">18.2 Rauchen und Reinigung.</span> Rauchen, Tiere, übermäßiger Sand, Flecken, Gerüche oder starke Verschmutzung können Reinigungskosten bis {{currency_symbol}}{{smoking_fee_maximum}} verursachen, bei erforderlicher professioneller Reinigung auch mehr.","tr":"<span class=\"clause-num\">18.2 Sigara ve temizlik.</span> Sigara içilmesi, hayvan taşınması, aşırı kum, leke, koku veya aşırı kirlilik, {{currency_symbol}}{{smoking_fee_maximum}} tutarına kadar veya profesyonel temizlik gerekiyorsa daha fazla temizlik ücretine yol açabilir."},
  {"th":"<span class=\"clause-num\">18.2 การสูบบุหรี่และทำความสะอาด.</span> การสูบบุหรี่ สัตว์เลี้ยง ทรายมากเกินไป คราบ กลิ่น หรือความสกปรกเกินสมควร อาจมีค่าทำความสะอาดหากต้องทำความสะอาดโดยผู้เชี่ยวชาญ","id":"<span class=\"clause-num\">18.2 Merokok dan kebersihan.</span> Merokok, hewan peliharaan, pasir berlebihan, noda, bau atau kotoran yang tidak wajar dapat dikenakan biaya kebersihan jika diperlukan pembersihan profesional.","vi":"<span class=\"clause-num\">18.2 Hút thuốc và vệ sinh.</span> Hút thuốc, vật nuôi, nhiều cát, vết bẩn, mùi hôi hoặc bụi bẩn quá mức có thể bị tính phí vệ sinh nếu cần vệ sinh chuyên nghiệp.","ms":"<span class=\"clause-num\">18.2 Merokok dan pembersihan.</span> Merokok, haiwan peliharaan, pasir berlebihan, kesan kotoran, bau atau kekotoran yang tidak munasabah boleh dikenakan caj pembersihan jika pembersihan profesional diperlukan.","fil":"<span class=\"clause-num\">18.2 Paninigarilyo at paglilinis.</span> Ang paninigarilyo, alagang hayop, labis na buhangin, mantsa, amoy o labis na dumi ay maaaring singilin ng bayad sa paglilinis kung kailangan ng propesyonal na paglilinis.","lo":"<span class=\"clause-num\">18.2 ການສູບຢາ ແລະ ການທຳຄວາມສະອາດ.</span> ການສູບຢາ, ສັດລ້ຽງ, ດິນຊາຍຫຼາຍເກີນໄປ, ຮອຍເປື້ອນ, ກິ່ນ ຫຼື ຄວາມເປື້ອນເປິເກີນສົມຄວນ ອາດມີຄ່າທຳຄວາມສະອາດຖ້າຕ້ອງທຳຄວາມສະອາດໂດຍຜູ້ຊ່ຽວຊານ.","km":"<span class=\"clause-num\">18.2 ការជក់បារី និងការសម្អាត។</span> ការជក់បារី សត្វចិញ្ចឹម ខ្សាច់ច្រើនពេក ស្នាមប្រឡាក់ ក្លិន ឬភាពកខ្វក់ហួសហេតុ អាចត្រូវគិតថ្លៃសម្អាត ប្រសិនបើត្រូវការការសម្អាតដោយអ្នកជំនាញ។","el":"<span class=\"clause-num\">18.2 Κάπνισμα και καθαρισμός.</span> Το κάπνισμα, τα ζώα, η υπερβολική άμμος, οι λεκέδες, οι οσμές ή η υπερβολική βρωμιά μπορεί να επιφέρουν χρέωση καθαρισμού όταν απαιτείται επαγγελματικός καθαρισμός.","es":"<span class=\"clause-num\">18.2 Tabaco y limpieza.</span> Fumar, llevar animales, el exceso de arena, las manchas, los olores o la suciedad excesiva pueden dar lugar a gastos de limpieza cuando sea necesaria una limpieza profesional.","pt":"<span class=\"clause-num\">18.2 Tabaco e limpeza.</span> Fumar, transportar animais, areia em excesso, nódoas, odores ou sujidade excessiva podem dar origem a custos de limpeza quando for necessária limpeza profissional.","it":"<span class=\"clause-num\">18.2 Fumo e pulizia.</span> Fumo, animali, sabbia eccessiva, macchie, odori o sporco eccessivo possono comportare spese di pulizia quando è necessaria una pulizia professionale.","hr":"<span class=\"clause-num\">18.2 Pušenje i čišćenje.</span> Pušenje, životinje, previše pijeska, mrlje, neugodni mirisi ili pretjerana prljavština mogu se naplatiti troškom čišćenja kada je potrebno profesionalno čišćenje.","fr":"<span class=\"clause-num\">18.2 Tabac et nettoyage.</span> Le tabac, les animaux, l'excès de sable, les taches, les odeurs ou une saleté excessive peuvent entraîner des frais de nettoyage lorsqu'un nettoyage professionnel est nécessaire.","de":"<span class=\"clause-num\">18.2 Rauchen und Reinigung.</span> Rauchen, Tiere, übermäßiger Sand, Flecken, Gerüche oder starke Verschmutzung können Reinigungskosten verursachen, wenn eine professionelle Reinigung erforderlich ist.","tr":"<span class=\"clause-num\">18.2 Sigara ve temizlik.</span> Sigara içilmesi, hayvan taşınması, aşırı kum, leke, koku veya aşırı kirlilik, profesyonel temizlik gerektiğinde temizlik ücretine yol açabilir."},
  {"th":"<span class=\"clause-num\">18.3 การซ่อมฉุกเฉิน.</span> การซ่อมฉุกเฉินควรได้รับอนุมัติก่อนเท่าที่ทำได้และต้องมีใบเสร็จ การซ่อมที่ไม่ได้รับอนุมัติอาจไม่ได้รับการชดใช้","id":"<span class=\"clause-num\">18.3 Perbaikan darurat.</span> Perbaikan darurat memerlukan persetujuan terlebih dahulu bila memungkinkan dan kuitansi wajib diberikan. Perbaikan tanpa persetujuan mungkin tidak diganti.","vi":"<span class=\"clause-num\">18.3 Sửa chữa khẩn cấp.</span> Sửa chữa khẩn cấp cần được chấp thuận trước khi có thể và phải cung cấp hóa đơn. Các sửa chữa không được chấp thuận có thể không được hoàn tiền.","ms":"<span class=\"clause-num\">18.3 Pembaikan kecemasan.</span> Pembaikan kecemasan memerlukan kelulusan terlebih dahulu jika boleh dan resit mesti diberikan. Pembaikan tanpa kelulusan mungkin tidak dibayar balik.","fil":"<span class=\"clause-num\">18.3 Emergency na pagpapaayos.</span> Ang emergency na pagpapaayos ay nangangailangan ng paunang pahintulot kung maaari at dapat magbigay ng resibo. Ang hindi awtorisadong pagpapaayos ay maaaring hindi bayaran.","lo":"<span class=\"clause-num\">18.3 ການສ້ອມແປງສຸກເສີນ.</span> ການສ້ອມແປງສຸກເສີນຄວນໄດ້ຮັບອະນຸມັດກ່ອນເທົ່າທີ່ເຮັດໄດ້ ແລະ ຕ້ອງມີໃບບິນ. ການສ້ອມແປງທີ່ບໍ່ໄດ້ຮັບອະນຸມັດອາດບໍ່ໄດ້ຮັບການຊົດເຊີຍ.","km":"<span class=\"clause-num\">18.3 ការជួសជុលបន្ទាន់។</span> ការជួសជុលបន្ទាន់ត្រូវមានការយល់ព្រមជាមុនតាមដែលអាចធ្វើបាន ហើយត្រូវផ្តល់បង្កាន់ដៃ។ ការជួសជុលដែលគ្មានការយល់ព្រមអាចមិនត្រូវបានសងវិញ។","el":"<span class=\"clause-num\">18.3 Επείγουσες επισκευές.</span> Οι επείγουσες επισκευές απαιτούν προηγούμενη έγκριση όπου είναι δυνατόν και πρέπει να τεκμηριώνονται με αποδείξεις. Οι μη εγκεκριμένες επισκευές ενδέχεται να μην αποζημιωθούν.","es":"<span class=\"clause-num\">18.3 Reparaciones urgentes.</span> Las reparaciones urgentes requieren autorización previa siempre que sea posible y deben justificarse con factura. Las reparaciones no autorizadas pueden no reembolsarse.","pt":"<span class=\"clause-num\">18.3 Reparações urgentes.</span> As reparações urgentes exigem autorização prévia sempre que possível e devem ser comprovadas por fatura. As reparações não autorizadas podem não ser reembolsadas.","it":"<span class=\"clause-num\">18.3 Riparazioni urgenti.</span> Le riparazioni urgenti richiedono, ove possibile, l'autorizzazione preventiva e devono essere documentate con fattura. Le riparazioni non autorizzate possono non essere rimborsate.","hr":"<span class=\"clause-num\">18.3 Hitni popravci.</span> Za hitne popravke potrebno je, kad god je moguće, prethodno odobrenje, a moraju se dostaviti računi. Neodobreni popravci možda se neće nadoknaditi.","fr":"<span class=\"clause-num\">18.3 Réparations urgentes.</span> Les réparations urgentes nécessitent un accord préalable dans la mesure du possible et doivent être justifiées par une facture. Les réparations non autorisées peuvent ne pas être remboursées.","de":"<span class=\"clause-num\">18.3 Notreparaturen.</span> Notreparaturen bedürfen nach Möglichkeit der vorherigen Zustimmung und sind durch Belege nachzuweisen. Nicht genehmigte Reparaturen werden möglicherweise nicht erstattet.","tr":"<span class=\"clause-num\">18.3 Acil onarımlar.</span> Acil onarımlar için mümkün olduğunca önceden onay alınmalı ve fatura ile belgelendirilmelidir. Onaylanmamış onarımların bedeli iade edilmeyebilir."},
  {"th":"<span class=\"clause-num\">18.4 กุญแจและเอกสาร.</span> กุญแจ รีโมต เอกสารทะเบียน เอกสารประกัน หรืออุปกรณ์ที่สูญหาย จะคิดตามค่าทดแทนจริงรวมถึงค่าดำเนินการที่สมเหตุสมผล","id":"<span class=\"clause-num\">18.4 Kunci dan dokumen.</span> Kunci, remote, dokumen registrasi (STNK), dokumen asuransi atau perlengkapan yang hilang dikenakan biaya penggantian ditambah biaya administrasi yang wajar.","vi":"<span class=\"clause-num\">18.4 Chìa khóa và giấy tờ.</span> Chìa khóa, điều khiển, giấy đăng ký xe, giấy bảo hiểm hoặc phụ kiện bị mất sẽ được tính theo chi phí thay thế cộng với phí xử lý hợp lý.","ms":"<span class=\"clause-num\">18.4 Kunci dan dokumen.</span> Kunci, alat kawalan jauh, dokumen pendaftaran, dokumen insurans atau aksesori yang hilang dikenakan caj mengikut kos penggantian berserta kos pentadbiran yang munasabah.","fil":"<span class=\"clause-num\">18.4 Mga susi at dokumento.</span> Ang nawalang susi, remote, dokumento ng rehistro, dokumento ng seguro o aksesorya ay sisingilin sa halaga ng pagpapalit kasama ang makatwirang bayad sa pangangasiwa.","lo":"<span class=\"clause-num\">18.4 ກະແຈ ແລະ ເອກະສານ.</span> ກະແຈ, ຣີໂໝດ, ເອກະສານທະບຽນ, ເອກະສານປະກັນໄພ ຫຼື ອຸປະກອນທີ່ເສຍ ຈະຄິດຕາມຄ່າທົດແທນຕົວຈິງ ລວມທັງຄ່າດຳເນີນການທີ່ສົມເຫດສົມຜົນ.","km":"<span class=\"clause-num\">18.4 សោ និងឯកសារ។</span> សោ តេឡេបញ្ជា ឯកសារចុះបញ្ជី ឯកសារធានារ៉ាប់រង ឬគ្រឿងបន្លាស់ដែលបាត់ ត្រូវគិតថ្លៃតាមតម្លៃជំនួស បូកនឹងថ្លៃរដ្ឋបាលសមរម្យ។","el":"<span class=\"clause-num\">18.4 Κλειδιά και έγγραφα.</span> Τα κλειδιά, τα τηλεχειριστήρια, η άδεια κυκλοφορίας, τα ασφαλιστικά έγγραφα ή τα εξαρτήματα που χάνονται χρεώνονται στο κόστος αντικατάστασης, πλέον εύλογων διοικητικών εξόδων.","es":"<span class=\"clause-num\">18.4 Llaves y documentos.</span> La pérdida de llaves, mandos, documentación del vehículo, documentos del seguro o accesorios se cobra por su coste de reposición más un gasto de gestión razonable.","pt":"<span class=\"clause-num\">18.4 Chaves e documentos.</span> A perda de chaves, comandos, documento único automóvel, documentos do seguro ou acessórios é cobrada pelo custo de substituição, acrescido de um encargo administrativo razoável.","it":"<span class=\"clause-num\">18.4 Chiavi e documenti.</span> Lo smarrimento di chiavi, telecomandi, carta di circolazione, documenti assicurativi o accessori è addebitato al costo di sostituzione più un ragionevole costo amministrativo.","hr":"<span class=\"clause-num\">18.4 Ključevi i dokumenti.</span> Izgubljeni ključevi, daljinski upravljači, prometna dozvola, dokumenti osiguranja ili oprema naplaćuju se po trošku zamjene uz razumnu administrativnu naknadu.","fr":"<span class=\"clause-num\">18.4 Clés et documents.</span> La perte de clés, télécommandes, certificat d'immatriculation, documents d'assurance ou accessoires est facturée au coût de remplacement majoré de frais administratifs raisonnables.","de":"<span class=\"clause-num\">18.4 Schlüssel und Papiere.</span> Verlorene Schlüssel, Fernbedienungen, Fahrzeugpapiere, Versicherungsunterlagen oder Zubehörteile werden zum Wiederbeschaffungswert zuzüglich angemessener Verwaltungskosten berechnet.","tr":"<span class=\"clause-num\">18.4 Anahtarlar ve belgeler.</span> Kaybolan anahtar, kumanda, ruhsat, sigorta belgesi veya donanımlar, yenileme bedeli ile makul bir işlem ücreti üzerinden ücretlendirilir."},
  {"th":"<span class=\"clause-num\">18.5 การติดต่อสื่อสาร.</span> การแจ้งเตือนอาจส่งทางโทรศัพท์ WhatsApp LINE SMS อีเมล หรือพอร์ทัลลูกค้า โดยใช้ข้อมูลติดต่อที่ผู้เช่าให้ไว้","id":"<span class=\"clause-num\">18.5 Komunikasi.</span> Pemberitahuan dapat dikirim melalui telepon, WhatsApp, LINE, SMS, email atau portal pemesanan pelanggan menggunakan kontak yang diberikan Penyewa.","vi":"<span class=\"clause-num\">18.5 Liên lạc.</span> Thông báo có thể được gửi qua điện thoại, WhatsApp, LINE, SMS, email hoặc cổng đặt xe của khách hàng theo thông tin liên lạc mà Bên thuê cung cấp.","ms":"<span class=\"clause-num\">18.5 Komunikasi.</span> Notis boleh dihantar melalui telefon, WhatsApp, LINE, SMS, e-mel atau portal tempahan pelanggan menggunakan butiran hubungan yang diberikan oleh Penyewa.","fil":"<span class=\"clause-num\">18.5 Komunikasyon.</span> Maaaring ipadala ang mga abiso sa telepono, WhatsApp, LINE, SMS, email o sa customer booking portal gamit ang mga contact detail na ibinigay ng Umuupa.","lo":"<span class=\"clause-num\">18.5 ການຕິດຕໍ່ສື່ສານ.</span> ການແຈ້ງເຕືອນອາດສົ່ງທາງໂທລະສັບ, WhatsApp, LINE, SMS, ອີເມວ ຫຼື ພອດທັນລູກຄ້າ ໂດຍໃຊ້ຂໍ້ມູນຕິດຕໍ່ທີ່ຜູ້ເຊົ່າໃຫ້ໄວ້.","km":"<span class=\"clause-num\">18.5 ការទំនាក់ទំនង។</span> ការជូនដំណឹងអាចផ្ញើតាមទូរស័ព្ទ WhatsApp LINE SMS អ៊ីមែល ឬវិបផតថលកក់របស់អតិថិជន ដោយប្រើព័ត៌មានទំនាក់ទំនងដែលអ្នកជួលបានផ្តល់។","el":"<span class=\"clause-num\">18.5 Επικοινωνία.</span> Οι ειδοποιήσεις μπορούν να αποστέλλονται τηλεφωνικά, μέσω WhatsApp, LINE, SMS, email ή της πύλης κρατήσεων πελατών, στα στοιχεία επικοινωνίας που έδωσε ο Μισθωτής.","es":"<span class=\"clause-num\">18.5 Comunicaciones.</span> Las notificaciones pueden enviarse por teléfono, WhatsApp, LINE, SMS, correo electrónico o el portal de reservas del cliente, a los datos de contacto facilitados por el Arrendatario.","pt":"<span class=\"clause-num\">18.5 Comunicações.</span> As comunicações podem ser enviadas por telefone, WhatsApp, LINE, SMS, correio eletrónico ou portal de reservas do cliente, para os contactos indicados pelo Locatário.","it":"<span class=\"clause-num\">18.5 Comunicazioni.</span> Le comunicazioni possono essere inviate per telefono, WhatsApp, LINE, SMS, e-mail o tramite il portale prenotazioni del cliente, ai recapiti forniti dal Conduttore.","hr":"<span class=\"clause-num\">18.5 Obavijesti.</span> Obavijesti se mogu slati telefonom, putem WhatsAppa, LINE-a, SMS-a, e-pošte ili korisničkog portala za rezervacije, na kontakt podatke koje je dao Najmoprimac.","fr":"<span class=\"clause-num\">18.5 Communications.</span> Les notifications peuvent être envoyées par téléphone, WhatsApp, LINE, SMS, e-mail ou via l'espace de réservation client, aux coordonnées fournies par le Locataire.","de":"<span class=\"clause-num\">18.5 Mitteilungen.</span> Mitteilungen können per Telefon, WhatsApp, LINE, SMS, E-Mail oder über das Kundenbuchungsportal an die vom Mieter angegebenen Kontaktdaten gesendet werden.","tr":"<span class=\"clause-num\">18.5 Bildirimler.</span> Bildirimler, Kiracının verdiği iletişim bilgilerine telefon, WhatsApp, LINE, SMS, e-posta veya müşteri rezervasyon portalı aracılığıyla gönderilebilir."},
  {"th":"<span class=\"clause-num\">18.6 รูปภาพและวิดีโอ.</span> รูปภาพและวิดีโอการตรวจสภาพเป็นส่วนหนึ่งของสัญญานี้ และอาจใช้เป็นหลักฐานสภาพยานพาหนะก่อน ระหว่าง และหลังการเช่า","id":"<span class=\"clause-num\">18.6 Foto dan video.</span> Foto dan video pemeriksaan merupakan bagian dari perjanjian ini dan dapat digunakan untuk membuktikan kondisi kendaraan sebelum, selama dan setelah masa sewa.","vi":"<span class=\"clause-num\">18.6 Hình ảnh và video.</span> Hình ảnh và video kiểm tra là một phần của hợp đồng này và có thể được dùng để chứng minh tình trạng xe trước, trong và sau thời gian thuê.","ms":"<span class=\"clause-num\">18.6 Gambar dan video.</span> Gambar dan video pemeriksaan adalah sebahagian daripada perjanjian ini dan boleh digunakan untuk membuktikan keadaan kenderaan sebelum, semasa dan selepas sewaan.","fil":"<span class=\"clause-num\">18.6 Mga larawan at video.</span> Ang mga larawan at video ng inspeksyon ay bahagi ng kasunduang ito at maaaring gamitin upang patunayan ang kondisyon ng sasakyan bago, habang at pagkatapos ng upa.","lo":"<span class=\"clause-num\">18.6 ຮູບພາບ ແລະ ວິດີໂອ.</span> ຮູບພາບ ແລະ ວິດີໂອການກວດສະພາບເປັນສ່ວນໜຶ່ງຂອງສັນຍານີ້ ແລະ ອາດໃຊ້ເປັນຫຼັກຖານສະພາບຍານພາຫະນະກ່ອນ, ລະຫວ່າງ ແລະ ຫຼັງການເຊົ່າ.","km":"<span class=\"clause-num\">18.6 រូបថត និងវីដេអូ។</span> រូបថត និងវីដេអូនៃការត្រួតពិនិត្យជាផ្នែកមួយនៃកិច្ចសន្យានេះ ហើយអាចប្រើជាភស្តុតាងនៃស្ថានភាពយានយន្តមុន អំឡុងពេល និងក្រោយការជួល។","el":"<span class=\"clause-num\">18.6 Φωτογραφίες και βίντεο.</span> Οι φωτογραφίες και τα βίντεο ελέγχου αποτελούν μέρος της παρούσας σύμβασης και μπορούν να χρησιμοποιηθούν ως απόδειξη της κατάστασης του οχήματος πριν, κατά τη διάρκεια και μετά τη μίσθωση.","es":"<span class=\"clause-num\">18.6 Fotos y vídeos.</span> Las fotos y vídeos de inspección forman parte de este contrato y pueden utilizarse para acreditar el estado del vehículo antes, durante y después del alquiler.","pt":"<span class=\"clause-num\">18.6 Fotografias e vídeos.</span> As fotografias e vídeos de inspeção fazem parte deste contrato e podem ser usados para provar o estado do veículo antes, durante e depois do aluguer.","it":"<span class=\"clause-num\">18.6 Foto e video.</span> Le foto e i video di ispezione fanno parte del presente contratto e possono essere usati per provare lo stato del veicolo prima, durante e dopo il noleggio.","hr":"<span class=\"clause-num\">18.6 Fotografije i videozapisi.</span> Fotografije i videozapisi pregleda sastavni su dio ovog ugovora i mogu se koristiti kao dokaz stanja vozila prije, tijekom i nakon najma.","fr":"<span class=\"clause-num\">18.6 Photos et vidéos.</span> Les photos et vidéos d'état des lieux font partie du présent contrat et peuvent servir à prouver l'état du véhicule avant, pendant et après la location.","de":"<span class=\"clause-num\">18.6 Fotos und Videos.</span> Fotos und Videos der Fahrzeugprüfung sind Bestandteil dieses Vertrags und können zum Nachweis des Fahrzeugzustands vor, während und nach der Miete verwendet werden.","tr":"<span class=\"clause-num\">18.6 Fotoğraf ve videolar.</span> Kontrol fotoğrafları ve videoları işbu sözleşmenin bir parçasıdır ve aracın kiralama öncesindeki, süresindeki ve sonrasındaki durumunu ispat için kullanılabilir."},
  {"th":"<span class=\"clause-num\">18.7 ห้ามให้เช่าช่วง ให้ยืม หรือให้ผู้อื่นขับขี่.</span> ผู้เช่าห้ามให้เช่าช่วง ให้เช่าต่อ ให้ยืม หรือส่งมอบยานพาหนะให้แก่บุคคลใด โอนสิทธิใด ๆ ตามสัญญานี้ หรือยินยอมให้บุคคลที่ไม่ได้ระบุชื่อในสัญญานี้ขับขี่ยานพาหนะ ห้ามใช้ยานพาหนะรับส่งผู้โดยสารหรือส่งสินค้าเพื่อรับค่าตอบแทน รวมถึงผ่านแอปพลิเคชันเรียกรถหรือส่งสินค้า การฝ่าฝืนข้อนี้ถือเป็นการผิดสัญญาอย่างมีนัยสำคัญ และให้สิทธิผู้ให้เช่าเลิกการเช่าและนำยานพาหนะคืนได้ทันที และเรียกค่าเสียหายและค่าใช้จ่ายที่เกิดจากการฝ่าฝืนนั้น รวมถึงหักจากเงินประกัน","id":"<span class=\"clause-num\">18.7 Larangan menyewakan kembali, meminjamkan, atau pengemudi lain.</span> Penyewa tidak boleh menyewakan kembali, menyewakan, meminjamkan atau menyerahkan kendaraan kepada siapa pun, mengalihkan hak apa pun berdasarkan perjanjian ini, atau membiarkan orang yang tidak disebut dalam perjanjian ini mengemudikan kendaraan. Kendaraan tidak boleh digunakan untuk mengangkut penumpang atau mengantar barang dengan bayaran, termasuk melalui aplikasi transportasi daring atau pengiriman. Pelanggaran ketentuan ini merupakan pelanggaran berat terhadap perjanjian ini dan memberi hak kepada Pemilik untuk mengakhiri sewa dan segera menarik kembali kendaraan, serta menuntut kerugian dan biaya yang ditimbulkannya, termasuk dari uang jaminan.","vi":"<span class=\"clause-num\">18.7 Không cho thuê lại, cho mượn hoặc để người khác lái.</span> Bên thuê không được cho thuê lại, cho thuê, cho mượn hoặc giao xe cho bất kỳ ai, chuyển giao bất kỳ quyền nào theo hợp đồng này, hoặc để người không có tên trong hợp đồng này lái xe. Không được dùng xe để chở khách hoặc giao hàng có thu tiền, kể cả qua ứng dụng gọi xe hoặc giao hàng. Vi phạm điều khoản này là vi phạm nghiêm trọng hợp đồng này và cho phép Bên cho thuê chấm dứt việc thuê, thu hồi xe ngay lập tức và đòi bồi thường các thiệt hại và chi phí phát sinh, kể cả trừ vào tiền đặt cọc.","ms":"<span class=\"clause-num\">18.7 Larangan menyewakan semula, meminjamkan atau pemandu lain.</span> Penyewa tidak boleh menyewakan semula, menyewakan, meminjamkan atau menyerahkan kenderaan kepada sesiapa, memindahkan apa-apa hak di bawah perjanjian ini, atau membenarkan sesiapa yang tidak dinamakan dalam perjanjian ini memandu atau menunggangnya. Kenderaan tidak boleh digunakan untuk membawa penumpang atau membuat penghantaran untuk bayaran, termasuk melalui aplikasi e-hailing atau penghantaran. Pelanggaran fasal ini merupakan pelanggaran material perjanjian ini dan memberi hak kepada Pemilik untuk menamatkan sewaan dan mengambil semula kenderaan serta-merta, serta menuntut kerugian dan kos yang disebabkannya, termasuk daripada wang cagaran.","fil":"<span class=\"clause-num\">18.7 Bawal ang sub-lease, pagpapahiram o ibang drayber.</span> Hindi maaaring i-sub-lease, ipaupa, ipahiram o ibigay ng Umuupa ang sasakyan sa sinuman, ilipat ang anumang karapatan sa ilalim ng kasunduang ito, o payagang magmaneho ang sinumang hindi nakapangalan sa kasunduang ito. Hindi maaaring gamitin ang sasakyan sa pagsasakay ng pasahero o paghahatid nang may bayad, kasama ang sa pamamagitan ng ride-hailing o delivery app. Ang paglabag sa probisyong ito ay isang mabigat na paglabag sa kasunduang ito at nagbibigay ng karapatan sa May-ari na tapusin ang pag-upa at agad bawiin ang sasakyan, at singilin ang mga pinsala at gastos na idinulot nito, kasama ang pagbawas sa deposito.","lo":"<span class=\"clause-num\">18.7 ຫ້າມໃຫ້ເຊົ່າຊ່ວງ, ໃຫ້ຢືມ ຫຼື ໃຫ້ຜູ້ອື່ນຂັບ.</span> ຜູ້ເຊົ່າຫ້າມໃຫ້ເຊົ່າຊ່ວງ, ໃຫ້ເຊົ່າຕໍ່, ໃຫ້ຢືມ ຫຼື ມອບຍານພາຫະນະໃຫ້ແກ່ຜູ້ໃດ, ໂອນສິດໃດໆ ພາຍໃຕ້ສັນຍານີ້ ຫຼື ໃຫ້ຜູ້ທີ່ບໍ່ມີຊື່ໃນສັນຍານີ້ຂັບຂີ່ຍານພາຫະນະ. ຫ້າມໃຊ້ຍານພາຫະນະຮັບສົ່ງຜູ້ໂດຍສານ ຫຼື ສົ່ງສິນຄ້າເພື່ອຮັບຄ່າຈ້າງ ລວມທັງຜ່ານແອັບຮັບສົ່ງ ຫຼື ສົ່ງເຄື່ອງ. ການລະເມີດຂໍ້ນີ້ຖືເປັນການລະເມີດສັນຍາຢ່າງຮ້າຍແຮງ ແລະ ໃຫ້ສິດຜູ້ໃຫ້ເຊົ່າຢຸດການເຊົ່າ ແລະ ຍຶດຍານພາຫະນະຄືນໄດ້ທັນທີ ແລະ ຮຽກຮ້ອງຄ່າເສຍຫາຍ ແລະ ຄ່າໃຊ້ຈ່າຍທີ່ເກີດຈາກການລະເມີດນັ້ນ ລວມທັງຫັກຈາກເງິນມັດຈຳ.","km":"<span class=\"clause-num\">18.7 ហាមជួលបន្ត ឲ្យខ្ចី ឬឲ្យអ្នកផ្សេងបើកបរ។</span> អ្នកជួលមិនអាចជួលបន្ត ឲ្យជួល ឲ្យខ្ចី ឬប្រគល់យានយន្តឲ្យនរណាម្នាក់ ផ្ទេរសិទ្ធិណាមួយក្រោមកិច្ចសន្យានេះ ឬអនុញ្ញាតឲ្យអ្នកដែលគ្មានឈ្មោះក្នុងកិច្ចសន្យានេះបើកបរយានយន្តបានឡើយ។ ហាមប្រើយានយន្តសម្រាប់ដឹកអ្នកដំណើរ ឬដឹកជញ្ជូនទំនិញដើម្បីយកថ្លៃ រួមទាំងតាមរយៈកម្មវិធីដឹកអ្នកដំណើរ ឬដឹកជញ្ជូន។ ការបំពានប្រការនេះ គឺជាការបំពានធ្ងន់ធ្ងរលើកិច្ចសន្យានេះ ហើយផ្តល់សិទ្ធិឲ្យអ្នកឲ្យជួលបញ្ចប់ការជួល និងដកយានយន្តវិញភ្លាមៗ ព្រមទាំងទាមទារការខូចខាត និងថ្លៃចំណាយដែលបណ្តាលមកពីការនោះ រួមទាំងកាត់ពីប្រាក់កក់។","el":"<span class=\"clause-num\">18.7 Απαγόρευση υπεκμίσθωσης, δανεισμού και άλλων οδηγών.</span> Ο Μισθωτής δεν μπορεί να υπεκμισθώσει, να εκμισθώσει, να δανείσει ή να παραδώσει το όχημα σε οποιονδήποτε, να μεταβιβάσει δικαιώματα από την παρούσα σύμβαση ή να επιτρέψει την οδήγησή του από πρόσωπο που δεν αναφέρεται στη σύμβαση. Το όχημα δεν μπορεί να χρησιμοποιηθεί για μεταφορά επιβατών ή διανομές έναντι αμοιβής, ούτε μέσω εφαρμογών μεταφοράς ή διανομής. Η παράβαση του όρου αυτού αποτελεί ουσιώδη παράβαση της σύμβασης και δίνει στον Εκμισθωτή το δικαίωμα να λύσει τη μίσθωση και να πάρει πίσω το όχημα αμέσως, καθώς και να αξιώσει τη ζημία και τα έξοδα που προκύπτουν, μεταξύ άλλων από την εγγύηση.","es":"<span class=\"clause-num\">18.7 Prohibición de subarriendo, préstamo y otros conductores.</span> El Arrendatario no puede subarrendar, alquilar, prestar ni entregar el vehículo a nadie, ceder los derechos derivados de este contrato ni dejar conducir el vehículo a una persona no indicada en este contrato. El vehículo no puede usarse para transportar pasajeros ni hacer repartos a cambio de pago, tampoco mediante aplicaciones de VTC o de reparto. Incumplir esta cláusula es un incumplimiento grave del contrato y faculta al Propietario para poner fin al alquiler y recuperar el vehículo de inmediato, así como para reclamar los perjuicios y gastos que cause, también con cargo a la fianza.","pt":"<span class=\"clause-num\">18.7 Proibição de subaluguer, empréstimo e outros condutores.</span> O Locatário não pode subalugar, alugar, emprestar ou entregar o veículo a ninguém, ceder os direitos deste contrato nem deixar conduzir o veículo alguém não identificado neste contrato. O veículo não pode ser usado para transporte de passageiros ou entregas mediante pagamento, incluindo através de plataformas TVDE ou de entregas. A violação desta cláusula constitui incumprimento grave do contrato e permite ao Locador pôr fim ao aluguer e recuperar o veículo de imediato, bem como exigir os prejuízos e custos daí resultantes, incluindo por dedução na caução.","it":"<span class=\"clause-num\">18.7 Divieto di sublocazione, prestito e altri conducenti.</span> Il Conduttore non può sublocare, noleggiare, prestare o consegnare il veicolo a nessuno, cedere i diritti derivanti dal presente contratto né far guidare il veicolo a persone non indicate nel contratto. Il veicolo non può essere usato per trasporto di persone o consegne a pagamento, nemmeno tramite app di trasporto o di consegna. La violazione di questa clausola costituisce grave inadempimento e consente al Locatore di porre fine al noleggio e riprendere immediatamente il veicolo, nonché di chiedere i danni e i costi che ne derivano, anche trattenendoli dal deposito cauzionale.","hr":"<span class=\"clause-num\">18.7 Zabrana podnajma, posudbe i drugih vozača.</span> Najmoprimac ne smije dati vozilo u podnajam, iznajmiti ga, posuditi ili predati bilo kome, ustupiti prava iz ovog ugovora niti dopustiti da vozilom upravlja osoba koja nije navedena u ovom ugovoru. Vozilo se ne smije koristiti za plaćeni prijevoz putnika ili dostavu, uključujući putem aplikacija za prijevoz ili dostavu. Kršenje ove odredbe bitna je povreda ugovora i ovlašćuje Najmodavca da prekine najam i odmah preuzme vozilo te da zahtijeva nastalu štetu i troškove, uključujući iz jamčevine.","fr":"<span class=\"clause-num\">18.7 Interdiction de sous-location, de prêt et d'autres conducteurs.</span> Le Locataire ne peut ni sous-louer, ni louer, ni prêter, ni remettre le véhicule à quiconque, ni céder les droits du présent contrat, ni laisser conduire le véhicule par une personne non désignée dans le contrat. Le véhicule ne peut pas servir au transport de personnes ou à des livraisons contre rémunération, y compris via des applications de VTC ou de livraison. Tout manquement à cette clause constitue un manquement grave au contrat et permet au Loueur de mettre fin à la location et de reprendre immédiatement le véhicule, ainsi que de réclamer le préjudice et les frais qui en résultent, y compris sur le dépôt de garantie.","de":"<span class=\"clause-num\">18.7 Keine Untervermietung, kein Verleihen, keine anderen Fahrer.</span> Der Mieter darf das Fahrzeug weder untervermieten, vermieten, verleihen noch einer anderen Person überlassen, keine Rechte aus diesem Vertrag übertragen und niemanden fahren lassen, der nicht in diesem Vertrag genannt ist. Das Fahrzeug darf nicht für bezahlte Personenbeförderung oder Lieferfahrten genutzt werden, auch nicht über Fahrdienst- oder Liefer-Apps. Ein Verstoß gegen diese Klausel ist eine wesentliche Vertragsverletzung und berechtigt den Vermieter, die Miete zu beenden und das Fahrzeug sofort zurückzunehmen sowie den dadurch entstandenen Schaden und die Kosten zu verlangen, auch durch Einbehalt von der Kaution.","tr":"<span class=\"clause-num\">18.7 Alt kiralama, ödünç verme ve başka sürücü yasağı.</span> Kiracı aracı hiç kimseye alt kiraya veremez, kiralayamaz, ödünç veremez veya teslim edemez; işbu sözleşmeden doğan hakları devredemez ve sözleşmede adı geçmeyen birinin aracı kullanmasına izin veremez. Araç, yolcu taşıma veya kurye uygulamaları üzerinden olanlar dâhil, ücretli yolcu taşımacılığı veya teslimat için kullanılamaz. Bu maddenin ihlali sözleşmenin ağır ihlalidir ve Kiraya Verene kiralamayı sona erdirme ve aracı derhâl geri alma, ayrıca bundan doğan zarar ve masrafları talep etme ve bunları depozitodan mahsup etme hakkı verir."},
  {"th":"<span class=\"clause-num\">18.7 ห้ามให้เช่าช่วง ให้ยืม หรือให้ผู้อื่นขับขี่.</span> ผู้เช่าห้ามให้เช่าช่วง ให้เช่าต่อ ให้ยืม หรือส่งมอบยานพาหนะให้แก่บุคคลใด โอนสิทธิใด ๆ ตามสัญญานี้ หรือยินยอมให้บุคคลที่ไม่ได้ระบุชื่อในสัญญานี้ขับขี่ยานพาหนะ การรับส่งผู้โดยสารและส่งสินค้าเพื่อรับค่าตอบแทนทำได้เฉพาะตามเงื่อนไขในข้อ 10 เท่านั้น การฝ่าฝืนข้อนี้ถือเป็นการผิดสัญญาอย่างมีนัยสำคัญ และให้สิทธิผู้ให้เช่าเลิกการเช่าและนำยานพาหนะคืนได้ทันที และเรียกค่าเสียหายและค่าใช้จ่ายที่เกิดจากการฝ่าฝืนนั้น รวมถึงหักจากเงินประกัน","id":"<span class=\"clause-num\">18.7 Larangan menyewakan kembali, meminjamkan, atau pengemudi lain.</span> Penyewa tidak boleh menyewakan kembali, menyewakan, meminjamkan atau menyerahkan kendaraan kepada siapa pun, mengalihkan hak apa pun berdasarkan perjanjian ini, atau membiarkan orang yang tidak disebut dalam perjanjian ini mengemudikan kendaraan. Angkutan penumpang dan pengantaran berbayar hanya diizinkan dengan syarat-syarat dalam bagian 10. Pelanggaran ketentuan ini merupakan pelanggaran berat terhadap perjanjian ini dan memberi hak kepada Pemilik untuk mengakhiri sewa dan segera menarik kembali kendaraan, serta menuntut kerugian dan biaya yang ditimbulkannya, termasuk dari uang jaminan.","vi":"<span class=\"clause-num\">18.7 Không cho thuê lại, cho mượn hoặc để người khác lái.</span> Bên thuê không được cho thuê lại, cho thuê, cho mượn hoặc giao xe cho bất kỳ ai, chuyển giao bất kỳ quyền nào theo hợp đồng này, hoặc để người không có tên trong hợp đồng này lái xe. Việc chở khách và giao hàng có thu tiền chỉ được phép theo các điều kiện tại mục 10. Vi phạm điều khoản này là vi phạm nghiêm trọng hợp đồng này và cho phép Bên cho thuê chấm dứt việc thuê, thu hồi xe ngay lập tức và đòi bồi thường các thiệt hại và chi phí phát sinh, kể cả trừ vào tiền đặt cọc.","ms":"<span class=\"clause-num\">18.7 Larangan menyewakan semula, meminjamkan atau pemandu lain.</span> Penyewa tidak boleh menyewakan semula, menyewakan, meminjamkan atau menyerahkan kenderaan kepada sesiapa, memindahkan apa-apa hak di bawah perjanjian ini, atau membenarkan sesiapa yang tidak dinamakan dalam perjanjian ini memandu atau menunggangnya. Perjalanan penumpang dan penghantaran berbayar hanya dibenarkan mengikut syarat dalam seksyen 10. Pelanggaran fasal ini merupakan pelanggaran material perjanjian ini dan memberi hak kepada Pemilik untuk menamatkan sewaan dan mengambil semula kenderaan serta-merta, serta menuntut kerugian dan kos yang disebabkannya, termasuk daripada wang cagaran.","fil":"<span class=\"clause-num\">18.7 Bawal ang sub-lease, pagpapahiram o ibang drayber.</span> Hindi maaaring i-sub-lease, ipaupa, ipahiram o ibigay ng Umuupa ang sasakyan sa sinuman, ilipat ang anumang karapatan sa ilalim ng kasunduang ito, o payagang magmaneho ang sinumang hindi nakapangalan sa kasunduang ito. Pinapayagan lamang ang may-bayad na pagsasakay at paghahatid ayon sa mga kondisyon sa seksyon 10. Ang paglabag sa probisyong ito ay isang mabigat na paglabag sa kasunduang ito at nagbibigay ng karapatan sa May-ari na tapusin ang pag-upa at agad bawiin ang sasakyan, at singilin ang mga pinsala at gastos na idinulot nito, kasama ang pagbawas sa deposito.","lo":"<span class=\"clause-num\">18.7 ຫ້າມໃຫ້ເຊົ່າຊ່ວງ, ໃຫ້ຢືມ ຫຼື ໃຫ້ຜູ້ອື່ນຂັບ.</span> ຜູ້ເຊົ່າຫ້າມໃຫ້ເຊົ່າຊ່ວງ, ໃຫ້ເຊົ່າຕໍ່, ໃຫ້ຢືມ ຫຼື ມອບຍານພາຫະນະໃຫ້ແກ່ຜູ້ໃດ, ໂອນສິດໃດໆ ພາຍໃຕ້ສັນຍານີ້ ຫຼື ໃຫ້ຜູ້ທີ່ບໍ່ມີຊື່ໃນສັນຍານີ້ຂັບຂີ່ຍານພາຫະນະ. ການຮັບສົ່ງຜູ້ໂດຍສານ ແລະ ສົ່ງສິນຄ້າເພື່ອຮັບຄ່າຈ້າງ ເຮັດໄດ້ສະເພາະຕາມເງື່ອນໄຂໃນຂໍ້ 10 ເທົ່ານັ້ນ. ການລະເມີດຂໍ້ນີ້ຖືເປັນການລະເມີດສັນຍາຢ່າງຮ້າຍແຮງ ແລະ ໃຫ້ສິດຜູ້ໃຫ້ເຊົ່າຢຸດການເຊົ່າ ແລະ ຍຶດຍານພາຫະນະຄືນໄດ້ທັນທີ ແລະ ຮຽກຮ້ອງຄ່າເສຍຫາຍ ແລະ ຄ່າໃຊ້ຈ່າຍທີ່ເກີດຈາກການລະເມີດນັ້ນ ລວມທັງຫັກຈາກເງິນມັດຈຳ.","km":"<span class=\"clause-num\">18.7 ហាមជួលបន្ត ឲ្យខ្ចី ឬឲ្យអ្នកផ្សេងបើកបរ។</span> អ្នកជួលមិនអាចជួលបន្ត ឲ្យជួល ឲ្យខ្ចី ឬប្រគល់យានយន្តឲ្យនរណាម្នាក់ ផ្ទេរសិទ្ធិណាមួយក្រោមកិច្ចសន្យានេះ ឬអនុញ្ញាតឲ្យអ្នកដែលគ្មានឈ្មោះក្នុងកិច្ចសន្យានេះបើកបរយានយន្តបានឡើយ។ ការដឹកអ្នកដំណើរ និងដឹកជញ្ជូនដើម្បីយកថ្លៃ ត្រូវបានអនុញ្ញាតតែតាមលក្ខខណ្ឌក្នុងផ្នែកទី 10 ប៉ុណ្ណោះ។ ការបំពានប្រការនេះ គឺជាការបំពានធ្ងន់ធ្ងរលើកិច្ចសន្យានេះ ហើយផ្តល់សិទ្ធិឲ្យអ្នកឲ្យជួលបញ្ចប់ការជួល និងដកយានយន្តវិញភ្លាមៗ ព្រមទាំងទាមទារការខូចខាត និងថ្លៃចំណាយដែលបណ្តាលមកពីការនោះ រួមទាំងកាត់ពីប្រាក់កក់។","el":"<span class=\"clause-num\">18.7 Απαγόρευση υπεκμίσθωσης, δανεισμού και άλλων οδηγών.</span> Ο Μισθωτής δεν μπορεί να υπεκμισθώσει, να εκμισθώσει, να δανείσει ή να παραδώσει το όχημα σε οποιονδήποτε, να μεταβιβάσει δικαιώματα από την παρούσα σύμβαση ή να επιτρέψει την οδήγησή του από πρόσωπο που δεν αναφέρεται στη σύμβαση. Οι μεταφορές επιβατών και οι διανομές έναντι αμοιβής επιτρέπονται μόνο υπό τους όρους της ενότητας 10. Η παράβαση του όρου αυτού αποτελεί ουσιώδη παράβαση της σύμβασης και δίνει στον Εκμισθωτή το δικαίωμα να λύσει τη μίσθωση και να πάρει πίσω το όχημα αμέσως, καθώς και να αξιώσει τη ζημία και τα έξοδα που προκύπτουν, μεταξύ άλλων από την εγγύηση.","es":"<span class=\"clause-num\">18.7 Prohibición de subarriendo, préstamo y otros conductores.</span> El Arrendatario no puede subarrendar, alquilar, prestar ni entregar el vehículo a nadie, ceder los derechos derivados de este contrato ni dejar conducir el vehículo a una persona no indicada en este contrato. El transporte de pasajeros y los repartos remunerados solo se permiten en las condiciones de la sección 10. Incumplir esta cláusula es un incumplimiento grave del contrato y faculta al Propietario para poner fin al alquiler y recuperar el vehículo de inmediato, así como para reclamar los perjuicios y gastos que cause, también con cargo a la fianza.","pt":"<span class=\"clause-num\">18.7 Proibição de subaluguer, empréstimo e outros condutores.</span> O Locatário não pode subalugar, alugar, emprestar ou entregar o veículo a ninguém, ceder os direitos deste contrato nem deixar conduzir o veículo alguém não identificado neste contrato. O transporte de passageiros e as entregas remunerados só são permitidos nas condições da secção 10. A violação desta cláusula constitui incumprimento grave do contrato e permite ao Locador pôr fim ao aluguer e recuperar o veículo de imediato, bem como exigir os prejuízos e custos daí resultantes, incluindo por dedução na caução.","it":"<span class=\"clause-num\">18.7 Divieto di sublocazione, prestito e altri conducenti.</span> Il Conduttore non può sublocare, noleggiare, prestare o consegnare il veicolo a nessuno, cedere i diritti derivanti dal presente contratto né far guidare il veicolo a persone non indicate nel contratto. Il trasporto di persone e le consegne a pagamento sono consentiti solo alle condizioni della sezione 10. La violazione di questa clausola costituisce grave inadempimento e consente al Locatore di porre fine al noleggio e riprendere immediatamente il veicolo, nonché di chiedere i danni e i costi che ne derivano, anche trattenendoli dal deposito cauzionale.","hr":"<span class=\"clause-num\">18.7 Zabrana podnajma, posudbe i drugih vozača.</span> Najmoprimac ne smije dati vozilo u podnajam, iznajmiti ga, posuditi ili predati bilo kome, ustupiti prava iz ovog ugovora niti dopustiti da vozilom upravlja osoba koja nije navedena u ovom ugovoru. Plaćeni prijevoz putnika i dostava dopušteni su samo pod uvjetima iz odjeljka 10. Kršenje ove odredbe bitna je povreda ugovora i ovlašćuje Najmodavca da prekine najam i odmah preuzme vozilo te da zahtijeva nastalu štetu i troškove, uključujući iz jamčevine.","fr":"<span class=\"clause-num\">18.7 Interdiction de sous-location, de prêt et d'autres conducteurs.</span> Le Locataire ne peut ni sous-louer, ni louer, ni prêter, ni remettre le véhicule à quiconque, ni céder les droits du présent contrat, ni laisser conduire le véhicule par une personne non désignée dans le contrat. Le transport de personnes et les livraisons rémunérés ne sont autorisés qu'aux conditions de la section 10. Tout manquement à cette clause constitue un manquement grave au contrat et permet au Loueur de mettre fin à la location et de reprendre immédiatement le véhicule, ainsi que de réclamer le préjudice et les frais qui en résultent, y compris sur le dépôt de garantie.","de":"<span class=\"clause-num\">18.7 Keine Untervermietung, kein Verleihen, keine anderen Fahrer.</span> Der Mieter darf das Fahrzeug weder untervermieten, vermieten, verleihen noch einer anderen Person überlassen, keine Rechte aus diesem Vertrag übertragen und niemanden fahren lassen, der nicht in diesem Vertrag genannt ist. Bezahlte Personenbeförderung und Lieferfahrten sind nur zu den Bedingungen in Abschnitt 10 erlaubt. Ein Verstoß gegen diese Klausel ist eine wesentliche Vertragsverletzung und berechtigt den Vermieter, die Miete zu beenden und das Fahrzeug sofort zurückzunehmen sowie den dadurch entstandenen Schaden und die Kosten zu verlangen, auch durch Einbehalt von der Kaution.","tr":"<span class=\"clause-num\">18.7 Alt kiralama, ödünç verme ve başka sürücü yasağı.</span> Kiracı aracı hiç kimseye alt kiraya veremez, kiralayamaz, ödünç veremez veya teslim edemez; işbu sözleşmeden doğan hakları devredemez ve sözleşmede adı geçmeyen birinin aracı kullanmasına izin veremez. Ücretli yolcu taşıma ve teslimata yalnızca 10. bölümdeki koşullarla izin verilir. Bu maddenin ihlali sözleşmenin ağır ihlalidir ve Kiraya Verene kiralamayı sona erdirme ve aracı derhâl geri alma, ayrıca bundan doğan zarar ve masrafları talep etme ve bunları depozitodan mahsup etme hakkı verir."},
  {"th":"ห้ามใช้ยานพาหนะเพื่อกิจกรรมผิดกฎหมาย แข่งขัน ลากจูง ขับออฟโรดเว้นแต่ตกลงไว้ ขับขี่ขณะมึนเมา ขนส่งสิ่งผิดกฎหมาย หรือใช้งานนอกพื้นที่ที่ตกลงกัน","id":"Kendaraan tidak boleh digunakan untuk kegiatan ilegal, balapan, menarik kendaraan lain, berkendara di luar jalan kecuali disepakati, berkendara di bawah pengaruh alkohol atau narkoba, mengangkut barang terlarang, atau penggunaan di luar wilayah yang disepakati.","vi":"Không được sử dụng xe cho hoạt động bất hợp pháp, đua xe, kéo xe, đi đường địa hình trừ khi đã thỏa thuận, lái xe khi say rượu hoặc dùng chất kích thích, chở hàng cấm, hoặc sử dụng ngoài khu vực đã thỏa thuận.","ms":"Kenderaan tidak boleh digunakan untuk aktiviti haram, perlumbaan, menunda, pemanduan luar jalan melainkan dipersetujui, memandu di bawah pengaruh alkohol atau dadah, membawa barang yang menyalahi undang-undang, atau penggunaan di luar kawasan yang dipersetujui.","fil":"Hindi dapat gamitin ang sasakyan sa ilegal na gawain, karera, paghila, pagmamaneho sa labas ng kalsada maliban kung napagkasunduan, pagmamaneho nang lasing o nasa impluwensya ng droga, pagdadala ng ilegal na kalakal, o anumang paggamit sa labas ng napagkasunduang lugar.","lo":"ຫ້າມໃຊ້ຍານພາຫະນະເພື່ອກິດຈະກຳທີ່ຜິດກົດໝາຍ, ການແຂ່ງຂັນ, ການລາກຈູງ, ການຂັບນອກເສັ້ນທາງເວັ້ນເສຍແຕ່ຕົກລົງໄວ້, ການຂັບຂີ່ຂະນະມຶນເມົາ, ການຂົນສົ່ງສິ່ງຜິດກົດໝາຍ ຫຼື ການນຳໃຊ້ນອກພື້ນທີ່ທີ່ຕົກລົງກັນ.","km":"ហាមប្រើយានយន្តសម្រាប់សកម្មភាពខុសច្បាប់ ការប្រណាំង ការអូស ការបើកបរក្រៅផ្លូវ លើកលែងតែបានព្រមព្រៀង ការបើកបរក្រោមឥទ្ធិពលស្រា ឬគ្រឿងញៀន ការដឹកទំនិញខុសច្បាប់ ឬការប្រើប្រាស់ក្រៅតំបន់ដែលបានព្រមព្រៀង។","el":"Απαγορεύεται η χρήση του οχήματος για παράνομες δραστηριότητες, αγώνες, ρυμούλκηση, οδήγηση εκτός δρόμου χωρίς συμφωνία, οδήγηση υπό την επήρεια αλκοόλ ή ουσιών, μεταφορά παράνομων αγαθών ή χρήση εκτός της συμφωνημένης περιοχής.","es":"El vehículo no puede utilizarse para actividades ilícitas, carreras, remolcar, circular fuera de carretera salvo acuerdo, conducir bajo los efectos del alcohol o las drogas, transportar mercancías ilícitas ni fuera de la zona acordada.","pt":"O veículo não pode ser utilizado para atividades ilícitas, corridas, reboque, condução fora de estrada salvo acordo, condução sob a influência de álcool ou drogas, transporte de mercadorias ilícitas ou fora da zona acordada.","it":"Il veicolo non può essere usato per attività illecite, gare, traino, guida fuoristrada salvo accordo, guida sotto l'effetto di alcol o droghe, trasporto di merci illecite o al di fuori della zona concordata.","hr":"Vozilo se ne smije koristiti za nezakonite aktivnosti, utrke, vuču, vožnju izvan cesta osim ako je dogovoreno, vožnju pod utjecajem alkohola ili droga, prijevoz nedopuštene robe niti izvan dogovorenog područja.","fr":"Le véhicule ne peut pas être utilisé pour des activités illicites, des courses, du remorquage, la conduite hors route sauf accord, la conduite sous l'emprise de l'alcool ou de stupéfiants, le transport de marchandises illicites ou en dehors de la zone convenue.","de":"Das Fahrzeug darf nicht für rechtswidrige Zwecke, Rennen, zum Abschleppen, im Gelände (sofern nicht vereinbart), unter dem Einfluss von Alkohol oder Drogen, zum Transport verbotener Waren oder außerhalb des vereinbarten Gebiets genutzt werden.","tr":"Araç; yasa dışı faaliyetlerde, yarışlarda, çekme işinde, kararlaştırılmadıkça arazi sürüşünde, alkol veya uyuşturucu etkisi altında, yasa dışı yük taşımada veya kararlaştırılan bölge dışında kullanılamaz."},
  {"th":"<strong>การรับส่งผู้โดยสารและส่งสินค้าเพื่อรับค่าตอบแทน.</strong> ผู้เช่าสามารถใช้ยานพาหนะรับส่งผู้โดยสารหรือส่งอาหารหรือสินค้าเพื่อรับค่าตอบแทน รวมถึงผ่านแอปพลิเคชันเรียกรถหรือส่งสินค้า ได้ภายใต้เงื่อนไขดังนี้ (ก) ผู้เช่าต้องมีและรักษาให้มีผลอยู่เสมอซึ่งใบอนุญาตขับขี่ ใบอนุญาต และการจดทะเบียนทุกอย่างที่กฎหมายกำหนดสำหรับงานนั้น เช่น ใบอนุญาตสำหรับรถรับจ้างผ่านแอปพลิเคชันหรือใบอนุญาตขับรถสาธารณะ หากกฎหมายกำหนด (ข) ประกันภัยปกติของยานพาหนะอาจไม่คุ้มครองการรับส่งผู้โดยสารหรือส่งสินค้าเพื่อรับค่าตอบแทน ผู้เช่าจึงต้องมีประกันภัยที่เหมาะสมกับการใช้งานดังกล่าว หรือใช้ความคุ้มครองของแอปพลิเคชันในกรณีที่มี (ค) ผู้เช่าต้องปฏิบัติตามกฎของแอปพลิเคชันและกฎหมาย (ง) ผู้เช่าต้องรับผิดชอบค่าปรับ ความเสียหาย และการสึกหรอที่เกิดจากการใช้งานดังกล่าว (จ) ยังคงห้ามให้เช่าช่วง ให้ยืม และให้ผู้ที่ไม่ได้ระบุชื่อในสัญญานี้ขับขี่ (ฉ) เงื่อนไขประกันภัยของยานพาหนะ และเงินประกันเพิ่มเติม ข้อจำกัดระยะทาง หรือเงื่อนไขอื่นใดในสัญญานี้ยังคงใช้บังคับ","id":"<strong>Angkutan penumpang dan pengantaran berbayar.</strong> Penyewa boleh menggunakan kendaraan untuk mengangkut penumpang atau mengantar makanan atau barang dengan bayaran, termasuk melalui aplikasi transportasi daring atau pengiriman, dengan syarat: (a) Penyewa memiliki, dan menjaga tetap berlaku, setiap SIM, izin dan pendaftaran yang diwajibkan hukum untuk pekerjaan tersebut, seperti izin angkutan daring atau SIM umum jika berlaku; (b) asuransi standar kendaraan mungkin tidak menanggung penggunaan untuk penumpang atau pengiriman berbayar, sehingga Penyewa wajib memiliki asuransi yang sesuai untuk penggunaan itu, atau menggunakan perlindungan dari aplikasi jika tersedia; (c) Penyewa mematuhi aturan aplikasi dan hukum; (d) Penyewa bertanggung jawab atas denda, kerusakan dan keausan yang timbul dari penggunaan tersebut; (e) menyewakan kembali, meminjamkan, dan pengemudi yang tidak disebut dalam perjanjian ini tetap dilarang; (f) ketentuan asuransi kendaraan serta setiap uang jaminan tambahan, batas jarak tempuh atau ketentuan lain dalam perjanjian ini tetap berlaku.","vi":"<strong>Chở khách và giao hàng có thu tiền.</strong> Bên thuê được dùng xe để chở khách hoặc giao đồ ăn, hàng hóa có thu tiền, kể cả qua ứng dụng gọi xe hoặc giao hàng, với các điều kiện sau: (a) Bên thuê có và duy trì hiệu lực mọi giấy phép lái xe, giấy phép và đăng ký mà pháp luật yêu cầu cho công việc đó, chẳng hạn giấy phép kinh doanh vận tải hoặc giấy phép lái xe phù hợp nếu có yêu cầu; (b) bảo hiểm thông thường của xe có thể không bảo hiểm cho việc chở khách hoặc giao hàng có thu tiền, vì vậy Bên thuê phải có bảo hiểm phù hợp cho mục đích đó, hoặc sử dụng bảo hiểm của ứng dụng nếu có; (c) Bên thuê tuân thủ quy định của ứng dụng và pháp luật; (d) Bên thuê chịu trách nhiệm về tiền phạt, hư hỏng và hao mòn phát sinh từ việc sử dụng đó; (e) việc cho thuê lại, cho mượn và để người không có tên trong hợp đồng này lái xe vẫn bị cấm; (f) các điều khoản bảo hiểm của xe và mọi khoản đặt cọc bổ sung, giới hạn quãng đường hoặc điều khoản khác trong hợp đồng này vẫn được áp dụng.","ms":"<strong>Perjalanan penumpang dan penghantaran berbayar.</strong> Penyewa boleh menggunakan kenderaan untuk membawa penumpang atau menghantar makanan atau barang untuk bayaran, termasuk melalui aplikasi e-hailing atau penghantaran, dengan syarat: (a) Penyewa memegang, dan mengekalkan kesahan, setiap lesen, permit dan pendaftaran yang dikehendaki oleh undang-undang untuk kerja tersebut, seperti lesen PSV atau permit e-hailing jika berkenaan; (b) insurans biasa kenderaan mungkin tidak melindungi penggunaan untuk penumpang atau penghantaran berbayar, maka Penyewa mesti mempunyai insurans yang sesuai untuk penggunaan itu, atau menggunakan perlindungan aplikasi jika ada; (c) Penyewa mematuhi peraturan aplikasi dan undang-undang; (d) Penyewa bertanggungjawab atas denda, kerosakan dan haus yang timbul daripada penggunaan itu; (e) menyewakan semula, meminjamkan dan pemandu yang tidak dinamakan dalam perjanjian ini kekal dilarang; (f) terma insurans kenderaan dan sebarang wang cagaran tambahan, had perbatuan atau terma lain dalam perjanjian ini masih terpakai.","fil":"<strong>Bayad na pagsasakay at paghahatid.</strong> Maaaring gamitin ng Umuupa ang sasakyan sa pagsasakay ng pasahero o paghahatid ng pagkain o kalakal nang may bayad, kasama ang sa pamamagitan ng ride-hailing o delivery app, sa mga kondisyong ito: (a) may hawak ang Umuupa, at pinananatiling may bisa, ng bawat lisensya, permit at rehistrong hinihingi ng batas para sa gawaing iyon, gaya ng permit para sa ride-hailing o lisensyang pang-komersyal na drayber kung kinakailangan; (b) maaaring hindi saklaw ng karaniwang insurance ng sasakyan ang may-bayad na pagsasakay o paghahatid, kaya dapat may insurance ang Umuupa na angkop sa ganitong gamit, o gamitin ang cover ng app kung mayroon; (c) sinusunod ng Umuupa ang mga patakaran ng app at ang batas; (d) pananagutan ng Umuupa ang anumang multa, pinsala at pagkasira na dulot ng ganitong gamit; (e) nananatiling bawal ang sub-lease, pagpapahiram at mga drayber na hindi nakapangalan sa kasunduang ito; (f) nananatiling may bisa ang mga tuntunin ng insurance ng sasakyan at anumang dagdag na deposito, limitasyon sa layo o iba pang tuntunin sa kasunduang ito.","lo":"<strong>ການຮັບສົ່ງຜູ້ໂດຍສານ ແລະ ສົ່ງສິນຄ້າເພື່ອຮັບຄ່າຈ້າງ.</strong> ຜູ້ເຊົ່າສາມາດໃຊ້ຍານພາຫະນະຮັບສົ່ງຜູ້ໂດຍສານ ຫຼື ສົ່ງອາຫານ ຫຼື ສິນຄ້າເພື່ອຮັບຄ່າຈ້າງ ລວມທັງຜ່ານແອັບຮັບສົ່ງ ຫຼື ສົ່ງເຄື່ອງ ໄດ້ພາຍໃຕ້ເງື່ອນໄຂດັ່ງນີ້: (ກ) ຜູ້ເຊົ່າຕ້ອງມີ ແລະ ຮັກສາໃຫ້ມີຜົນສະເໝີ ໃບຂັບຂີ່, ໃບອະນຸຍາດ ແລະ ການຈົດທະບຽນທຸກຢ່າງທີ່ກົດໝາຍກຳນົດສຳລັບວຽກນັ້ນ ເຊັ່ນ ໃບອະນຸຍາດຮັບສົ່ງຜ່ານແອັບ ຫຼື ໃບຂັບຂີ່ສຳລັບການຄ້າ ຖ້າມີການກຳນົດ; (ຂ) ປະກັນໄພປົກກະຕິຂອງຍານພາຫະນະອາດບໍ່ຄຸ້ມຄອງການຮັບສົ່ງຜູ້ໂດຍສານ ຫຼື ສົ່ງສິນຄ້າເພື່ອຮັບຄ່າຈ້າງ ຜູ້ເຊົ່າຈຶ່ງຕ້ອງມີປະກັນໄພທີ່ເໝາະສົມກັບການນຳໃຊ້ດັ່ງກ່າວ ຫຼື ໃຊ້ການຄຸ້ມຄອງຂອງແອັບໃນກໍລະນີທີ່ມີ; (ຄ) ຜູ້ເຊົ່າຕ້ອງປະຕິບັດຕາມກົດຂອງແອັບ ແລະ ກົດໝາຍ; (ງ) ຜູ້ເຊົ່າຮັບຜິດຊອບຄ່າປັບໃໝ, ຄວາມເສຍຫາຍ ແລະ ການສຶກຫຼໍທີ່ເກີດຈາກການນຳໃຊ້ດັ່ງກ່າວ; (ຈ) ຍັງຄົງຫ້າມໃຫ້ເຊົ່າຊ່ວງ, ໃຫ້ຢືມ ແລະ ໃຫ້ຜູ້ທີ່ບໍ່ມີຊື່ໃນສັນຍານີ້ຂັບຂີ່; (ສ) ເງື່ອນໄຂປະກັນໄພຂອງຍານພາຫະນະ ແລະ ເງິນມັດຈຳເພີ່ມເຕີມ, ຂີດຈຳກັດໄລຍະທາງ ຫຼື ເງື່ອນໄຂອື່ນໃດໃນສັນຍານີ້ຍັງຄົງນຳໃຊ້.","km":"<strong>ការដឹកអ្នកដំណើរ និងដឹកជញ្ជូនដើម្បីយកថ្លៃ.</strong> អ្នកជួលអាចប្រើយានយន្តដើម្បីដឹកអ្នកដំណើរ ឬដឹកជញ្ជូនអាហារ ឬទំនិញដើម្បីយកថ្លៃ រួមទាំងតាមរយៈកម្មវិធីដឹកអ្នកដំណើរ ឬដឹកជញ្ជូន ក្រោមលក្ខខណ្ឌដូចខាងក្រោម៖ (ក) អ្នកជួលត្រូវមាន និងរក្សាឲ្យមានសុពលភាពជានិច្ច នូវប័ណ្ណបើកបរ លិខិតអនុញ្ញាត និងការចុះបញ្ជីទាំងអស់ដែលច្បាប់តម្រូវសម្រាប់ការងារនោះ ដូចជាលិខិតអនុញ្ញាតដឹកអ្នកដំណើរតាមកម្មវិធី ឬប័ណ្ណបើកបរពាណិជ្ជកម្ម ប្រសិនបើតម្រូវ; (ខ) ធានារ៉ាប់រងធម្មតារបស់យានយន្តអាចមិនគ្របដណ្តប់ការដឹកអ្នកដំណើរ ឬដឹកជញ្ជូនដើម្បីយកថ្លៃ ដូច្នេះអ្នកជួលត្រូវមានធានារ៉ាប់រងសមស្របសម្រាប់ការប្រើប្រាស់នោះ ឬប្រើការគ្របដណ្តប់របស់កម្មវិធីនៅពេលមាន; (គ) អ្នកជួលត្រូវគោរពតាមច្បាប់របស់កម្មវិធី និងច្បាប់; (ឃ) អ្នកជួលទទួលខុសត្រូវលើការពិន័យ ការខូចខាត និងការសឹករិចរិលដែលកើតចេញពីការប្រើប្រាស់នោះ; (ង) ការជួលបន្ត ការឲ្យខ្ចី និងការឲ្យអ្នកដែលគ្មានឈ្មោះក្នុងកិច្ចសន្យានេះបើកបរ នៅតែត្រូវបានហាមឃាត់; (ច) លក្ខខណ្ឌធានារ៉ាប់រងរបស់យានយន្ត និងប្រាក់កក់បន្ថែម ដែនកំណត់ចម្ងាយ ឬលក្ខខណ្ឌផ្សេងទៀតក្នុងកិច្ចសន្យានេះ នៅតែអនុវត្ត។","el":"<strong>Μεταφορές επιβατών και διανομές έναντι αμοιβής.</strong> Ο Μισθωτής μπορεί να χρησιμοποιεί το όχημα για μεταφορά επιβατών ή διανομή φαγητού ή αγαθών έναντι αμοιβής, και μέσω εφαρμογών μεταφοράς ή διανομής, υπό τους εξής όρους: (α) ο Μισθωτής διαθέτει, και διατηρεί σε ισχύ, κάθε άδεια, έγκριση και εγγραφή που απαιτεί ο νόμος για την εργασία αυτή, όπως άδεια μεταφοράς επιβατών μέσω εφαρμογής ή επαγγελματική άδεια οδήγησης όπου απαιτείται· (β) η συνήθης ασφάλιση του οχήματος ενδέχεται να μην καλύπτει τη μεταφορά επιβατών ή τις διανομές έναντι αμοιβής, γι' αυτό ο Μισθωτής πρέπει να έχει ασφάλιση κατάλληλη για τη χρήση αυτή ή να χρησιμοποιεί την κάλυψη της εφαρμογής όπου υπάρχει· (γ) ο Μισθωτής τηρεί τους κανόνες της εφαρμογής και τον νόμο· (δ) ο Μισθωτής ευθύνεται για πρόστιμα, ζημίες και φθορές που προκύπτουν από τη χρήση αυτή· (ε) η υπεκμίσθωση, ο δανεισμός και οδηγοί που δεν αναφέρονται στη σύμβαση εξακολουθούν να απαγορεύονται· (στ) οι ασφαλιστικοί όροι του οχήματος και κάθε πρόσθετη εγγύηση, όριο χιλιομέτρων ή άλλος όρος της σύμβασης εξακολουθούν να ισχύουν.","es":"<strong>Transporte de pasajeros y repartos remunerados.</strong> El Arrendatario puede usar el vehículo para transportar pasajeros o repartir comida o mercancías a cambio de pago, incluso mediante aplicaciones de VTC o de reparto, con estas condiciones: (a) el Arrendatario tiene, y mantiene vigentes, todos los permisos, licencias y registros que exige la ley para esa actividad, como una autorización de VTC o un permiso de conductor profesional cuando proceda; (b) el seguro habitual del vehículo puede no cubrir el transporte de pasajeros o los repartos remunerados, por lo que el Arrendatario debe tener un seguro adecuado para ese uso, o usar la cobertura de la aplicación cuando exista; (c) el Arrendatario cumple las normas de la aplicación y la ley; (d) el Arrendatario responde de las multas, daños y desgaste derivados de ese uso; (e) siguen prohibidos el subarriendo, el préstamo y los conductores no indicados en este contrato; (f) siguen aplicándose las condiciones del seguro del vehículo y cualquier fianza adicional, límite de kilometraje u otra condición de este contrato.","pt":"<strong>Transporte de passageiros e entregas remunerados.</strong> O Locatário pode usar o veículo para transportar passageiros ou entregar refeições ou mercadorias mediante pagamento, incluindo através de plataformas TVDE ou de entregas, nas seguintes condições: (a) o Locatário tem, e mantém válidos, todas as cartas, licenças, certificados e registos que a lei exige para essa atividade, como o certificado de motorista TVDE ou uma licença de condutor profissional quando aplicável; (b) o seguro normal do veículo pode não cobrir o transporte de passageiros ou as entregas remuneradas, pelo que o Locatário deve ter um seguro adequado a esse uso, ou usar a cobertura da plataforma quando exista; (c) o Locatário cumpre as regras da plataforma e a lei; (d) o Locatário é responsável pelas multas, danos e desgaste resultantes desse uso; (e) continuam proibidos o subaluguer, o empréstimo e os condutores não identificados neste contrato; (f) continuam a aplicar-se as condições do seguro do veículo e qualquer caução adicional, limite de quilometragem ou outra condição deste contrato.","it":"<strong>Trasporto di persone e consegne a pagamento.</strong> Il Conduttore può usare il veicolo per trasportare persone o consegnare cibo o merci a pagamento, anche tramite app di trasporto o di consegna, alle seguenti condizioni: (a) il Conduttore possiede, e mantiene validi, tutte le patenti, licenze, autorizzazioni e iscrizioni richieste dalla legge per tale attività, come un'autorizzazione per il trasporto di persone tramite app o una patente professionale ove previste; (b) l'assicurazione ordinaria del veicolo potrebbe non coprire il trasporto di persone o le consegne a pagamento, quindi il Conduttore deve avere un'assicurazione adatta a tale uso, o usare la copertura dell'app ove prevista; (c) il Conduttore rispetta le regole dell'app e la legge; (d) il Conduttore risponde di multe, danni e usura derivanti da tale uso; (e) restano vietati la sublocazione, il prestito e i conducenti non indicati nel contratto; (f) restano applicabili le condizioni assicurative del veicolo e ogni ulteriore deposito, limite di chilometraggio o altra condizione del contratto.","hr":"<strong>Plaćeni prijevoz putnika i dostava.</strong> Najmoprimac smije koristiti vozilo za prijevoz putnika ili dostavu hrane ili robe uz plaćanje, uključujući putem aplikacija za prijevoz ili dostavu, pod sljedećim uvjetima: (a) Najmoprimac ima, i održava valjanima, sve vozačke dozvole, dozvole, licencije i upise koje zakon zahtijeva za taj posao, poput dozvole za prijevoz putnika putem aplikacije ili profesionalne vozačke dozvole kada je propisano; (b) uobičajeno osiguranje vozila možda ne pokriva plaćeni prijevoz putnika ili dostavu, pa Najmoprimac mora imati osiguranje prikladno za tu namjenu ili koristiti pokriće aplikacije kada postoji; (c) Najmoprimac poštuje pravila aplikacije i zakon; (d) Najmoprimac odgovara za kazne, štetu i trošenje nastale takvom uporabom; (e) podnajam, posudba i vozači koji nisu navedeni u ovom ugovoru i dalje su zabranjeni; (f) i dalje vrijede uvjeti osiguranja vozila te svaka dodatna jamčevina, ograničenje kilometraže ili drugi uvjet ovog ugovora.","fr":"<strong>Transport de personnes et livraisons rémunérés.</strong> Le Locataire peut utiliser le véhicule pour transporter des personnes ou livrer des repas ou des marchandises contre rémunération, y compris via des applications de VTC ou de livraison, aux conditions suivantes : (a) le Locataire détient, et maintient en cours de validité, tous les permis, cartes, autorisations et inscriptions que la loi exige pour cette activité, comme la carte professionnelle de VTC ou une autorisation de transport lorsqu'elles s'appliquent ; (b) l'assurance habituelle du véhicule peut ne pas couvrir le transport de personnes ou les livraisons rémunérés, le Locataire doit donc disposer d'une assurance adaptée à cet usage, ou utiliser la couverture de l'application lorsqu'elle existe ; (c) le Locataire respecte les règles de l'application et la loi ; (d) le Locataire est responsable des amendes, des dommages et de l'usure résultant de cet usage ; (e) la sous-location, le prêt et les conducteurs non désignés dans le contrat restent interdits ; (f) les conditions d'assurance du véhicule et tout dépôt de garantie supplémentaire, limite de kilométrage ou autre condition du contrat continuent de s'appliquer.","de":"<strong>Bezahlte Personenbeförderung und Lieferfahrten.</strong> Der Mieter darf das Fahrzeug zur Beförderung von Personen oder zur Lieferung von Speisen oder Waren gegen Entgelt nutzen, auch über Fahrdienst- oder Liefer-Apps, unter folgenden Bedingungen: (a) der Mieter besitzt alle Fahrerlaubnisse, Genehmigungen und Eintragungen, die das Gesetz für diese Tätigkeit verlangt, etwa eine Genehmigung für Fahrdienste oder eine Fahrerlaubnis zur Fahrgastbeförderung, soweit erforderlich, und hält sie gültig; (b) die übliche Versicherung des Fahrzeugs deckt die entgeltliche Personenbeförderung oder Lieferfahrten möglicherweise nicht ab, daher muss der Mieter eine für diese Nutzung geeignete Versicherung haben oder den Versicherungsschutz der App nutzen, soweit vorhanden; (c) der Mieter hält die Regeln der App und das Gesetz ein; (d) der Mieter haftet für Bußgelder, Schäden und Abnutzung aus dieser Nutzung; (e) Untervermietung, Verleihen und nicht in diesem Vertrag genannte Fahrer bleiben verboten; (f) die Versicherungsbedingungen des Fahrzeugs sowie jede zusätzliche Kaution, Kilometerbegrenzung oder sonstige Bedingung dieses Vertrags gelten weiter.","tr":"<strong>Ücretli yolcu taşıma ve teslimat.</strong> Kiracı aracı, yolcu taşıma veya kurye uygulamaları üzerinden olanlar dâhil, ücret karşılığında yolcu taşımak veya yemek ya da eşya teslim etmek için şu koşullarla kullanabilir: (a) Kiracı bu iş için mevzuatın gerektirdiği her türlü ehliyet, izin ve kaydı taşır ve geçerli tutar, örneğin gerektiğinde yolcu taşıma uygulaması izni veya ticari sürücü belgesi; (b) aracın standart sigortası ücretli yolcu taşımayı veya teslimatı kapsamayabilir, bu nedenle Kiracı bu kullanıma uygun bir sigortaya sahip olmalı veya varsa uygulamanın sağladığı teminatı kullanmalıdır; (c) Kiracı uygulamanın kurallarına ve mevzuata uyar; (d) Kiracı bu kullanımdan doğan cezalardan, hasarlardan ve aşınmadan sorumludur; (e) alt kiralama, ödünç verme ve sözleşmede adı geçmeyen sürücüler yasak olmaya devam eder; (f) aracın sigorta koşulları ile sözleşmedeki her türlü ek depozito, kilometre sınırı veya diğer koşullar geçerliliğini korur."},
  {"th":"<span class=\"clause-num\">18.8 เงื่อนไขพิเศษ.</span> เงื่อนไขพิเศษข้างต้นเป็นส่วนหนึ่งของสัญญานี้และมีผลผูกพันผู้เช่า","id":"<span class=\"clause-num\">18.8 Ketentuan khusus.</span> Ketentuan khusus di atas merupakan bagian dari perjanjian ini dan mengikat Penyewa.","vi":"<span class=\"clause-num\">18.8 Điều kiện đặc biệt.</span> Các điều kiện đặc biệt nêu trên là một phần của hợp đồng này và ràng buộc Bên thuê.","ms":"<span class=\"clause-num\">18.8 Syarat khas.</span> Syarat khas di atas adalah sebahagian daripada perjanjian ini dan mengikat Penyewa.","fil":"<span class=\"clause-num\">18.8 Mga espesyal na kondisyon.</span> Ang mga espesyal na kondisyon sa itaas ay bahagi ng kasunduang ito at may bisa sa Umuupa.","lo":"<span class=\"clause-num\">18.8 ເງື່ອນໄຂພິເສດ.</span> ເງື່ອນໄຂພິເສດຂ້າງເທິງເປັນສ່ວນໜຶ່ງຂອງສັນຍານີ້ ແລະ ມີຜົນຜູກມັດຜູ້ເຊົ່າ.","km":"<span class=\"clause-num\">18.8 លក្ខខណ្ឌពិសេស។</span> លក្ខខណ្ឌពិសេសខាងលើជាផ្នែកមួយនៃកិច្ចសន្យានេះ ហើយមានអានុភាពលើអ្នកជួល។","el":"<span class=\"clause-num\">18.8 Ειδικοί όροι.</span> Οι ειδικοί όροι που αναφέρονται παραπάνω αποτελούν μέρος της παρούσας σύμβασης και δεσμεύουν τον Μισθωτή.","es":"<span class=\"clause-num\">18.8 Condiciones especiales.</span> Las condiciones especiales indicadas arriba forman parte de este contrato y obligan al Arrendatario.","pt":"<span class=\"clause-num\">18.8 Condições especiais.</span> As condições especiais acima indicadas fazem parte deste contrato e vinculam o Locatário.","it":"<span class=\"clause-num\">18.8 Condizioni particolari.</span> Le condizioni particolari sopra indicate fanno parte del presente contratto e vincolano il Conduttore.","hr":"<span class=\"clause-num\">18.8 Posebni uvjeti.</span> Gore navedeni posebni uvjeti sastavni su dio ovog ugovora i obvezuju Najmoprimca.","fr":"<span class=\"clause-num\">18.8 Conditions particulières.</span> Les conditions particulières ci-dessus font partie du présent contrat et engagent le Locataire.","de":"<span class=\"clause-num\">18.8 Besondere Vereinbarungen.</span> Die oben genannten besonderen Vereinbarungen sind Bestandteil dieses Vertrags und für den Mieter verbindlich.","tr":"<span class=\"clause-num\">18.8 Özel şartlar.</span> Yukarıda belirtilen özel şartlar işbu sözleşmenin bir parçasıdır ve Kiracıyı bağlar."},
  {"th":"เจ้าของมีหน้าที่รักษายานพาหนะให้อยู่ในสภาพพร้อมใช้งานตลอดระยะเวลาเช่า หากยานพาหนะไม่สามารถใช้งานได้เนื่องจากความขัดข้องทางกลไกหรือการเสียที่ไม่ได้เกิดจากความประมาทของผู้เช่า และเจ้าของไม่สามารถแก้ไขหรือจัดหายานพาหนะทดแทนที่เหมาะสมได้ภายใน <strong>24 ชั่วโมง</strong> นับจากที่ผู้เช่าแจ้ง ผู้เช่ามีสิทธิ์ขอยกเลิกสัญญาและรับเงินคืนตามสัดส่วนสำหรับระยะเวลาที่เหลืออยู่","id":"Pemilik bertanggung jawab menjaga kendaraan dalam kondisi laik jalan dan dapat digunakan selama masa sewa. Jika kendaraan tidak dapat digunakan karena kerusakan mesin atau mogok yang bukan disebabkan kelalaian Penyewa, dan Pemilik tidak dapat memperbaikinya atau menyediakan kendaraan pengganti yang sesuai dalam <strong>24 jam</strong> sejak Penyewa memberi tahu Pemilik, Penyewa berhak meminta pembatalan perjanjian dan menerima pengembalian uang secara proporsional untuk sisa masa sewa yang belum digunakan.","vi":"Bên cho thuê có trách nhiệm duy trì xe ở tình trạng an toàn và vận hành được trong suốt thời gian thuê. Nếu xe không thể vận hành do hỏng hóc cơ khí không phải do lỗi của Bên thuê, và Bên cho thuê không thể khắc phục hoặc cung cấp xe thay thế phù hợp trong vòng <strong>24 giờ</strong> kể từ khi Bên thuê thông báo, Bên thuê có quyền yêu cầu hủy hợp đồng và được hoàn lại tiền tương ứng với thời gian thuê còn lại chưa sử dụng.","ms":"Pemilik bertanggungjawab memastikan kenderaan berada dalam keadaan selamat dipandu dan boleh digunakan sepanjang tempoh sewa. Jika kenderaan tidak dapat digunakan akibat kerosakan mekanikal yang bukan disebabkan kecuaian Penyewa, dan Pemilik tidak dapat membaikinya atau menyediakan kenderaan gantian yang sesuai dalam tempoh <strong>24 jam</strong> selepas Penyewa memaklumkan Pemilik, Penyewa berhak meminta pembatalan kontrak dan menerima bayaran balik secara pro rata bagi baki tempoh yang tidak digunakan.","fil":"Responsibilidad ng May-ari na panatilihing ligtas at gumagana ang sasakyan sa buong panahon ng upa. Kung hindi magamit ang sasakyan dahil sa sirang mekanikal na hindi dulot ng kapabayaan ng Umuupa, at hindi ito maayos ng May-ari o makapagbigay ng angkop na kapalit na sasakyan sa loob ng <strong>24 na oras</strong> mula nang ipaalam ng Umuupa, may karapatan ang Umuupa na hilingin ang pagkansela ng kontrata at makatanggap ng proporsyonal na refund para sa natitirang hindi nagamit na panahon.","lo":"ຜູ້ໃຫ້ເຊົ່າມີໜ້າທີ່ຮັກສາຍານພາຫະນະໃຫ້ຢູ່ໃນສະພາບພ້ອມໃຊ້ງານຕະຫຼອດໄລຍະເວລາເຊົ່າ. ຖ້າຍານພາຫະນະບໍ່ສາມາດໃຊ້ງານໄດ້ເນື່ອງຈາກຂໍ້ຂັດຂ້ອງທາງກົນຈັກ ຫຼື ລົດເປ່ເພທີ່ບໍ່ໄດ້ເກີດຈາກຄວາມປະໝາດຂອງຜູ້ເຊົ່າ ແລະ ຜູ້ໃຫ້ເຊົ່າບໍ່ສາມາດແກ້ໄຂ ຫຼື ຈັດຫາຍານພາຫະນະທົດແທນທີ່ເໝາະສົມໄດ້ພາຍໃນ <strong>24 ຊົ່ວໂມງ</strong> ນັບແຕ່ຜູ້ເຊົ່າແຈ້ງ ຜູ້ເຊົ່າມີສິດຂໍຍົກເລີກສັນຍາ ແລະ ຮັບເງິນຄືນຕາມສັດສ່ວນສຳລັບໄລຍະເວລາທີ່ເຫຼືອ.","km":"អ្នកឲ្យជួលទទួលខុសត្រូវថែរក្សាយានយន្តឲ្យស្ថិតក្នុងស្ថានភាពអាចបើកបរ និងប្រើប្រាស់បានពេញមួយរយៈពេលជួល។ ប្រសិនបើយានយន្តមិនអាចប្រើប្រាស់បានដោយសារការខូចមេកានិក ដែលមិនមែនបណ្តាលមកពីការធ្វេសប្រហែសរបស់អ្នកជួល ហើយអ្នកឲ្យជួលមិនអាចជួសជុល ឬផ្តល់យានយន្តជំនួសសមរម្យក្នុងរយៈពេល <strong>២៤ ម៉ោង</strong> គិតពីពេលអ្នកជួលជូនដំណឹង អ្នកជួលមានសិទ្ធិស្នើលុបចោលកិច្ចសន្យា និងទទួលការសងប្រាក់វិញតាមសមាមាត្រសម្រាប់រយៈពេលដែលនៅសល់។","el":"Ο Εκμισθωτής οφείλει να διατηρεί το όχημα σε κατάσταση ασφαλούς κυκλοφορίας και λειτουργίας καθ' όλη τη διάρκεια της μίσθωσης. Αν το όχημα καταστεί άχρηστο λόγω μηχανικής βλάβης που δεν οφείλεται σε αμέλεια του Μισθωτή και ο Εκμισθωτής δεν μπορεί να το επισκευάσει ή να διαθέσει κατάλληλο όχημα αντικατάστασης εντός <strong>24 ωρών</strong> από την ειδοποίηση του Μισθωτή, ο Μισθωτής μπορεί να ζητήσει τη λύση της σύμβασης και αναλογική επιστροφή χρημάτων για το υπόλοιπο διάστημα.","es":"El Propietario debe mantener el vehículo en condiciones de circular y de uso durante todo el periodo de alquiler. Si el vehículo queda inutilizable por una avería mecánica no causada por negligencia del Arrendatario y el Propietario no puede repararlo ni facilitar un vehículo de sustitución adecuado en el plazo de <strong>24 horas</strong> desde el aviso del Arrendatario, este podrá solicitar la resolución del contrato y el reembolso proporcional del periodo no utilizado.","pt":"O Locador deve manter o veículo em condições de circulação e de utilização durante todo o período de aluguer. Se o veículo ficar inutilizável por avaria mecânica não causada por negligência do Locatário e o Locador não conseguir repará-lo nem disponibilizar um veículo de substituição adequado no prazo de <strong>24 horas</strong> após o aviso do Locatário, este pode pedir a resolução do contrato e o reembolso proporcional do período não utilizado.","it":"Il Locatore deve mantenere il veicolo in condizioni di efficienza e idoneo alla circolazione per tutto il periodo di noleggio. Se il veicolo diventa inutilizzabile per un guasto meccanico non dovuto a negligenza del Conduttore e il Locatore non riesce a ripararlo o a fornire un veicolo sostitutivo adeguato entro <strong>24 ore</strong> dalla segnalazione del Conduttore, quest'ultimo può chiedere la risoluzione del contratto e il rimborso proporzionale del periodo non goduto.","hr":"Najmodavac je dužan održavati vozilo tehnički ispravnim i spremnim za vožnju tijekom cijelog najma. Ako vozilo postane neupotrebljivo zbog mehaničkog kvara koji nije prouzročen nepažnjom Najmoprimca, a Najmodavac ga ne može popraviti ili osigurati odgovarajuće zamjensko vozilo u roku od <strong>24 sata</strong> od obavijesti Najmoprimca, Najmoprimac može zatražiti raskid ugovora i razmjerni povrat novca za neiskorišteno razdoblje.","fr":"Le Loueur doit maintenir le véhicule en état de circuler et de fonctionner pendant toute la durée de la location. Si le véhicule devient inutilisable à la suite d'une panne mécanique non imputable à la négligence du Locataire et que le Loueur ne peut ni le réparer ni fournir un véhicule de remplacement adapté dans les <strong>24 heures</strong> suivant le signalement du Locataire, celui-ci peut demander la résiliation du contrat et le remboursement au prorata de la période non utilisée.","de":"Der Vermieter hat das Fahrzeug während der gesamten Mietzeit in verkehrssicherem und betriebsbereitem Zustand zu halten. Wird das Fahrzeug durch einen technischen Defekt, den der Mieter nicht fahrlässig verursacht hat, unbenutzbar und kann der Vermieter es nicht innerhalb von <strong>24 Stunden</strong> nach Mitteilung des Mieters instand setzen oder ein geeignetes Ersatzfahrzeug stellen, kann der Mieter die Aufhebung des Vertrags und eine anteilige Erstattung für die nicht genutzte Zeit verlangen.","tr":"Kiraya Veren, kiralama süresi boyunca aracı trafiğe ve kullanıma elverişli durumda tutmakla yükümlüdür. Araç, Kiracının ihmalinden kaynaklanmayan bir mekanik arıza nedeniyle kullanılamaz hâle gelir ve Kiraya Veren, Kiracının bildiriminden itibaren <strong>24 saat</strong> içinde aracı onaramaz veya uygun bir ikame araç sağlayamazsa, Kiracı sözleşmenin feshini ve kullanılmayan süreye ait bedelin orantılı olarak iadesini talep edebilir."},
  {"th":"ข้อกำหนดนี้ไม่มีผลบังคับใช้หากการไม่สามารถใช้งานได้เกิดจากการกระทำของผู้เช่า รวมถึงอุบัติเหตุ การขับขี่ประมาท การเติมเชื้อเพลิงผิดประเภท หรือความเสียหายที่เกิดจากผู้เช่า ในกรณีดังกล่าวให้ใช้บทบัญญัติในข้อ 9 และข้อ 12","id":"Ketentuan ini tidak berlaku jika kendaraan tidak dapat digunakan karena tindakan Penyewa, termasuk kecelakaan, penggunaan yang lalai, salah mengisi bahan bakar, atau kerusakan yang disebabkan Penyewa. Dalam hal tersebut berlaku Pasal 9 dan 12.","vi":"Điều khoản này không áp dụng nếu xe không vận hành được do hành vi của Bên thuê, bao gồm tai nạn, sử dụng cẩu thả, đổ sai nhiên liệu hoặc hư hỏng do Bên thuê gây ra. Trong các trường hợp đó, áp dụng Điều 9 và Điều 12.","ms":"Fasal ini tidak terpakai jika kenderaan tidak dapat digunakan akibat tindakan Penyewa termasuk kemalangan, pemanduan cuai, bahan api yang salah, atau kerosakan yang disebabkan oleh Penyewa. Dalam keadaan sedemikian, Seksyen 9 dan 12 terpakai.","fil":"Hindi saklaw ng probisyong ito kung ang hindi paggana ay dulot ng mga kilos ng Umuupa kabilang ang aksidente, pabayang pagmamaneho, maling panggatong, o sirang dulot ng Umuupa. Sa ganitong mga kaso, ang Seksyon 9 at 12 ang umiiral.","lo":"ຂໍ້ກຳນົດນີ້ບໍ່ນຳໃຊ້ ຖ້າການບໍ່ສາມາດໃຊ້ງານໄດ້ເກີດຈາກການກະທຳຂອງຜູ້ເຊົ່າ ລວມທັງອຸບັດຕິເຫດ, ການຂັບຂີ່ປະໝາດ, ການເຕີມນ້ຳມັນຜິດປະເພດ ຫຼື ຄວາມເສຍຫາຍທີ່ເກີດຈາກຜູ້ເຊົ່າ. ໃນກໍລະນີດັ່ງກ່າວ ໃຫ້ນຳໃຊ້ຂໍ້ 9 ແລະ ຂໍ້ 12.","km":"ប្រការនេះមិនអនុវត្តទេ ប្រសិនបើការមិនអាចប្រើប្រាស់បានបណ្តាលមកពីសកម្មភាពរបស់អ្នកជួល រួមទាំងគ្រោះថ្នាក់ ការបើកបរធ្វេសប្រហែស ការចាក់ឥន្ធនៈខុស ឬការខូចខាតដែលបង្កដោយអ្នកជួល។ ក្នុងករណីនោះ ប្រការ ៩ និង ១២ ត្រូវអនុវត្ត។","el":"Η ρήτρα αυτή δεν εφαρμόζεται όταν η αδυναμία χρήσης οφείλεται σε ενέργειες του Μισθωτή, όπως ατύχημα, αμελή χρήση, λάθος καύσιμο ή ζημιά που προκάλεσε ο ίδιος. Στις περιπτώσεις αυτές εφαρμόζονται οι ενότητες 9 και 12.","es":"Esta cláusula no se aplica cuando la inutilización se deba a actos del Arrendatario, como accidentes, uso negligente, combustible equivocado o daños causados por él. En esos casos se aplican las secciones 9 y 12.","pt":"Esta cláusula não se aplica quando a inutilização resultar de atos do Locatário, incluindo acidentes, utilização negligente, combustível errado ou danos por si causados. Nesses casos aplicam-se as secções 9 e 12.","it":"La presente clausola non si applica se l'inutilizzabilità è causata dal Conduttore, compresi incidenti, uso negligente, carburante errato o danni da lui provocati. In tali casi si applicano le sezioni 9 e 12.","hr":"Ova odredba ne primjenjuje se ako je neupotrebljivost prouzročio Najmoprimac, uključujući prometne nezgode, nepažljivo korištenje, pogrešno gorivo ili oštećenja koja je sam prouzročio. U tim slučajevima primjenjuju se odjeljci 9 i 12.","fr":"Cette clause ne s'applique pas lorsque l'immobilisation résulte du fait du Locataire, notamment un accident, une utilisation négligente, une erreur de carburant ou des dommages qu'il a causés. Les sections 9 et 12 s'appliquent alors.","de":"Diese Klausel gilt nicht, wenn die Unbenutzbarkeit auf Handlungen des Mieters beruht, etwa Unfälle, fahrlässige Bedienung, falschen Kraftstoff oder vom Mieter verursachte Schäden. In diesen Fällen gelten die Abschnitte 9 und 12.","tr":"Kullanılamama hâli Kiracının kaza, ihmalkâr kullanım, yanlış yakıt veya sebep olduğu hasar gibi eylemlerinden kaynaklanıyorsa bu hüküm uygulanmaz. Bu durumda 9. ve 12. bölümler uygulanır."},
];

